    'api.schedule.exec_disabled_status' => 'exec() jest wyłączone — nie można zapytać pomocnika, który tryb jest uruchomiony.',
    'api.schedule.exec_disabled_switch' => 'exec() jest wyłączone — nie można uruchomić polecenia przełączania trybu.',
    'api.schedule.helper_failed' => 'Pomocnik zawiódł (kod :code): :out',
