    'api.schedule.mode_matches' => 'Tracker działa w trybie :actual, zgodnie z tym, co pokazuje panel.',
    'api.schedule.mode_mismatch' => 'NIEZGODNOŚĆ — panel wskazuje :panel, a tracker działa w trybie :actual. Naciśnij „Przełącz tracker teraz” albo przywróć ustawienie w panelu.',
    'api.schedule.mode_unreadable' => 'Nie udało się odczytać działającego trybu. :error',
    'api.schedule.no_output' => 'brak wyjścia',
    'api.schedule.no_switch_cmd' => 'Nie skonfigurowano polecenia przełączania trybu, więc panel nie może sprawdzić, co jest uruchomione.',
    'api.schedule.no_switch_cmd_switch' => 'Nie skonfigurowano polecenia przełączania trybu, więc panel nie może przełączyć trackera. Ustaw je w sekcji Tryb trackera i whitelista albo przełącz ręcznie na serwerze.',
    'api.schedule.now_in_mode' => 'Tracker działa teraz w trybie :mode.',
    'api.schedule.now_in_mode_confirmed' => 'Tracker działa teraz w trybie :mode (potwierdzone przez pomocnika).',
