    'api.schedule.switch_failed_short' => 'Przełączenie nie powiodło się.',
    'api.schedule.switch_wrong_mode' => 'Polecenie przełączania zakończyło się kodem 0, ale zgłasza tryb \':mode\' (oczekiwano \':wanted\').',
    'api.search.too_short' => 'Wpisz co najmniej 3 znaki (albo szesnastkowy początek info hasha).',
    'api.settings.api_bytes_budget_invalid' => 'Dzienny budżet bajtów API musi mieścić się między 0 (bez limitu) a 1 TB.',
    'api.settings.backup_cmd_invalid' => 'Nieprawidłowe polecenie pomocnika kopii zapasowych: dozwolone są tylko litery, cyfry, spacja oraz _ . / - (bez metaznaków powłoki); argumenty akcji są dopisywane automatycznie.',
    'api.settings.default_group_missing' => 'Nie ma grupy o takim slugu — wybierz istniejącą.',
    'api.settings.backup_db_name_invalid' => 'Nieprawidłowa nazwa bazy danych: tylko litery, cyfry i _.',
    'api.settings.backup_dir_rejected' => 'Katalog kopii zapasowych odrzucony: :error:hint',
    'api.settings.backup_gpg_invalid' => 'Nieprawidłowy odbiorca GPG: podaj identyfikator klucza, odcisk palca lub adres e-mail.',
    'api.settings.backup_profile_unknown' => 'Nieznany profil kopii zapasowej.',
    'api.settings.backup_schedule_invalid' => 'Nieprawidłowy harmonogram kopii zapasowych: wybierz co najmniej jeden dzień tygodnia i godzinę między 00:00 a 23:59.',
    'api.settings.backup_script_path_invalid' => 'Ścieżka do Backup-serwera.sh musi być bezwzględna i nie może zawierać metaznaków powłoki.',
    'api.settings.backup_tz_invalid' => 'Nieprawidłowa strefa czasowa kopii zapasowych. Użyj identyfikatora IANA, np. Europe/Warsaw lub UTC.',
    'api.settings.cluster_cmd_invalid' => 'Polecenie pomocnika instancji może zawierać tylko litery, cyfry, spacje oraz _ . / -',
    'api.settings.cluster_port_base_invalid' => 'Port pierwszej instancji musi mieścić się w zakresie 1024–65500 (porty poniżej 1024 należą do usług, które były tu wcześniej).',
    'api.settings.cookie_secure_mode_invalid' => 'Bezpieczne ciasteczka muszą być ustawione na Automatycznie, Zawsze albo Nigdy.',
    'api.settings.cookie_secure_needs_https' => 'Odmowa ustawienia bezpiecznych ciasteczek na Zawsze: to konkretne żądanie nie dotarło do panelu po HTTPS, a zapis zablokowałby dostęp wszystkim — przeglądarka odrzuciłaby ciasteczko sesji, więc każde logowanie kończyłoby się sukcesem, a następne kliknięcie wracało do formularza. Jeśli strona naprawdę jest serwowana po HTTPS, to serwer WWW nie mówi o tym PHP: w nginx dodaj "fastcgi_param HTTPS $https if_not_empty;" oraz "fastcgi_param REQUEST_SCHEME $scheme;" do sekcji location dla PHP, przeładuj i spróbuj ponownie.',
    'api.settings.csp_host_invalid' => '„:entry” nie jest hostem, który ten serwis wstawi do nagłówka Content-Security-Policy. Podaj nazwę hosta — opcjonalnie z https:// i jedną wiodącą gwiazdką *. — i nic więcej: bez ścieżki, bez samotnego dwukropka, bez cudzysłowów, bez słów kluczowych CSP. Ta wartość trafia do nagłówka dosłownie, więc cokolwiek innego albo zepsułoby politykę, albo po cichu by ją rozszerzyło.',
    'api.settings.csp_hosts_too_many' => 'Najwyżej :max dodatkowych hostów. Każdy z nich może uruchamiać skrypty na każdej stronie tego serwisu; dłuższa lista przestaje być polityką.',
    'api.settings.dbmem_cmd_invalid' => 'Polecenie pomocnika bazy może zawierać tylko litery, cyfry, spacje i _ . / -',
    'api.settings.hsts_needs_https' => 'Odmowa włączenia HSTS: to konkretne żądanie nie dotarło do panelu po HTTPS, więc nagłówek i tak nie mógłby zostać wysłany, a przełącznik tylko wyglądałby na włączony. Jeśli strona naprawdę jest serwowana po HTTPS, to serwer WWW nie mówi o tym PHP: w nginx dodaj "fastcgi_param HTTPS $https if_not_empty;" oraz "fastcgi_param REQUEST_SCHEME $scheme;" do sekcji location dla PHP, przeładuj i spróbuj ponownie.',
    'api.settings.hsts_preload_requires' => 'Token preload wymaga włączonego "obejmij subdomeny" oraz max-age co najmniej :age sekund (rok) — tego wymaga sama lista preload przeglądarek, a deklaracja, której nie przyjmie, jest gorsza niż jej brak. Ustaw najpierw te dwie rzeczy.',
    'api.settings.index_source_url_invalid' => 'Adres źródła indeksu musi być adresem http(s).',
    'api.settings.invalid_captcha_provider' => 'Nieprawidłowy dostawca CAPTCHA.',
    'api.settings.invalid_input' => 'Nieprawidłowe dane wejściowe',
    'api.settings.invalid_tracker_mode' => 'Nieprawidłowy tryb trackera.',
    'api.settings.login_path_taken' => 'Ten adres logowania do panelu jest już używany przez inną stronę. Wybierz inny.',
    'api.settings.login_path_too_long' => 'Adres logowania do panelu jest za długi (maks. 64 znaki).',
    'api.settings.mail_from_domain' => 'Domena nadawcy musi być domeną serwisu lub jej domeną nadrzędną (:hosts).',
    'api.settings.mail_from_invalid' => 'Adres nadawcy nie jest prawidłowym adresem e-mail.',
    'api.settings.mode_switch_cmd_invalid' => 'Nieprawidłowe polecenie przełączania trybu: dozwolone są tylko litery, cyfry, spacja oraz _ . / - (bez metaznaków powłoki); argument trybu jest dopisywany automatycznie. Zostaw puste, aby zmieniać tylko ustawienie.',
    'api.settings.net_auto_band_inverted' => 'Pasmo automatyczne jest odwrócone: maksimum (:max pps) nie może być niższe od minimum (:min pps).',
    'api.settings.net_limit_cmd_invalid' => 'Nieprawidłowe polecenie pomocnika limitu ruchu: dozwolone są tylko litery, cyfry, spacja oraz _ . / - (bez metaznaków powłoki); argumenty akcji są dopisywane automatycznie. Zostaw puste, aby wyłączyć tę funkcję.',
    'api.settings.no_valid_settings' => 'Nie podano żadnych prawidłowych ustawień',
    'api.settings.ot_cpu_affinity_invalid' => 'Przypisanie CPU musi wyglądać jak „2-5” lub „0 2 4” — lista zrozumiała dla systemd.',
    'api.settings.ot_perf_cmd_invalid' => 'Polecenie pomocnika OpenTrackera może zawierać tylko litery, cyfry, spacje, kropki, ukośniki, myślniki i podkreślenia.',
    'api.settings.ot_udp_workers_invalid' => 'Liczba wątków UDP musi być pusta (nie ruszaj) albo być liczbą od 1 do :max.',
    'api.settings.proto_header_invalid' => 'Nagłówek protokołu klienta: tylko litery, cyfry i myślniki, do 64 znaków (albo puste, żeby go ignorować).',
    'api.settings.reauth_required' => 'Te ustawienia decydują o tym, co serwer uruchamia lub komu ufa (:keys). Podaj hasło właściciela, aby potwierdzić zmianę.',
    'api.settings.saved_mode_unconfirmed' => 'Zapisano — ale panel nie zdołał potwierdzić, w którym trybie tracker faktycznie działa:detail. Sprawdź to na stronie Whitelisty, zanim na tym polegasz.',
    'api.settings.saved_tracker_not_switched' => 'Zapisano — ale TRACKER nie został przełączony. Nadal działa w trybie :actual, a panel wskazuje teraz :panel. Użyj „Przełącz tracker teraz” na stronie Whitelisty albo włącz harmonogram.',
    'api.settings.schedule_invalid' => 'Nieprawidłowy harmonogram: użyj "all", "none" lub {"from":"HH:MM","to":"HH:MM"} dla każdego dnia mon..sun (godziny 00:00–23:59).',
    'api.settings.schedule_tz_invalid' => 'Nieprawidłowa strefa czasowa harmonogramu. Użyj identyfikatora IANA, np. Europe/Warsaw lub UTC.',
    'api.settings.scrape_url_invalid' => 'Adres scrape musi być adresem http(s).',
    'api.settings.service_name_invalid' => 'Nieprawidłowa nazwa usługi trackera. Użyj tylko liter, cyfr oraz . _ @ - (np. "opentracker").',
    'api.settings.sysctl_cmd_invalid' => 'Polecenie pomocnika buforów jądra może zawierać tylko litery, cyfry, spacje oraz _ . / -',
    'api.settings.trusted_proxy_invalid' => 'Zaufane IP proxy: ":entry" nie jest adresem IP ani zakresem CIDR.',
    'api.settings.trusted_proxy_too_wide' => 'Zaufane IP proxy: ":entry" jest zbyt szeroki. Tak duży blok pozwala każdemu z jego wnętrza podać dowolny adres, przez co każdy limit, blokada i ban w panelu stałyby się zwykłym nagłówkiem. Użyj prefiksu co najmniej /:four dla IPv4 albo /:six dla IPv6 (najszersze publikowane bloki Cloudflare to /12 i /32).',
    'api.settings.whitelist_path_rejected' => 'Ścieżka whitelisty odrzucona: :error',
    'api.settings.whitelist_submit_mode_invalid' => 'Nieprawidłowy krąg osób mogących zgłaszać do whitelisty.',
    'api.stats.disabled' => 'Statystyki trackera są wyłączone',
    'api.stats.fetch_failed' => 'Nie udało się pobrać statystyk trackera. Przekroczono limit czasu połączenia lub serwer jest nieosiągalny.',
    'api.stats.invalid_xml' => 'Nieprawidłowa odpowiedź XML z trackera.',
    'api.stats.no_access' => 'Statystyki trackera nie są dostępne dla Twojego konta',
    'api.stats.no_cache' => 'Brak jeszcze zbuforowanych statystyk. Wymagane jest odświeżenie.',
    'api.stats.refresh_failed' => 'Nie udało się odświeżyć statystyk: :error',
    'api.stats.updating' => 'Statystyki trackera są aktualizowane. Spróbuj ponownie.',
    'api.stats.url_missing' => 'Adres URL statystyk trackera nie jest skonfigurowany',
    'api.stats.xml_parse_failed' => 'Nie udało się przetworzyć odpowiedzi XML z trackera.',
    'api.status.email_required' => 'Do sprawdzenia statusu zgłoszenia wymagany jest adres e-mail',
    'api.status.invalid_number' => 'Nieprawidłowy numer zgłoszenia',
    'api.status.query_required' => 'Podaj numer zgłoszenia lub info hash',
    'api.status.too_many' => 'Zbyt wiele sprawdzeń statusu. Odczekaj chwilę i spróbuj ponownie.',
    'api.sysctl.above_max' => ':label: powyżej :max.',
    'api.sysctl.adv_auto_limiter' => 'Automatyczny limiter ruchu przychodzącego jest włączony. Zaciska się, gdy rośnie obciążenie maszyny — a obsługa pakietów, które wcześniej odrzucałeś, podnosi właśnie to obciążenie, więc odczytałby tę zmianę jako przeciążenie i obniżył budżet trackera. Wyłącz go, zanim cokolwiek tu uzbroisz.',
    'api.sysctl.adv_conflicts' => 'Te klucze są ustawione także w: :files. Plik sortujący się za plikiem panelu wygrywa przy następnym starcie, więc zmiana może wyglądać na trwałą tygodniami i wyparować przy restarcie, którego nikt z nią nie połączy.',
    'api.sysctl.adv_machine' => 'Ta maszyna ma :ram pamięci i :cpus rdzeni; rozmiar strony to :page bajtów i w tym liczone jest udp_mem. Każdy limit poniżej jest sprawdzany względem tych liczb, a nie względem wartości zalecanej gdzie indziej.',
    'api.sysctl.adv_netns' => 'Ten proces działa w prywatnej przestrzeni nazw sieci, więc zapis któregokolwiek z tych kluczy zmieniłby kopię stosu sieciowego, której nic innego na maszynie nie widzi. Panel odmawia uzbrojenia stąd, zamiast raportować zmianę, która nie zaszła.',
    'api.sysctl.adv_no_systemd_run' => 'systemd-run nie jest dostępny, więc uzbrojoną zmianę mógłby cofnąć tylko timer janitora. Jeśli ten timer nie działa, nic nie przywróci starych wartości.',
    'api.sysctl.adv_one_core' => 'WSZYSTKIE pakiety przychodzące obsługuje jeden rdzeń: CPU :busiest obsłużył :pct% wszystkiego, co ta maszyna odebrała, przy :cpus rdzeniach. To karta sieciowa z jedną kolejką dostarczająca każde przerwanie do tego samego rdzenia, a :rps Wyjaśnia to objaw, którego żaden bufor nie tłumaczy: tracker wygląda na bezczynny, kolejka na CPU nigdy się nie przepełnia, a mimo to podniesienie limitu przychodzącego sprawia, że wszystko inne na maszynie się zacina — bo wszystko inne czeka za tym jednym rdzeniem.:hint',
    'api.sysctl.adv_rps_hint' => ' Rozłożenie nie wymaga restartu i działa natychmiast. Dotyczy całego systemu, jak sysctl-e obok, więc panel tego nie zapisuje.',
    'api.sysctl.adv_rps_off' => 'Receive Packet Steering jest WYŁĄCZONY (rps_cpus ma zero na każdej kolejce odbioru).',
    'api.sysctl.adv_rps_on' => 'Receive Packet Steering jest włączony, więc bardziej się tego tutaj nie rozłoży.',
    'api.sysctl.adv_socket_drops' => 'Gniazdo trackera odrzuciło :n pakietów, bo jego kolejka była pełna. To jedyna strata na tej stronie, którą poniższe bufory naprawdę mogą naprawić — pakiet odrzucony tam kosztował maszynę wszystko oprócz odpowiedzi.',
    'api.sysctl.adv_softnet_over' => 'Kolejka pakietów na CPU przepełniła się :n razy. To jedyny pomiar uzasadniający jej podniesienie — pamiętaj, że wartość jest na CPU, więc na :cpus rdzeniach się mnoży.',
    'api.sysctl.adv_softnet_zero' => 'Kolejka pakietów na CPU nigdy nie przepełniła się na tej maszynie (softnet dropped = 0 na wszystkich :cpus rdzeniach), więc jej wydłużanie nic nie da — a to zmiana, która najpewniej sprawi, że sesja SSH zacznie się zacinać, bo każdy pakiet czeka wtedy za dłuższą kolejką. Zostaw ją w spokoju.',
    'api.sysctl.adv_spread_ok' => 'Obsługa odbioru jest rozłożona na :cpus rdzeni (najbardziej obciążony ma :pct% pakietów), więc żaden pojedynczy rdzeń nie jest wąskim gardłem.',
    'api.sysctl.adv_udp_mem_fine' => 'Wszystkie gniazda UDP na tej maszynie razem używają :used stron (:used_bytes) przy progu presji :pressure stron (:pressure_bytes). Nic nie jest nawet blisko, więc podniesienie udp_mem nic by nie zmieniło — wartości krążące w poradnikach to zwykle większy ułamek RAM, niż maszyna ma.',
    'api.sysctl.adv_udp_mem_near' => 'Pamięć UDP zbliża się do progu presji (:used z :pressure stron). To pomiar, który uzasadnia podniesienie udp_mem.',
    'api.sysctl.arm_queued' => 'Zakolejkowano. Janitor zastosuje zmianę w ciągu minuty i zaplanuje automatyczne cofnięcie po :minutes min, chyba że potwierdzisz. Do tego czasu nic nie trafia do /etc, więc restart również ją cofa.',
    'api.sysctl.auto_limiter_on' => 'Automatyczny limiter ruchu przychodzącego jest włączony. Zaciska się, gdy rośnie obciążenie maszyny, a obsługa pakietów, które wcześniej odrzucałeś, podnosi właśnie je — odczytałby tę zmianę jako przeciążenie i obciął budżet trackera. Najpierw wyłącz go w Ustawieniach.',
    'api.sysctl.backlog_too_high' => 'Długość kolejki liczy się na CPU: :max na :cpus rdzeniach to już :total pakietów buforowanych przed zaporą. Nic większego nie zostanie przyjęte.',
    'api.sysctl.below_min' => ':label: poniżej :min.',
    'api.sysctl.big_step' => ':label rośnie ponad czterokrotnie w jednym kroku (z :cur do :new). Zmieniaj jedną rzecz, obserwuj, potem następną — maszyna, która dławi się po kilku zmianach naraz, nie powie ci, która była winna.',
    'api.sysctl.confirm_queued' => 'Zakolejkowano. Janitor zapisze /etc/sysctl.d/99-tracker-panel.conf w ciągu minuty i anuluje zaplanowane cofnięcie.',
    'api.sysctl.eighth_of_ram' => ':label: ponad jedna ósma RAM tej maszyny w jednym buforze gniazda — czy chodziło o KiB?',
    'api.sysctl.helper_no_answer' => 'Pomocnik nie odpowiedział.',
    'api.sysctl.key_netdev_max_backlog_label' => 'Pakiety w kolejce, zanim jądro zacznie odrzucać',
    'api.sysctl.key_netdev_max_backlog_what' => 'NA CPU. Wydłużenie tego pod zalewem nie ratuje pakietów — zapora i tak odrzuci je kilka milisekund później — sprawia tylko, że każdy inny pakiet na maszynie czeka za nimi. To pokrętło, przez które interaktywna sesja SSH zaczyna się zacinać.',
    'api.sysctl.key_rmem_default_label' => 'Bufor odbioru przydzielany każdemu gniazdu',
    'api.sysctl.key_rmem_default_what' => 'Co gniazdo dostaje bez proszenia. To ten, który kosztuje: dotyczy każdego gniazda utworzonego później, które nie ustawia własnego rozmiaru. TCP nie dotyczy — ma własne net.ipv4.tcp_rmem — więc w praktyce chodzi o UDP.',
    'api.sysctl.key_rmem_max_label' => 'Górny limit bufora odbioru',
    'api.sysctl.key_rmem_max_what' => 'Najwięcej, ile gniazdo może dostać, JEŚLI poprosi. Podniesienie samo w sobie niczego nie przydziela — różnicę zobaczy tylko program wywołujący setsockopt(SO_RCVBUF).',
    'api.sysctl.key_udp_mem_label' => 'Łączna pamięć dla UDP (min / presja / max)',
    'api.sysctl.key_udp_mem_what' => 'Limit dla WSZYSTKICH gniazd UDP razem w całej maszynie, liczony w stronach. Poniżej „min” jądro nigdy nie odzyskuje pamięci, więc min to pamięć obiecana, a nie limit; powyżej „max” odmawia. Pod zalewem jądro naprawdę weźmie tyle, ile pozwala max, a baza danych jest na tej samej maszynie.',
    'api.sysctl.key_udp_rmem_min_label' => 'Minimum odbioru gwarantowane każdemu gniazdu UDP',
    'api.sysctl.key_udp_rmem_min_what' => 'Ile gniazdo UDP zachowuje nawet wtedy, gdy powyższa pula jest pod presją. Małe i tanie; podniesienie chroni tracker przed wyciskaniem, gdy coś innego na maszynie zalewa UDP.',
    'api.sysctl.key_udp_wmem_min_label' => 'Minimum wysyłania gwarantowane każdemu gniazdu UDP',
    'api.sysctl.key_udp_wmem_min_what' => 'To samo w drugą stronę.',
    'api.sysctl.key_wmem_default_label' => 'Bufor wysyłania przydzielany każdemu gniazdu',
    'api.sysctl.key_wmem_default_what' => 'Ten sam zasięg rażenia co domyślny bufor odbioru i ten sam brak dowodów. Jeśli chcesz zatrzymać odrzucanie announce\'ów, to nie to pokrętło.',
    'api.sysctl.key_wmem_max_label' => 'Górny limit bufora wysyłania',
    'api.sysctl.key_wmem_max_what' => 'To samo co limit odbioru, tylko w drugą stronę. Żaden pomiar tutaj nigdy nie wskazał na stronę wysyłania; jest tu dla symetrii, nie jako teza.',
    'api.sysctl.need_ack' => 'Podniesienie :sysctl zmienia bufor przydzielany każdemu gniazdu utworzonemu później, nie tylko trackera. Zaznacz potwierdzenie, że o to właśnie chodziło.',
    'api.sysctl.no_systemd_run' => 'systemd-run nie jest dostępny na tej maszynie, więc automatyczne cofnięcie może wykonać tylko timer janitora. Jeśli ten timer nie działa, nic nie przywróci starych wartości. Potwierdź, że to akceptujesz.',
    'api.sysctl.no_values' => 'Brak wartości do zastosowania.',
    'api.sysctl.not_all_landed' => 'Nie każda wartość faktycznie zadziałała przy uzbrajaniu, więc utrwalenie zapisałoby coś, co nie jest prawdą. Najpierw cofnij i sprawdź wynik dla poszczególnych kluczy.',
    'api.sysctl.not_enabled' => 'Pomocnik buforów jądra nie jest skonfigurowany lub włączony (Ustawienia → Bufory sieciowe jądra).',
    'api.sysctl.not_integer' => ':label: musi być liczbą całkowitą.',
    'api.sysctl.nothing_armed' => 'Nic nie jest uzbrojone.',
    'api.sysctl.preview_failed' => 'podgląd nie powiódł się',
    'api.sysctl.private_netns' => 'Ten panel działa w prywatnej przestrzeni nazw sieci, więc zmiana trafiłaby do kopii stosu sieciowego, której nikt inny nie widzi. Odmowa zamiast sukcesu, który nic nie znaczy.',
    'api.sysctl.revert_queued' => 'Zakolejkowano. Janitor przywróci zapisane wartości w ciągu minuty — a jeśli przy uzbrajaniu zaplanowano automatyczne cofnięcie, systemd może zdążyć pierwszy.',
    'api.sysctl.run_bad_command' => 'Polecenie pomocnika zawiera niedozwolone znaki.',
