    'api.sysctl.run_no_output' => 'Pomocnik nie zwrócił żadnego wyjścia (kod :code). Sprawdź regułę sudoers.',
    'api.sysctl.udp_mem_digits' => 'Wartości udp_mem muszą być całkowitymi liczbami stron.',
    'api.sysctl.udp_mem_increasing' => 'udp_mem musi rosnąć ściśle: min < presja < max.',
    'api.sysctl.udp_mem_max_high' => 'udp_mem max jest za wysokie dla tej maszyny (:pages stron, :bytes przy :ram RAM). Pod zalewem jądro naprawdę tyle weźmie, a baza danych jest na tej samej maszynie.',
    'api.sysctl.udp_mem_min_high' => 'udp_mem min jest za wysokie dla tej maszyny (:pages stron, :bytes). Poniżej min jądro nigdy nie odzyskuje pamięci UDP, więc to pamięć obiecana na stałe, a nie limit — panel przyjmie tu najwyżej :cap stron.',
    'api.sysctl.udp_mem_pressure_high' => 'udp_mem presja jest za wysoka dla tej maszyny (maksymalnie :cap stron).',
    'api.sysctl.udp_mem_three' => 'udp_mem wymaga dokładnie trzech liczb: min, presja i max.',
    'api.sysctl.unknown_error' => 'nieznany błąd',
    'api.sysctl.verdict_clamped' => 'Ten tracker prosi o większy bufor odbioru i jest przycinany przez limit (jego gniazdo ma :rb, dokładnie dwukrotność net.core.rmem_max — jądro podwaja to, o co prosi program). Podniesienie limitu to tania poprawka: samo w sobie niczego nie przydziela i nie dotyka innych gniazd.',
    'api.sysctl.verdict_fine' => 'Ten tracker prosi o własny rozmiar bufora odbioru (:rb) i nie jest przycinany przez limit.',
    'api.sysctl.verdict_no_ask' => 'Ten tracker nigdy nie prosi jądra o większy bufor odbioru: jego gniazdo siedzi dokładnie na domyślnej wartości systemowej (:rb), a nie na dwukrotności limitu, gdzie byłoby, gdyby poprosiło. Samo podniesienie limitu nic tu więc nie zmieni — jedyne pokrętło poruszające to gniazdo to wartość domyślna, a ta dotyczy każdego gniazda na maszynie.',
    'api.sysctl.verdict_stale' => 'To gniazdo jest MNIEJSZE niż bieżąca wartość domyślna (:rb wobec :def), a żadne gniazdo tworzone teraz takie by nie było. Bufor odbioru ustala się przy otwarciu gniazda, więc tracker wciąż używa wartości obowiązującej przy ostatnim starcie — twoja zmiana działa w jądrze, ale nie dotarła do tego gniazda. ZRESTARTUJ TRACKER, a to gniazdo dostanie :def; do tego czasu licznik odrzuconych pakietów będzie rósł ze starego powodu.',
    'api.sysctl.why_rmem_default' => 'ten tracker nigdy nie prosi, więc wartość domyślna to jedyne pokrętło, które dociera do jego gniazda',
    'api.sysctl.why_rmem_max' => 'żeby nic nie przycinało programu, który prosi — teraz ani po aktualizacji',
