    'api.twofa.already_on' => 'Uwierzytelnianie dwuskładnikowe jest już włączone. Jeśli chcesz nowy sekret, najpierw je wyłącz — wtedy stary przestanie działać w chwili, gdy zacznie działać nowy.',
    'api.twofa.begin_note' => 'Nic nie jest jeszcze włączone. Dodaj klucz do aplikacji uwierzytelniającej, a potem wpisz poniżej kod z niej — to potwierdza, że klucz dotarł w całości, i dopiero wtedy coś się zmienia.',
    'api.twofa.code_required' => 'Oprócz hasła wymagany jest aktualny kod (lub kod odzyskiwania). Uwierzytelnianie dwuskładnikowe chroni na wypadek, gdyby ktoś inny znał hasło, więc samo hasło nie może go wyłączyć.',
    'api.twofa.config_not_writable' => 'Katalog config/ nie jest zapisywalny, więc sekretu nie da się zapisać. Napraw to przed rozpoczęciem: konfiguracja, której nie można zapisać, zostawiłaby Ci aplikację generującą kody do sekretu, którego ten serwer nie pamięta.',
    'api.twofa.confirm_code_wrong' => 'Ten kod jest nieprawidłowy. Sprawdź zegar na urządzeniu, które go generuje — TOTP opiera się na czasie, a telefon spóźniony o minutę generuje kody, których ten serwer nie przyjmie.',
