    'api.wl.warn_meta_heartbeat' => 'Sygnał życia workera metadanych: :age — :n hashy czeka na metadane.',
    'api.wl.warn_meta_order_mismatch' => 'Worker metadanych pobiera w kolejności „:run”, a nie „:want” ustawionej w Ustawieniach — odczytuje to ponownie mniej więcej co minutę.',
    'api.wl.warn_meta_order_unsupported' => 'Ustawienia wymagają kolejności pobierania „:want”, ale uruchomiony worker metadanych jest starszy niż ta opcja i nadal bierze najdłużej czekający hash jako pierwszy — zrestartuj tracker-metadata.',
    'api.wl.warn_regen_pending' => 'Oczekuje ponowne wygenerowanie pliku whitelisty (usunięcie/ban nie jest jeszcze odzwierciedlone w pliku).',
    'api.wl.warn_reload_pending' => 'Przeładowanie trackera oczekuje od :age — tracker nadal serwuje poprzednią whitelistę.',
    'api.wl.warn_reloads_failed' => 'Ostatnie :n przeładowania trackera nie powiodły się: :output — czy usługa działa?',
    'api.wl.warn_schedule_invalid' => 'Tryb harmonogramu jest WŁĄCZONY, ale JSON harmonogramu jest nieprawidłowy — popraw go w Ustawieniach (tryb nie zostanie przełączony).',
    'api.wl.warn_schedule_overdue' => 'Harmonogram wymaga trybu :desired, ale tracker jest w trybie :mode, a harmonogram nie był sprawdzany w ciągu ostatnich 3 minut — czy timer janitora (tools/janitor.php) działa?',
    'api.wl.warn_schedule_switch_failed' => 'Harmonogram wymaga trybu :desired, ale tracker jest w trybie :mode — ostatnie przełączenie NIE POWIODŁO SIĘ: :error',
    'apidocs.ab_already' => 'Tracker już odrzuca ten hash. Nic nie zostało zgłoszone, bo nie ma już o co prosić.',
    'apidocs.ab_blocked' => 'Zgłoszenie zostało przyjęte, a torrent natychmiast zablokowany. Nie jest już nikomu serwowany.',
    'apidocs.ab_duplicate' => 'Zgłoszenie o tym hashu jest już tutaj otwarte. <code>report_id</code> wskazuje które.',
    'apidocs.ab_invalid' => 'Nie dało się odczytać pozycji albo brakuje pola, którego ten klucz musi używać. <code>error</code> mówi którego.',
    'apidocs.ab_received' => 'Zgłoszenie zostało przyjęte i czeka na decyzję człowieka. Do tego czasu torrent pozostaje nietknięty.',
    'apidocs.abuse_intro' => 'Jedno żądanie może nieść kilka zgłoszeń. Każda pozycja wskazuje torrent przez <code>magnet</code> albo <code>hash</code>; reszta opisuje roszczenie. Pozycje są rozpatrywane pojedynczo, więc zgłoszenie, którego nie da się odczytać, nie pociąga za sobą całej paczki.',
    'apidocs.abuse_note_auto' => '<strong>Ten klucz blokuje od razu.</strong> Hash wysłany tutaj przestaje być serwowany wszystkim, którzy mają ten torrent, bez czytania zgłoszenia przez człowieka. Wysyłaj tylko to, czego jesteś pewien; jedyną drogą powrotną jest odwołanie.',
    'apidocs.abuse_note_review' => 'Zgłoszenia z tego klucza są <strong>wstrzymywane do przeglądu</strong>. Trafiają do kolejki operatora z Waszą nazwą i nic w torrencie się nie zmienia, dopóki ktoś nie zdecyduje.',
    'apidocs.abuse_reply_auto' => 'Każda pozycja wraca z informacją, co się z nią stało. <code>blocked</code> znaczy, że tracker już przestał serwować ten torrent.',
    'apidocs.abuse_reply_review' => 'Każda pozycja wraca z informacją, co się z nią stało. <code>received</code> znaczy, że jest w kolejce — nie że ktoś już ją rozpatrzył.',
    'apidocs.block_auto' => 'Blokada natychmiast, bez przeglądu',
    'apidocs.block_review' => 'Wstrzymane do przeglądu przez człowieka',
    'apidocs.h_abuse' => 'Zgłaszanie torrenta',
    'apidocs.h_abuse_reply' => 'Co wraca w odpowiedzi',
    'apidocs.k_blocking' => 'Co się dzieje ze zgłoszeniem',
    'apidocs.api_off' => 'API jest w tej chwili wyłączone na tym trackerze. Żądania będą odrzucane, dopóki operator go nie włączy.',
    'apidocs.approve_auto' => 'Automatyczne — przyjęte hashe są serwowane od razu',
    'apidocs.approve_review' => 'Z przeglądem — człowiek ogląda każde zgłoszenie, zanim tracker zacznie je serwować',
    'apidocs.auth_body' => 'Dwa nagłówki przy każdym żądaniu. Bearer to identyfikator klucza i sekret połączone kropką. Wysyłaj po HTTPS i przechowuj jak hasło — kto go ma, rejestruje hashe jako ty.',
    'apidocs.bridge_intro' => 'Wasz klucz może zalogować waszych ludzi na tym trackerze bez zakładania konta drugi raz. Dwa z czterech kroków dzieją się w przeglądarce, więc budujcie to w tej kolejności:',
    'apidocs.bridge_reverse' => 'Działa też w drugą stronę. Osoba zalogowana <em>tutaj</em> może trafić do was już zalogowana: tracker przekierowuje ją pod adres ustawiony przez operatora z <code>?thx_token=…</code>, a wasz serwer wysyła ten token na <code>v1/auth/verify</code>, żeby dowiedzieć się, kto to jest. Token jedzie w przekierowaniu; wydać go może tylko wasz klucz.',
    'apidocs.bridge_step1' => 'Ktoś zalogowany u was klika w stronę trackera. Wasz <em>serwer</em> wysyła jego id na <code>v1/auth/login</code>.',
    'apidocs.bridge_step2' => 'Odpowiedź niesie jednorazowy <code>handoff.url</code>. Przekierujcie tam przeglądarkę — tylko tak może powstać ciasteczko sesji dla tej strony.',
    'apidocs.bridge_step3' => 'Bilet zużywa się przy wejściu, żyje około dwóch minut i działa dokładnie raz. Twórzcie go w chwili kliknięcia, nigdy wcześniej.',
    'apidocs.bridge_step4' => 'Gdy wylogują się u was, wyślijcie to samo id na <code>v1/auth/logout</code>. Ich mostkowana sesja tutaj skończy się przy następnej otwartej stronie.',
    'apidocs.bridge_warning' => '<strong>Nigdy nie umieszczajcie klucza bearer w przeglądarce.</strong> Każde wywołanie tutaj robi wasz serwer. Do przeglądarki trafia bilet bezwartościowy minutę później i bezwartościowy drugi raz — na tej różnicy stoi całe bezpieczeństwo tego rozwiązania.',
    'apidocs.col_endpoint' => 'Endpoint',
    'apidocs.col_means' => 'Znaczenie',
    'apidocs.col_status' => 'Status',
    'apidocs.ep_auth_login' => 'Znajdź, powiąż albo utwórz konto stojące za waszym użytkownikiem i wydaj bilet, który go zaloguje.',
    'apidocs.ep_auth_logout' => 'Wylogował się u was. Kończy jego mostkowaną sesję tutaj.',
    'apidocs.ep_auth_merge' => 'Przypnij waszego użytkownika do konta, które już tu istnieje, albo odepnij. Nigdy nie zgaduje — bierze konkretne konto.',
    'apidocs.ep_auth_status' => 'Co tracker sądzi w tej chwili: powiązany czy nie, kiedy ostatnio przyszedł, czy wylogował się tutaj.',
    'apidocs.ep_auth_verify' => 'Wykorzystaj <code>thx_token</code>, który przysłał tracker, i dowiedz się, czyj jest.',
    'apidocs.ep_fed_export' => 'Weźcie listę, którą ten tracker chce się z wami dzielić.',
    'apidocs.ep_fed_ping' => 'Sprawdźcie, że obie strony się widzą i zgadzają co do tego, kto jest kim.',
    'apidocs.ep_users_grant' => 'Wstaw konto do grupy, na stałe albo do daty.',
    'apidocs.ep_users_lookup' => 'Czy istnieje konto o tej nazwie albo adresie?',
    'apidocs.ep_users_provision' => 'Utwórz je. Hasło wraca raz, jeśli sami go nie podacie.',
    'apidocs.ep_users_revoke' => 'Wyjmij je z powrotem.',
    'apidocs.fed_intro' => 'Wasz klucz wymienia z tym trackerem listy hashy, zamiast do niego zgłaszać.',
    'apidocs.foot' => 'Jeśli coś tutaj nie zgadza się z tym, co dostajesz, wierz odpowiedzi i powiedz operatorowi — ta strona opisuje konfigurację, a odpowiedź jest tą konfiguracją w działaniu.',
    'apidocs.h1' => 'Instrukcja integracji',
    'apidocs.h_auth' => 'Uwierzytelnianie',
    'apidocs.h_bridge' => 'Logowanie tutaj waszych użytkowników',
    'apidocs.h_curl' => 'Jedno polecenie, żeby sprawdzić, że działa',
    'apidocs.h_fed' => 'Federacja',
    'apidocs.h_check' => 'Pytanie, co się stało',
    'apidocs.check_body_auto' => 'Twój klucz publikuje prosto na tracker, więc wpis zwykle jest aktywny od razu po przyjęciu. Ten endpoint i tak odpowiada — hash może zostać później zablokowany, a uzgodnienie, które sprawdza zamiast zakładać, pozostaje poprawne.',
    'apidocs.check_body_review' => 'Twoje zgłoszenia czekają na człowieka, więc <code>pending</code> to nie koniec historii. Zapytaj ten endpoint, co się z nimi stało: zwraca decyzję, a przy odrzuceniu także notatkę, którą napisał moderator. Wyślij jeden hash w query stringu albo paczkę w treści żądania.',
    'apidocs.check_note' => 'Notatkę dostaje wyłącznie klucz, który przysłał dany wpis — była napisana do ciebie. Ktokolwiek inny pytający o ten sam hash widzi status i <code>mine: false</code>.',
    'apidocs.ck_live' => 'Serwowany przez tracker.',
    'apidocs.ck_pending' => 'Czeka na człowieka. Jeszcze nie jest serwowany.',
    'apidocs.ck_rejected' => 'Odrzucony. Nie jest serwowany; <code>review_note</code> mówi dlaczego.',
    'apidocs.ck_banned' => 'Odrzucony przez ten tracker. Ponowne wysłanie tego nie zmieni.',
    'apidocs.ck_unknown' => 'Ten tracker nie ma takiego hasha.',
    'apidocs.h_reply' => 'Odpowiedź',
    'apidocs.h_request' => 'Żądanie',
    'apidocs.h_rules' => 'Zasady, które warto znać przed napisaniem klienta',
    'apidocs.h_status' => 'Co znaczy każdy status',
    'apidocs.h_users' => 'Konta',
    'apidocs.intro' => 'Ta strona opisuje <strong>twój</strong> klucz. Adres, który dostałeś, niesie odpowiedzi wybrane dla niego przez operatora, więc to, co jest niżej, jest tym, co twój klucz naprawdę zrobi — a nie jedną stroną o wszystkich możliwościach. Samego klucza tu nie ma; przyszedł w tej samej wiadomości, od człowieka.',
    'apidocs.k_approval' => 'Zatwierdzanie',
    'apidocs.k_endpoint' => 'Endpoint',
    'apidocs.k_required' => 'Wymagane przy każdej pozycji',
    'apidocs.reply_auto' => 'Jeden wynik na pozycję, w kolejności wysyłki, plus podsumowanie. <code>added</code> znaczy, że tracker już to serwuje.',
    'apidocs.reply_review' => 'Jeden wynik na pozycję, w kolejności wysyłki, plus podsumowanie. Twój klucz przechodzi przez przegląd, więc nowy hash wraca jako <code>pending</code>: wiersz istnieje, ale tracker nie będzie go serwował, dopóki ktoś tutaj go nie zatwierdzi. Nie pokazuj tego swoim użytkownikom jako działającego.',
    'apidocs.request_body' => 'Jeden POST, jedno ciało JSON, dowolnie wiele pozycji do limitu paczki. Pozycja może być linkiem magnet albo samym 40-znakowym info hashem.',
    'apidocs.required_none' => 'nic poza hashem',
    'apidocs.required_note' => 'Twój klucz wymaga <code>:fields</code> przy każdej pozycji. Pozycja bez nich jest odrzucana jako <code>invalid</code> i nazwana w odpowiedzi — nie jest rejestrowana i ukrywana, tylko w ogóle nie jest rejestrowana.',
    'apidocs.rule_additive' => '<strong>Tylko dodawanie.</strong> Celowo nie ma endpointu usuwania — klucz, który rejestruje, nie może wyrejestrować, więc przejęty klucz nie opróżni trackera.',
    'apidocs.rule_batch' => '<strong>Paczka.</strong> Do :n pozycji na żądanie. Większa jest odrzucana w całości, a nie ucinana — nigdy nie musisz zgadywać, która połowa doszła.',
    'apidocs.rule_errors' => '<strong>Błędy.</strong> <code>401</code> brak bearera, <code>403</code> zły albo zablokowany klucz, <code>413</code> za duże ciało, <code>422</code> JSON nie w tym kształcie. Problem pojedynczej pozycji nigdy nie jest 4xx — jest statusem przy tej pozycji.',
    'apidocs.rule_idempotent' => '<strong>Idempotentne.</strong> Ponowne wysłanie tego samego hasha jest bezpieczne i daje <code>exists</code>. Nie musisz pamiętać, co już wysłałeś.',
    'apidocs.rule_limits' => '<strong>Limity tempa.</strong> Na minutę i na dobę, per klucz. Po przekroczeniu dostajesz <code>429</code> z <code>retry_after</code>; jeśli mimo to wysyłasz dalej, klucz zostaje na jakiś czas zablokowany.',
    'apidocs.st_added' => 'Zarejestrowane i serwowane.',
    'apidocs.st_banned' => 'Zablokowane na tym trackerze. Nie będzie serwowane, kto by go nie wysłał.',
    'apidocs.st_exists' => 'Ktoś już zarejestrował ten hash. Nic się nie zmieniło i to nie jest błąd.',
    'apidocs.st_invalid' => 'To nie jest użyteczny magnet ani hash, albo brakuje pola wymaganego przez twój klucz. Powód jest w <code>error</code>.',
    'apidocs.st_pending' => 'Zarejestrowane i czeka na człowieka. Jeszcze nie serwowane.',
    'apidocs.users_intro' => 'Wasz klucz może też pracować bezpośrednio na kontach. Każde z tych wywołań to POST z ciałem JSON; odpowiedź zawsze niesie <code>ok</code>.',
