    'home.about_head' => 'O trackerze',
    'home.about_open' => 'To darmowy, publiczny tracker BitTorrent działający na oprogramowaniu OpenTracker autorstwa erdgeista. Działa na Linuksie Debian od 2020 roku i obsługuje zarówno IPv4, jak i IPv6.',
    'home.about_sched' => 'To darmowy tracker BitTorrent działający na oprogramowaniu OpenTracker autorstwa erdgeista w <strong>trybie whitelisty według harmonogramu</strong>: w godzinach whitelisty (:hours) obsługuje <strong>wyłącznie zarejestrowane torrenty</strong>; poza nimi działa jako tracker otwarty. W tej chwili jest w <strong>trybie :mode</strong>. Rejestracja jest darmowa i anonimowa:reg. Działa na Linuksie Debian od 2020 roku i obsługuje zarówno IPv4, jak i IPv6.',
    'home.about_wl' => 'To darmowy tracker BitTorrent działający na oprogramowaniu OpenTracker autorstwa erdgeista w <strong>trybie whitelisty</strong>: obsługuje <strong>wyłącznie zarejestrowane torrenty</strong>. Rejestracja jest darmowa i anonimowa:reg. Działa na Linuksie Debian od 2020 roku i obsługuje zarówno IPv4, jak i IPv6.',
    'home.announce_copy' => 'Skopiuj adresy announce',
    'home.announce_extra' => 'Ten tracker działa na więcej niż jednym porcie. Dodaj do klienta <strong>wszystkie</strong> — każdy obsługuje inny proces, a użycie tylko pierwszego zostawia pozostałe bezczynne.',
    'home.announce_head' => 'Adres announce',
    'home.contact_cta' => 'Jeśli chcesz zgłosić naruszające treści, skorzystaj z naszego <a href=":url" class="report-link">[ Formularza zgłoszeń ]</a>',
    'home.contact_head' => 'Kontakt',
    'home.contact_note_a' => 'Zgłoszenia złożone przez powyższy formularz są rozpatrywane szybciej i otrzymują aktualizacje statusu. W sprawach biznesowych, propozycji współpracy lub gdy nie otrzymałeś odpowiedzi na zgłoszenie, możesz skontaktować się z nami przez ',
    'home.contact_reveal' => '[kliknij, aby pokazać kontakt]',
    'home.donate_copy' => 'Skopiuj :label',
