    'home.feat_free' => 'Usługa całkowicie darmowa',
    'home.feat_index' => 'Indeks zaobserwowanych torrentów z nazwami i listami plików, aby zgłoszenia dało się dopasować do treści',
    'home.feat_ipv6' => 'Pełna obsługa IPv4 i IPv6',
    'home.feat_languages' => 'Dostępny w więcej niż jednym języku',
    'home.feat_meta' => 'Przechowujemy metadane torrentów (nazwy / listy plików) zarejestrowanych hashy oraz adresy IP zgłaszających, aby zwalczać nadużycia; nie prowadzimy logów połączeń peerów',
    'home.feat_no_host' => 'Nie hostujemy ani nie przechowujemy żadnych treści ani plików .torrent',
    'home.feat_no_logs' => 'Nie prowadzimy logów połączeń',
    'home.feat_random_ip' => 'Do list peerów wstrzykiwane są losowe adresy IP (prywatność)',
    'home.feat_sched' => 'W godzinach whitelisty obsługiwane są wyłącznie zarejestrowane info hashe — poza nimi tracker jest otwarty',
    'home.feat_search' => 'Zalogowani mogą przeszukiwać ten indeks',
    'home.feat_transparency' => 'Publiczny raport przejrzystości z każdego żądania usunięcia',
    'home.feat_wl' => 'Obsługiwane są wyłącznie zarejestrowane info hashe — żadnych nieproszonych rojów',
