    'home.tagline' => 'Publiczny tracker BitTorrent napędzany przez OpenTracker',
    'info.a_accounts' => 'Konto jest opcjonalne — tracker działa bez niego. Odblokowuje funkcje dla zalogowanych zależnie od przypisanych grup, na przykład wyszukiwanie w indeksie albo rejestrację torrentów bez CAPTCHY. Co przechowujemy dla konta, opisuje Regulamin.',
    'info.a_data' => 'Tracker przechowuje wyłącznie aktywne roje — listę info_hashy i powiązanych z nimi peerów (IP + port). Te dane są tymczasowe i znikają, gdy sesja peera wygaśnie. Nie przechowujemy żadnych plików, nazw torrentów ani treści.',
    'info.a_data_index' => 'Indeks przechowuje dodatkowo, dla każdego zaobserwowanego hasha, nazwę torrenta i listę plików pobraną z roju — metadane, nie treść.',
    'info.a_how' => 'Klient BitTorrent wysyła do trackera żądanie „announce” z info_hashem torrenta. Tracker odpowiada listą peerów, którzy właśnie udostępniają lub pobierają ten sam torrent. Tracker zna wyłącznie: info_hash, adres IP peera i port.',
    'info.a_index' => 'Poza obsługą rojów tracker prowadzi indeks zaobserwowanych info hashy i pobiera z roju nazwę oraz listę plików każdego torrenta. Istnieje po to, by zgłoszenie z tytułem dało się dopasować do hasha, i by hash można było pokazać takim, jaki jest. Poza metadanymi nic nie jest pobierane; wpisy wygasają, gdy rój przez jakiś czas milczy.',
    'info.a_index_search' => 'Zalogowani mogą go <a href=":url">przeszukiwać</a>.',
    'info.a_ot' => 'OpenTracker to wydajne oprogramowanie trackera BitTorrent stworzone przez erdgeista. Jest open source, wyjątkowo szybkie i minimalistyczne. Obsługuje miliony połączeń przy minimalnym zużyciu zasobów.',
    'info.a_what' => 'Tracker BitTorrent to serwer, który pomaga klientom BitTorrent porozumiewać się ze sobą. Koordynuje przesyłanie plików między użytkownikami (peerami), śledząc, kto udostępnia dany torrent. Tracker nie przechowuje żadnych plików — wyłącznie informacje o aktywnych uczestnikach roju.',
    'info.a_wl' => 'Ten tracker uruchamia OpenTracker w <strong>trybie whitelisty</strong>: na announce odpowiadamy wyłącznie dla info hashy, które zostały wcześniej <strong>zarejestrowane</strong>. Torrenty publikowane na naszym forum społecznościowym rejestrują się automatycznie; każdy inny może za darmo zarejestrować link magnet lub info hash na <a href=":url">stronie whitelisty</a> (obowiązuje CAPTCHA i limity, adres IP zgłaszającego jest zapisywany w celu zwalczania nadużyć). Zarejestrowane hashe mogą zostać usunięte lub zbanowane po zgłoszeniu nadużycia. Niezarejestrowane hashe dostają pustą odpowiedź / „brak uprawnień”.',
    'info.faq_a1_open' => 'Tracker sam usuwa roje, gdy wygasną sesje wszystkich peerów. Nie decydujemy o tym, które torrenty są śledzone.',
    'info.faq_a1_wl' => 'Tak — w trybie whitelisty hash można usunąć z whitelisty (lub go tam zbanować), po czym tracker przestaje odpowiadać na announce dla niego. Skorzystaj z formularza zgłoszeń.',
    'info.faq_a2' => 'Nie. Info_hash to jedynie skrót SHA1 metadanych torrenta. Tracker nie ma żadnych informacji o zawartości plików.',
    'info.faq_a3' => 'Nie. Nie prowadzimy trwałych logów połączeń. Do list peerów wstrzykiwane są losowe adresy IP, aby chronić prywatność.',
    'info.faq_a4' => 'Ponieważ tracker nie przechowuje żadnych plików ani treści, właściciele praw powinni kontaktować się ze stroną indeksującą (np. serwisem z torrentami), a nie z trackerem. Możesz jednak złożyć zgłoszenie przez nasz formularz.',
    'info.faq_a5' => 'Nie. Tracker nie przechowuje plików .torrent. Śledzi wyłącznie aktywne połączenia peerów.',
    'info.faq_a6' => 'Tak — przełącznik w nawigacji zmienia język na czas sesji przeglądarki, a zalogowane konto może zapisać preferowany język na stronie konta.',
    'info.faq_head' => 'Najczęściej zadawane pytania',
    'info.faq_q1' => 'Czy możecie usunąć info_hash?',
