    'settings.account_email_hint1' => 'Adres <strong>Twojego własnego konta</strong> (:username) — trafiają tu powiadomienia o koncie, link weryfikacyjny i resety hasła do serwisu.',
    'settings.account_email_hint2' => 'To <em>nie</em> jest publiczny adres kontaktowy (E-mail serwisu) ani nadawca (Od) — oba znajdziesz w sekcji Kontakt i e-mail.',
    'settings.account_email_hint3' => 'Edycja uruchamia tę samą dwuetapową zmianę, jaką przechodzi użytkownik: najpierw potwierdzenie z <strong>obecnej</strong> skrzynki, potem z nowej; wyczyść pole, aby usunąć adres.',
    'settings.account_email_no_account' => 'Ten login do panelu nie ma wiersza w tabeli <code>users</code>, więc nie ma adresu do zarządzania. Utwórz użytkownika o tej samej nazwie na stronie Użytkownicy, aby go powiązać.',
    'settings.account_email_ph' => 'brak — dodaj adres',
    'settings.account_email_ph_none' => 'z tym loginem nie jest powiązane żadne konto',
    'settings.account_email_removal' => '(usunięcie)',
