    'settings.account_username' => 'Nazwa użytkownika administratora',
    'settings.account_username_hint' => 'Zmiana nazwy użytkownika wymaga podania obecnego hasła.',
    'settings.admin_access_client_ip_header' => 'Nagłówek IP klienta',
    'settings.admin_access_client_ip_header_hint' => 'Potrzebne do poprawnego limitowania per IP za Cloudflare / reverse proxy.',
    'settings.admin_access_client_ip_header_note' => '(puste = surowe IP połączenia)',
    'settings.admin_access_client_ip_header_ph' => 'np. CF-Connecting-IP lub X-Forwarded-For',
    'settings.admin_access_hidden_404' => 'Odpowiedz 404 Not Found',
    'settings.admin_access_hidden_behavior' => 'Inne adresy panelu po wylogowaniu',
    'settings.admin_access_hidden_behavior_hint' => 'Co dostaje niezalogowany gość pod adresem panelu innym niż adres logowania powyżej. Domyślnie formularz logowania nie pokazuje się nigdzie poza Twoim adresem (API wciąż odpowiada <code>401</code> na wywołania panelu, więc ukrywa to panel przed przeglądaniem, nie przed zdeterminowanym skanem).',
    'settings.admin_access_hidden_home' => 'Przekieruj na stronę główną (domyślnie)',
    'settings.admin_access_hidden_login' => 'Pokaż formularz logowania (klasycznie)',
    'settings.admin_access_lockout_attempts' => 'Próby do blokady logowania',
    'settings.admin_access_lockout_minutes' => 'Okno blokady logowania (min)',
    'settings.admin_access_login_path' => 'Adres logowania administratora',
    'settings.admin_access_login_path_hint' => 'Jedyny adres, pod którym pokazuje się ten formularz logowania. Przeniesienie go w niezgadywalne miejsce (np. <code>admin123yzxadminxxx</code>) trzyma crawlery i przypadkowe boty z dala od formularza — <em>nie</em> zastępuje to silnego hasła: API logowania ma stały adres, a prawdziwą ochroną przed brute-force jest blokada poniżej (plus <em>Przy logowaniu administratora</em> w sekcji CAPTCHA). Gdy ustawiony jest własny adres, to API dodatkowo odrzuca logowanie z sesji, która nigdy nie otworzyła tej strony. Litery, cyfry, <code>-</code> i <code>_</code>; puste lub nazwa użyta już przez inną stronę wraca do <code>admin</code>. Strony panelu zachowują zwykłe adresy (<code>?action=admin</code>, <code>?action=settings</code>, …) po zalogowaniu, więc zakładki, linki i przycisk Wyloguj działają dalej. <strong>Zapisz sobie nowy adres, zanim zapiszesz ustawienia.</strong>',
    'settings.admin_access_reauth_max_attempts' => 'Błędne potwierdzenia hasła do wylogowania',
    'settings.admin_access_reauth_max_attempts_hint' => 'Każda niebezpieczna akcja prosi o hasło ponownie. Tyle błędnych odpowiedzi <strong>wylogowuje sesję</strong> — powrót oznacza stronę logowania, z jej CAPTCHA i blokadą adresu. Każda błędna odpowiedź kosztuje też coraz więcej czasu, już od pierwszej. Bramka sesji trzyma obcych z daleka; to jest dla kogoś, kto już siedzi przy maszynie.',
    'settings.admin_access_session_absolute' => 'Bezwzględny limit sesji (godz.)',
    'settings.admin_access_session_absolute_hint' => 'Twardy limit od zalogowania, niezależnie od aktywności.',
    'settings.admin_access_session_idle' => 'Limit bezczynności sesji (min)',
    'settings.admin_access_session_idle_hint' => 'Wylogowuje administratora po tylu minutach bez aktywności.',
    'settings.admin_access_title' => 'Dostęp administratora i sesje',
    'settings.admin_access_trusted_proxy_ips' => 'Zaufane IP proxy',
    'settings.admin_access_trusted_proxy_ips_hint' => 'Nagłówek z przekazanym IP jest zaufany tylko wtedy, gdy żądanie pochodzi z wnętrza jednego z tych wpisów. Zakresy to właśnie to, co publikuje CDN — Cloudflare ma ich około trzydziestu i żadnych pojedynczych adresów. Blok szerszy niż /8 (IPv4) albo /16 (IPv6) jest tu odrzucany i ignorowany w działaniu: pozwalałby każdemu z jego wnętrza podać dowolny adres.',
    'settings.admin_access_trusted_proxy_ips_note' => '(adresy lub zakresy CIDR; rozdziela przecinek, spacja albo nowa linia. Puste, jeśli nie ma proxy)',
    'settings.admin_access_trusted_proxy_ips_ph' => 'np. 173.245.48.0/20, 2400:cb00::/32',
    'settings.api_auto_approve' => 'Zatwierdzanie',
    'settings.api_auto_approve_auto' => 'Publikuj od razu',
    'settings.api_auto_approve_review' => 'Wstrzymaj do przeglądu',
    'settings.api_ban_days' => 'Długość blokady (dni)',
    'settings.api_budgets_intro' => 'Mechanizm blokad powyżej reaguje tylko na <em>błędne</em> uwierzytelnienie. Te dwa budżety ograniczają klucz, który jest całkowicie poprawny — peera federacji pobierającego strony albo klucz, który wyciekł. Liczone są <strong>per klucz</strong> (nie per IP, więc obcy za tym samym NAT-em nie zagłodzi partnera), a przekroczenie odpowiada <code>429</code> z <code>Retry-After</code> zamiast blokady: zbyt szybkie pobieranie to błąd konfiguracji między partnerami, nie atak. Adresy z <em>IP nigdy nieblokowane</em> są z nich również zwolnione. <strong>0 wyłącza budżet.</strong>',
    'settings.api_bytes_day' => 'Bajtów dziennie',
    'settings.api_bytes_day_hint' => '0 = bez limitu. Liczy to, co <em>wysyłamy</em>, jak i to, co odbieramy, więc wyłapie rozpędzony eksport. Przechowywane w bajtach; jednostka tutaj to tylko sposób wyświetlania.',
    'settings.api_docs_copy' => 'Kopiuj link do instrukcji',
    'settings.api_docs_link' => 'Instrukcja integracji dla tego klucza',
    'settings.api_exempt_ips' => 'IP nigdy nieblokowane',
    'settings.api_exempt_ips_hint' => '(adresy IP lub CIDR po przecinku; trzymaj tu własne adresy tego serwera — forum na tym samym hoście nie może się samo zablokować)',
    'settings.api_intro' => '<code>POST v1/whitelist/submit</code> / <code>GET v1/whitelist/ping</code> z nagłówkiem <code>Authorization: Bearer key_id.secret</code> (używane przez rozszerzenie forum). <strong>Każde nieudane uwierzytelnienie z nagłówkiem Authorization blokuje IP źródłowe</strong> (IPv4 dokładnie, IPv6 per /64) na podaną niżej liczbę dni i zapisuje to żądanie. Żądania bez nagłówka dostają 401 bez blokady.',
    'settings.api_label' => 'API',
    'settings.api_managed_on' => 'Klientami (kluczami) i blokadami zarządza się na stronie',
    'settings.api_per_key' => '(per klucz)',
    'settings.api_required_fields' => 'Wymagaj przy każdej pozycji',
    'settings.api_rpm' => 'Żądań na minutę',
    'settings.api_rpm_hint' => '0 = bez limitu. Pobranie federacyjne to jedno żądanie na stronę, więc 60 to hojnie.',
    'settings.api_size_aria' => 'Rozmiar',
    'settings.api_title' => 'API serwer-serwer',
    'settings.api_unit_aria' => 'Jednostka',
    'settings.api_unit_bytes' => 'bajty',
    'settings.api_whitelist_page' => 'Whitelista',
    'settings.audit_intro' => 'Kto co zrobił w panelu. Log jest stąd celowo tylko do odczytu — zapis, który może edytować opisywany przez niego panel, nie jest zapisem. Dane uwierzytelniające nigdy do niego nie trafiają: ustawienie, które je zawiera, pojawia się jako „zmienione”, nigdy jako wartość.',
    'settings.audit_keep_days' => 'Przechowuj przez (dni)',
    'settings.audit_keep_days_hint' => 'Janitor usuwa wszystko starsze, po kilka tysięcy wierszy na przebieg.',
    'settings.audit_opt_no_record' => 'Nie rejestruj',
    'settings.audit_opt_record' => 'Rejestruj działania w panelu',
    'settings.audit_recording' => 'Rejestrowanie',
    'settings.audit_recording_hint' => 'Wyłączenie zatrzymuje nowe wpisy; nie usuwa już zapisanych.',
    'settings.audit_title' => 'Log audytu',
    'settings.backups_auto_label' => 'Automatyczna kopia',
    'settings.backups_cmd_hint' => 'Tylko litery, cyfry, spacja i <code>_ . / -</code> — bez metaznaków powłoki.',
    'settings.backups_cmd_label' => 'Polecenie pomocnika roota',
    'settings.backups_cmd_label_sub' => '(argumenty akcji są dopisywane automatycznie)',
    'settings.backups_cmd_ph' => 'np. :cmd',
    'settings.backups_custom_hint' => 'To nazwy pozycji <code>Backup-serwera.sh</code>. Inne usługi na tej maszynie (poczta, forum, pliki) mają własne pozycje — dopisz je ręcznie w polu, które pokazuje <code>--list</code> zestawu narzędzi, jeśli chcesz jednego archiwum na wszystko.',
    'settings.backups_custom_label' => 'Własny wybór',
    'settings.backups_custom_label_sub' => '(używany przez profil „Własny wybór”)',
    'settings.backups_db_hint' => 'Litery, cyfry i <code>_</code>. To także nazwa, którą trzeba wpisać, by potwierdzić przywracanie.',
    'settings.backups_db_label' => 'Baza do zrzutu / przywrócenia',
    'settings.backups_dir_hint' => 'Archiwum zawiera każde hasło do bazy na tej maszynie, więc ścieżka, którą serwer WWW mógłby serwować, jest odrzucana z miejsca.',
    'settings.backups_dir_label' => 'Katalog',
    'settings.backups_dir_label_sub' => '(poza katalogiem WWW; tworzony jako <code>0700 root</code> przy pierwszym uruchomieniu)',
    'settings.backups_dir_test_btn' => 'Test',
    'settings.backups_enabled_hint' => 'Wył. oznacza, że nic nie działa z timera. Kopię nadal można zrobić ręcznie na stronie Kopie zapasowe.',
    'settings.backups_gpg_hint' => 'Szyfrowanie <strong>kluczem publicznym</strong> (<code>gpg --encrypt --recipient</code>), bo nie wymaga hasła, a więc i terminala. Najpierw zaimportuj klucz jako root (<code>gpg --import</code>). Zostaw puste, a archiwa będą leżeć na dysku jawnie — do przyjęcia, dopóki nie opuszczają serwera, który czyta tylko root, i nie do przyjęcia w chwili, gdy skopiujesz jedno poza niego.',
    'settings.backups_gpg_label' => 'Szyfruj dla',
    'settings.backups_gpg_label_sub' => '(id klucza GPG lub e-mail; puste = bez szyfrowania)',
    'settings.backups_heading' => 'Kopie zapasowe',
    'settings.backups_intro' => 'To jest kopia zapasowa <strong>trackera</strong>. Kopia całej maszyny — poczty, forum, certyfikatów — to osobne zadanie dla zestawu narzędzi serwera i panel nie próbuje go zastąpić. Domyślnie zrzuca bazę trackera przez <code>mariadb-dump</code>. Jeśli zainstalowano tu <code>Backup-serwera.sh</code>, panel steruje <em>nim</em>, przez pomocnika roota <code>tools/opentracker/tracker-backup.sh</code> — tak, by na tej maszynie był jeden program do kopii, nie dwa — a profile poniżej zyskują jego pozycje: konfigurację, listę, unit i firewall. Przeglądanie, weryfikacja, pobieranie i przywracanie archiwów odbywa się na',
    'settings.backups_intro_after' => '; ta sekcja to polityka.<br>Nic ciężkiego nie działa nigdy w żądaniu WWW: kopia startuje odłączona i raportuje przez plik stanu, który strona odpytuje.',
    'settings.backups_intro_link' => 'stronie Kopie zapasowe',
    'settings.backups_keep_days_label' => 'Usuń starsze niż',
    'settings.backups_keep_days_label_sub' => '(dni; 0 = bez limitu)',
    'settings.backups_keep_heading' => 'Jak długo zostają',
    'settings.backups_keep_label' => 'Zachowaj najwyżej',
    'settings.backups_keep_label_sub' => '(archiwów; 0 = bez limitu)',
    'settings.backups_label' => 'Kopie zapasowe',
    'settings.backups_max_gb_hint' => 'Od najstarszych, aż katalog się zmieści. Ostatnie pozostałe archiwum nigdy nie jest usuwane — pełny dysk to źle, brak kopii to gorzej.',
    'settings.backups_max_gb_label' => 'Sufit katalogu',
    'settings.backups_max_gb_label_sub' => '(GB; 0 = bez limitu)',
    'settings.backups_nice_hint' => '15 nie pozwala zrzutowi walczyć z trackerem o CPU i dysk; pomocnik prosi też systemd o bezczynne I/O.',
    'settings.backups_nice_label' => 'Priorytet procesu',
    'settings.backups_nice_label_sub' => '(nice, 0–19)',
    'settings.backups_off' => 'Wyłączone',
    'settings.backups_on' => 'Wł. — pozwól harmonogramowi działać',
    'settings.backups_profile_hint' => '<strong>Lekka</strong> pomija <code>index_hashes</code> / <code>index_files</code> — na tej instalacji to zdecydowanie dwie największe tabele, a odbudowują się same z roju. <strong>Pełna</strong> bierze wszystko.',
    'settings.backups_profile_label' => 'Profil',
    'settings.backups_sched_at' => 'o',
    'settings.backups_sched_hint' => 'Nie zaznacz żadnego dnia, a nic nie uruchomi się automatycznie. Odpala ją timer janitora (nigdy żądanie WWW), a slot pominięty, bo maszyna była wyłączona, i tak wykona się później tego samego dnia — ale nigdy dwa razy dla tego samego slotu.',
    'settings.backups_script_hint' => 'Nie znaleziono? Panel wraca do zrzutu samej bazy trackera, a strona Kopie zapasowe o tym informuje.',
    'settings.backups_script_label' => 'Ścieżka do <code>Backup-serwera.sh</code>',
    'settings.backups_script_label_sub' => '(puste = szukaj w zwykłych miejscach)',
    'settings.backups_tools_heading' => 'Narzędzia',
    'settings.backups_tz_label' => 'Strefa czasowa',
    'settings.backups_verify_hint' => 'Archiwum, którego nikt nigdy nie odczytał, to domysł, nie kopia zapasowa.',
    'settings.backups_verify_label' => 'Sprawdzaj każde archiwum po zapisaniu',
    'settings.backups_verify_no' => 'Nie',
    'settings.backups_verify_yes' => 'Tak — suma kontrolna + odczyt zwrotny',
    'settings.backups_what_heading' => 'Co wchodzi w skład',
    'settings.backups_when_heading' => 'Kiedy',
    'settings.bridge_create' => 'Zakładanie kont',
    'settings.bridge_create_hint' => 'Wyłączone — przejdą tylko ci, którzy już mają powiązane konto.',
    'settings.bridge_enabled' => 'Mostek',
    'settings.bridge_enabled_hint' => 'Wyłączony — wszystkie pięć endpointów v1/auth/* odpowiada 503.',
    'settings.bridge_endpoints' => 'Endpointy: <code>v1/auth/login</code>, <code>v1/auth/logout</code>, <code>v1/auth/verify</code>, <code>v1/auth/merge</code>, <code>v1/auth/status</code> — wszystkie w zakresie <code>users</code>. Instrukcja integracji dla klucza jest przy samym kluczu, w panelu Whitelisty.',
    'settings.bridge_heading' => 'Mostek logowania',
    'settings.bridge_intro' => 'Jedna społeczność, dwie strony, jedno konto. Forum z kluczem API może zalogować tutaj swoich ludzi — zakładając konto przy pierwszym razie — a osoba zalogowana tutaj może trafić na forum już zalogowana. Żadna strona nie widzi hasła drugiej; przechodzi tylko jednorazowy bilet, bezwartościowy minutę później.',
    'settings.bridge_login_url' => 'Strona logowania forum',
    'settings.bridge_login_url_hint' => 'Pokazywana na formularzu logowania jako „zaloguj przez forum”. Puste = nie pokazujemy.',
    'settings.bridge_logout' => 'Wylogowanie w obie strony',
    'settings.bridge_logout_hint' => 'Wylogowanie po jednej stronie kończy mostkowaną sesję po drugiej.',
    'settings.bridge_merge' => 'Przejmowanie istniejących kont',
    'settings.bridge_merge_email' => 'Gdy adres jest tu potwierdzony',
    'settings.bridge_merge_hint' => 'Czy tożsamość z forum może przejąć lokalne konto o tym samym adresie e-mail. Domyślnie <strong>nigdy</strong>: klucz, który może podać dowolny adres, może podać adres administratora. Włącz tylko tam, gdzie każdy adres został potwierdzony na tej stronie.',
    'settings.bridge_merge_none' => 'Nigdy (zalecane)',
    'settings.bridge_return_url' => 'Dokąd prowadzi „przejdź na forum”',
    'settings.bridge_return_url_hint' => 'Forum dostaje tu <code>?thx_token=…</code> i odsyła go do <code>v1/auth/verify</code>. Puste wyłącza kierunek wychodzący.',
    'settings.bridge_ttl' => 'Ważność biletu',
    'settings.bridge_ttl_hint' => 'Sekundy. Musi przetrwać tylko jedno przekierowanie. 30–900.',
    'settings.bridge_warning' => '<strong>To najmocniejszy przełącznik na tej stronie.</strong> Przy włączonym mostku każdy, kto ma klucz z zakresem <code>users</code>, może powiedzieć „ta przeglądarka to użytkownik 412” i zostanie mu to uwierzone. Daj ten klucz forum i niczemu więcej, a gdy przestaniesz go używać — wyłącz to.',
    'settings.bulk_mail_hint_a' => 'Dodaje <strong>Napisz do członków</strong> na stronie',
    'settings.bulk_mail_hint_b' => 'wiadomość do zaznaczonych, grupy albo wszystkich. Powiadomienia w panelu działają także przy wyłączonym — ten przełącznik dotyczy <em>e-maila</em>. Domyślnie wyłączone.',
    'settings.bulk_mail_label' => 'Napisz do wszystkich (mail masowy)',
    'settings.bulk_mail_per_minute' => 'Maili masowych na minutę',
    'settings.bulk_mail_per_minute_hint' => 'Ten serwer wysyła przez <code>mail()</code> bez żadnego przekaźnika, więc sto wiadomości wychodzących naraz z domeny, która zwykle wysyła kilka, to prosta droga do zaklasyfikowania jako spam — a pierwszą ofiarą jest mail resetu hasła. Panel tylko kolejkuje; janitor wysyła tyle na minutę.',
    'settings.bulk_mail_retries' => 'Ponowienia maila masowego',
    'settings.bulk_mail_retries_hint' => 'Prób na wiadomość, zanim zostanie oznaczona jako nieudana, z coraz dłuższymi odstępami. Serwer pocztowy, który odmawia, nie chce być pytany ponownie od razu.',
    'settings.captcha_enable' => 'Włącz CAPTCHA',
    'settings.captcha_hcaptcha_secret' => 'Klucz tajny hCaptcha',
    'settings.captcha_hcaptcha_site_key' => 'Klucz witryny hCaptcha',
    'settings.captcha_heading' => 'CAPTCHA',
    'settings.captcha_intro' => 'Wybierz dostawcę i wpisz jego klucze. Przełączniki poniżej decydują, gdzie CAPTCHA jest wymagana; publiczna strona rejestracji na whitelistę wymaga jej zawsze (jest wyłączona, gdy CAPTCHA nie jest skonfigurowana).',
    'settings.captcha_on_appeal' => 'W formularzach odwołań',
    'settings.captcha_on_block_check' => 'Przy sprawdzaniu blokady',
    'settings.captcha_on_login' => 'Przy logowaniu admina',
    'settings.captcha_on_report' => 'W formularzu zgłoszenia',
    'settings.captcha_on_status' => 'Przy sprawdzaniu statusu',
    'settings.captcha_provider' => 'Dostawca',
    'settings.captcha_provider_hcaptcha' => 'hCaptcha (pole wyboru)',
    'settings.captcha_provider_recaptcha' => 'Google reCAPTCHA v2 (pole wyboru)',
    'settings.captcha_provider_recaptcha_v3' => 'Google reCAPTCHA v3 (niewidoczna, wynik)',
    'settings.captcha_recaptcha_secret' => 'Klucz tajny reCAPTCHA v2',
    'settings.captcha_recaptcha_site_key' => 'Klucz witryny reCAPTCHA v2',
    'settings.captcha_recaptcha_v3_min_score' => 'Minimalny wynik reCAPTCHA v3',
    'settings.captcha_recaptcha_v3_score_hint' => 'Wynik poniżej tej wartości → CAPTCHA niezaliczona; 0.5 to sugerowany przez Google punkt wyjścia. v3 nie ma widżetu — użytkownicy są oceniani po cichu (zamiast odznaki pod formularzami wyświetlana jest informacja „chronione przez reCAPTCHA”).',
    'settings.captcha_recaptcha_v3_secret' => 'Klucz tajny reCAPTCHA v3',
    'settings.captcha_recaptcha_v3_site_key' => 'Klucz witryny reCAPTCHA v3',
    'settings.captcha_smart_delete_attempts' => 'Nieudane próby przed CAPTCHA',
    'settings.captcha_smart_delete_attempts_hint' => 'Wymusza reCAPTCHA w oknie usuwania po tylu błędnych hasłach.',
    'settings.captcha_smart_delete_title' => 'Limity bezpieczeństwa usuwania zgłoszeń',
    'settings.captcha_smart_grace' => 'Okres karencji (minuty)',
    'settings.captcha_smart_grace_hint' => 'Po rozwiązaniu CAPTCHA pomijaj wszystkie CAPTCHA przez tyle minut.',
    'settings.captcha_smart_heading' => 'Inteligentna CAPTCHA',
    'settings.captcha_smart_intro' => 'CAPTCHA pojawia się dopiero, gdy użytkownik zbierze dość punktów aktywności. Jej rozwiązanie daje okres karencji, w którym CAPTCHA nie jest wymagana. Nieudane logowania admina zawsze zerują okres karencji.',
    'settings.captcha_smart_lockout_attempts' => 'Nieudane próby przed blokadą',
    'settings.captcha_smart_lockout_attempts_hint' => 'Blokuje usuwanie zgłoszeń po tylu błędnych hasłach.',
    'settings.captcha_smart_lockout_minutes' => 'Czas blokady (minuty)',
