    'settings.captcha_smart_points_title' => 'Punkty za akcję',
    'settings.captcha_smart_pts_appeal' => 'Odwołanie',
    'settings.captcha_smart_pts_block_check' => 'Sprawdzenie blokady',
    'settings.captcha_smart_pts_login_fail' => 'Nieudane logowanie',
    'settings.captcha_smart_pts_report' => 'Zgłoszenie',
    'settings.captcha_smart_pts_status' => 'Status zgłoszenia',
    'settings.captcha_smart_threshold' => 'Próg punktów',
    'settings.captcha_smart_threshold_hint' => 'CAPTCHA pojawia się, gdy punkty osiągną tę wartość.',
    'settings.captcha_turnstile_secret' => 'Klucz tajny Turnstile',
    'settings.captcha_turnstile_site_key' => 'Klucz witryny Turnstile',
    'settings.cluster_cmd' => 'Polecenie pomocnika',
    'settings.cluster_cmd_hint' => 'Puste = funkcja nie istnieje: żadnej karty, żadnego odpytywania, żadnego <code>sudo</code>.',
    'settings.cluster_cmd_ph' => 'np. sudo -n /usr/local/sbin/tracker-cluster.sh',
    'settings.cluster_intro_a' => 'Uruchom <strong>więcej niż jednego</strong> opentrackera na tej maszynie, na dodatkowych portach UDP, gdy jednemu naprawdę skończyło się CPU. Najpierw sprawdź',
    'settings.cluster_intro_b' => '— mówi wprost, czy to pomoże, a na większości maszyn nie pomoże: tanie pokrętła (liczba wątków, priorytet, bufory gniazd) dają niemal cały dostępny zysk przy niemal zerowym ryzyku. Instalatorowy <code>opentracker.service</code> jest <strong>nigdy nieruszany</strong>; dodatkowe instancje stają obok niego, dzielą tę samą accesslistę i ten sam tryb white/black, a ich usunięcie usuwa każdy ślad. Domyślnie wyłączone.',
    'settings.cluster_perf_card_link' => 'kartę wydajności',
    'settings.cluster_title' => 'Instancje OpenTrackera',
    'settings.confirm_body' => 'Zmieniasz limity bezpieczeństwa usuwania zgłoszeń. Podaj hasło administratora, aby potwierdzić i zastosować te zmiany.',
    'settings.confirm_body_exec' => 'Zmieniasz ustawienie, które decyduje o tym, co serwer uruchamia lub komu ufa. Podaj hasło administratora, aby potwierdzić i zastosować te zmiany.',
    'settings.confirm_cancel' => 'Anuluj',
    'settings.confirm_password' => 'Hasło administratora *',
    'settings.confirm_submit' => 'Potwierdź zmiany',
    'settings.confirm_title' => 'Potwierdź zmiany ustawień',
    'settings.content_allow_bbcode' => 'Zezwól na BBCode',
    'settings.content_allow_markdown' => 'Zezwól na Markdown',
    'settings.content_allow_markdown_hint' => 'Gdy oba włączone, wybiera piszący. Gdy oba wyłączone, BBCode nadal jest dostępny — pole opisu bez żadnej składni byłoby pułapką.',
    'settings.content_autopublish' => 'Zawsze publikuj',
    'settings.content_autopublish_hint' => 'Celowo osobno od <em>Przeglądu przed publikacją</em>: „nie moderuję” i „moderuję, ale to przepuszczam” to różne decyzje, a sklejenie ich w jeden przełącznik uniemożliwia podjęcie tej drugiej.',
    'settings.content_autopublish_yes' => 'Tak — całkowicie pomiń kolejkę',
    'settings.content_description' => 'Pole opisu',
    'settings.content_disabled' => 'Wyłączone',
    'settings.content_edit_max_pending' => 'Propozycji zmian na torrent',
    'settings.content_edit_max_pending_hint' => 'Rejestracja już istniejącego hasha z opisem <strong>proponuje zmianę</strong> zamiast cokolwiek zmieniać — każdy może zarejestrować cudzy torrent, więc pierwszy opis nie jest automatycznie tym właściwym. Propozycje pojawiają się w <strong>Whitelista &rarr; Do przeglądu &rarr; Zmiany</strong>, stary i nowy obok siebie. 0 = nie przyjmuj propozycji.',
    'settings.content_enabled' => 'Włączone',
    'settings.content_intro' => 'Dwa opcjonalne pola w formularzu rejestracji: <strong>skąd pochodzi torrent</strong> i <strong>czym jest</strong>. Pojawiają się na publicznej whitelisie, w Indeksie i w publicznej wyszukiwarce. Oba są <strong>domyślnie wyłączone</strong>, bo to tekst wpisany przez anonimowego nieznajomego, który potem publikujesz pod własną domeną — opis może zawierać obrazki, a link prowadzi tam, gdzie zdecydował autor. Z włączonym przeglądem (domyślnym po włączeniu tych pól) torrent nadal rejestruje się <em>natychmiast</em>; tylko link i opis czekają na Ciebie.',
    'settings.content_max_chars' => 'Maks. znaków',
    'settings.content_max_images' => 'Maks. obrazków',
    'settings.content_max_images_hint' => '0 = brak. Każdy obrazek to żądanie od Twojego odwiedzającego do cudzego serwera.',
    'settings.content_max_links' => 'Maks. linków',
    'settings.content_no' => 'Nie',
    'settings.content_review' => 'Przegląd przed publikacją',
    'settings.content_review_hint_link' => 'stronie Whitelista',
    'settings.content_review_hint_post' => 'Wyłączenie oznacza, że pierwszy zły opis będzie publiczny, zanim ktokolwiek go zobaczy.',
    'settings.content_review_hint_pre' => 'Wstrzymane elementy pojawiają się w zakładce <strong>Do przeglądu</strong> na',
    'settings.content_review_no' => 'Nie — publikuj od razu',
    'settings.content_review_yes' => 'Tak — wstrzymaj do przeglądu',
    'settings.content_sl_refresh' => 'Pozwól odwiedzającym odświeżać S/L',
    'settings.content_sl_refresh_hint' => 'Dodaje przycisk odświeżania w panelu Info publicznej wyszukiwarki, scrape\'ujący ten jeden hash na żywo. Domyślnie wyłączone: to przycisk zamieniający kliknięcia obcych w żądania do trackera.',
    'settings.content_sl_refresh_seconds' => 'Odstęp odświeżania (s)',
    'settings.content_sl_refresh_seconds_hint' => 'Na hash, wspólnie dla wszystkich odwiedzających. Bez tego przycisk to darmowy generator obciążenia wycelowany we własny tracker.',
    'settings.content_source_url' => 'Pole linku źródłowego',
    'settings.content_source_url_hint' => '<strong>Tylko https.</strong> Zwykłe HTTP jest odrzucane, a nie podnoszone: ta strona działa po TLS i nie może nikomu podsuwać obniżenia. Adresy prywatne i dane logowania w URL też są odrzucane.',
    'settings.content_subtitle' => 'Co mogą pisać zgłaszający i kto to sprawdza',
    'settings.content_title' => 'Opisy i linki źródłowe',
    'settings.content_trusted_domains' => 'Domeny bez ostrzeżenia',
    'settings.content_trusted_domains_hint' => 'Każdy link poza serwis prosi odwiedzającego o potwierdzenie. Te domeny (i ich subdomeny) to pomijają. Puste = ostrzegaj przy wszystkim, także własnych.',
    'settings.content_trusted_domains_ph' => 'np. tryhackx.org, files.example.org',
    'settings.content_yes' => 'Tak',
    'settings.csp_col_blocked' => 'Zablokowane',
    'settings.csp_col_directive' => 'Dyrektywa',
    'settings.csp_col_hits' => 'Razy',
    'settings.csp_col_last' => 'Ostatnio',
    'settings.csp_col_page' => 'Strona',
    'settings.csp_col_scope' => 'Gdzie',
    'settings.csp_diag_apache' => 'Ten serwer to Apache, więc czytany jest także <code>.htaccess</code>. Polityka stamtąd ma teraz postać <code>Header setifempty</code>: uzupełnia nagłówek tylko wtedy, gdy ta strona nic nie wysyła (tryb <em>Wyłączona</em>), a w trybie samego raportowania idzie pod własną nazwą i nadal egzekwuje dokładnie to, co egzekwowała dotąd. Żadna nie nadpisuje drugiej.',
    'settings.csp_diag_label' => 'To żądanie wysłałoby nagłówek:',
    'settings.csp_diag_nothing' => 'żaden — polityka jest wyłączona',
    'settings.csp_diag_panel' => 'Panel:',
    'settings.csp_diag_public' => 'Strony publiczne:',
    'settings.csp_extra_hosts' => 'Dodatkowe dozwolone hosty',
    'settings.csp_extra_hosts_hint' => 'Nazwy hostów dopisywane do <code>script-src</code>, <code>style-src</code>, <code>connect-src</code> i <code>frame-src</code> — dla skryptu analitycznego, własnego serwisu z czcionkami, własnego CDN-a. Oddzielone spacją albo przecinkiem, najwyżej dziesięć; dozwolone opcjonalne <code>https://</code> i jedna wiodąca gwiazdka <code>*.</code>, nic poza tym. <strong>Host wpisany tutaj może uruchamiać skrypty na każdej stronie tego serwisu, w sesji każdego odwiedzającego</strong>, dlatego pole prosi o hasło właściciela. Hosty dostawcy CAPTCHA dopisują się same — i to wyłącznie tego faktycznie skonfigurowanego, co jest już węższe niż dawna stała lista, dopuszczająca na każdej instalacji wszystkich czterech. jsDelivr (Bootstrap) też jest tam z automatu i nie trzeba go wpisywać.',
    'settings.csp_extra_hosts_ph' => 'cdn.example.org  https://*.example.net',
    'settings.csp_intro' => 'Reguła, którą przeglądarki stosują do każdej strony tego serwisu: z jakich źródeł wolno uruchamiać skrypty, wczytywać style, czcionki i ramki — a przede wszystkim to, że wpisany w stronę <code>&lt;script&gt;</code> uruchomi się tylko wtedy, gdy niesie jednorazowy <em>nonce</em> tego żądania. To właśnie ta część zamienia wstrzyknięty <code>&lt;script&gt;</code> w martwy tekst. Polityka powstaje tutaj, osobno dla każdego żądania, i wysyła ją PHP. Tam, gdzie serwer czyta też <code>.htaccess</code> — a ten czyta — w pliku zostaje zapasowa polityka egzekwująca, która wchodzi tylko wtedy, gdy PHP nic nie wyśle; dzięki temu przejście w tryb samego raportowania nic nie kosztuje.',
    'settings.csp_mode' => 'Tryb polityki',
    'settings.csp_mode_enforce' => 'Egzekwowanie — przeglądarka blokuje to, czego polityka zabrania',
    'settings.csp_mode_hint' => '<strong>Tylko raportowanie</strong> wysyła <code>Content-Security-Policy-Report-Only</code>: przeglądarki sprawdzają każdą stronę względem polityki i <em>niczego</em> nie blokują, więc nic się nie zepsuje. Zostaw tak na kilka dni, przeczytaj listę poniżej i dopiero wtedy przełącz na <strong>Egzekwowanie</strong>. Co naprawdę zmienia egzekwowanie: wpisany w stronę <code>&lt;script&gt;</code> bez nonce przestaje działać, tak samo każdy atrybut <code>onclick="…"</code> — nonce ich nie ratuje i dlatego dostarczane strony nie mają ani jednego. Przeczytaj też to: <strong>style wpisane w stronę są nadal dozwolone</strong> i będą, dopóki opisy budują <code>style=""</code> z tekstu autora, więc ta polityka broni przed wstrzykniętymi <em>skryptami</em>, a nie przed wstrzykniętym stylowaniem. Nic tutaj nie odetnie Ci dostępu — polityka mówi o tym, co strona może wczytać, a nie o ciasteczkach czy logowaniu — ale jeśli egzekwowanie zepsuje coś, przez co nie dojdziesz do panelu, droga powrotna to jedno polecenie na bazie trackera: <code>UPDATE settings SET value = \'report\' WHERE `key` = \'csp_mode\';</code>',
    'settings.csp_mode_off' => 'Wyłączona — aplikacja nie wysyła żadnej polityki',
    'settings.csp_mode_report' => 'Tylko raportowanie — nic nie jest blokowane (domyślnie)',
    'settings.csp_report_enabled' => 'Zbieraj raporty naruszeń',
    'settings.csp_report_enabled_hint' => 'Dodaje do polityki <code>report-uri</code>, więc przeglądarki wysyłają POST-em każde naruszenie do <code>csp-report.php</code>, a lista poniżej się zapełnia. <strong>Domyślnie wyłączone i to celowo</strong>: tryb samego raportowania nadal raportuje, ten endpoint to publiczny zapis do bazy bez uwierzytelnienia, a rozszerzenia przeglądarek wstrzykujące własne skrypty są największym źródłem raportów CSP w całym internecie — i żadne z nich nie dotyczy tego serwisu. Włącz na dzień albo dwa, gdy potrzebujesz dowodów, potem wyłącz. Raporty o adresach rozszerzeń są odrzucane przed zapisem; z zablokowanego adresu zostaje samo ŹRÓDŁO (nigdy ścieżka ani zapytanie, w którym rutynowo bywa token), a ze strony, na której doszło do naruszenia — samo <code>?action=</code>.',
    'settings.csp_report_keep_rows' => 'Ile rodzajów naruszeń pamiętać',
    'settings.csp_report_keep_rows_hint' => 'Wiersze są agregowane: jeden na <em>rodzaj</em> naruszenia (zakres + dyrektywa + zablokowane źródło) z licznikiem, więc ta liczba ogranicza, ile różnych problemów panel pamięta, a nie ile razy wystąpiły. To także granica wobec złośliwego klienta — gdy tabela ma tyle wierszy, nowy rodzaj jest odrzucany zamiast wstawiany, więc nikt jej nie rozdmucha wymyślaniem kolejnych źródeł. 0 nie pamięta niczego, a endpoint w ogóle wtedy nie zapisuje.',
    'settings.csp_reports_clear' => 'Wyczyść listę',
    'settings.csp_reports_hint' => 'Jedna linia na rodzaj naruszenia, najnowsze u góry. <em>Zablokowane</em> to źródło, do którego strona próbowała sięgnąć, albo słowo, którego specyfikacja używa zamiast adresu: <code>inline</code> oznacza skrypt lub styl wpisany w samą stronę, <code>eval</code> — kod zbudowany z tekstu. Wiersz nie zawsze znaczy, że coś jest zepsute: w trybie samego raportowania nic nie zostało zablokowane, a rozszerzenie przeglądarki potrafi wygenerować raport, który nie ma z tym serwisem nic wspólnego.',
    'settings.csp_reports_refresh' => 'Odśwież',
    'settings.csp_reports_title' => 'Co zgłosiły przeglądarki',
    'settings.csp_title' => 'Content-Security-Policy (co strona może wczytać)',
    'settings.csp_warn_hosts_dropped' => 'Te wpisy w polu <em>Dodatkowe dozwolone hosty</em> są pomijane: <code>:entries</code>. Nie są nazwami hostów, które ten serwis wstawi do nagłówka odpowiedzi, albo przekraczają limit dziesięciu. Nic z nich nie wynika — popraw je albo usuń, bo host, który wygląda na skonfigurowany, a nie jest, to typowa przyczyna zepsutego przez tygodnie widżetu.',
    'settings.dbmem_card_link' => 'Otwórz kartę na stronie Ruch.',
    'settings.dbmem_cmd' => 'Polecenie pomocnika',
    'settings.dbmem_cmd_hint' => 'Pomocnik roota instalowany z <code>tools/opentracker/tracker-dbmem.sh</code> z własną linią sudoers (patrz INSTALL). Puste = funkcja wyłączona. Po zapisie naciśnij <em>Testuj</em>.',
    'settings.dbmem_enabled' => 'Włączone',
    'settings.dbmem_enabled_hint' => 'Pokazuje kartę na stronie Ruch i pozwala janitorowi dokończyć odroczone zapisy.',
    'settings.dbmem_intro' => 'Pula buforów i pozostałe limity pamięci silnika bazy, z panelu. To, co silnik potrafi zmienić na żywo, jest zmieniane na żywo i odczytywane z powrotem; reszta trafia do pliku drop-in w /etc/mysql i czeka na restart, o który prosisz osobno. Baza na takiej maszynie jest wspólna z innymi usługami — każda liczba tutaj jest też ich.',
    'settings.dbmem_test' => 'Testuj pomocnika',
    'settings.dbmem_title' => 'Pamięć bazy danych (MariaDB / MySQL)',
    'settings.donation_field_add' => 'Dodaj pole',
    'settings.donation_field_label_ph' => 'Etykieta',
    'settings.donation_field_remove_title' => 'Usuń',
    'settings.donation_field_value_ph' => 'Adres, hash lub URL',
    'settings.donations_enabled' => 'Pokazuj dotacje',
    'settings.donations_hint' => 'Dodaj do 15 własnych pól. Adresy URL (http/https) wyświetlą się jako klikalne linki. Inne wartości (adresy portfeli, hashe) wyświetlą się jako kod do skopiowania.',
    'settings.donations_no' => 'Nie',
    'settings.donations_title' => 'Pola dotacji',
    'settings.donations_yes' => 'Tak',
    'settings.digest_enabled' => 'E-mail zbiorczy',
    'settings.digest_enabled_hint' => 'Domyślnie wyłączone.',
    'settings.digest_heading' => 'Podsumowanie dla operatora',
    'settings.digest_hours' => 'Godziny między e-mailami',
    'settings.digest_hours_hint' => 'To dolna granica, nie rozkład jazdy (1–168).',
    'settings.digest_intro' => 'Jeden e-mail do <strong>ciebie</strong> mówiący, co czeka w kolejkach: zgłoszenia partnerów wstrzymane do przeglądu, opisy czekające na przeczytanie, zgłoszenia nadużyć, których nikt nie otworzył, zgłoszone wiadomości. Wysyła go timer janitora, nigdy odsłona strony, i tylko wtedy, gdy jest w nim cokolwiek — poniższy odstęp to minimalny czas między e-mailami, więc spokojny tydzień nic nie kosztuje, a pierwsza rzecz, która pojawi się po nim, jest zgłaszana od razu, a nie na końcu odstępu, który zaczął się, gdy nie było o czym pisać.',
    'settings.digest_min' => 'Wyślij dopiero, gdy czeka tyle pozycji',
    'settings.digest_min_hint' => '0 i 1 znaczą to samo: „nigdy nie wysyłaj pustego”.',
    'settings.digest_off' => 'Bez podsumowania',
    'settings.digest_on' => 'Wysyłaj podsumowanie',
    'settings.digest_to' => 'Wyślij na adres',
    'settings.digest_to_hint' => 'Puste = adres kontaktowy strony.',
    'settings.health_heading' => 'Kontrola stanu',
    'settings.health_intro' => 'Jedna odpowiedź JSON pod <code>?action=health</code> dla monitoringu: wersja schematu, czy accesslista została zapisana i przeładowana, czy panel i faktycznie działający tracker zgadzają się co do trybu, heartbeat workera metadanych i to, co czeka w kolejkach. Zwraca <strong>503</strong>, gdy naprawdę jest źle, więc nawet monitoring rozumiejący tylko „działa/nie działa” ci powie. Bez tokenu ten adres nie istnieje — a błędny token dostaje dokładnie to samo co brak tokenu, więc sonda nie dowie się nawet, że jest tu jakiś sekret.',
    'settings.health_token' => 'Token',
    'settings.health_token_hint' => 'Co najmniej 16 znaków, inaczej liczy się jak pusty. Wysyłaj go nagłówkiem <code>X-Health-Token</code>, jeśli monitoring na to pozwala — query string trafia po drodze do każdego logu dostępu.',
    'settings.health_token_ph' => 'puste = wyłączone',
    'settings.health_url' => 'Adres do monitorowania',
    'settings.health_url_hint' => 'Wklej to do Uptime Kuma (albo czegokolwiek, co pilnuje serwera). Słowo kluczowe <code>"status":"ok"</code> wyłapie też ostrzeżenie, nie tylko awarię.',
    'settings.user2fa_all' => 'Każde konto',
    'settings.user2fa_enabled' => 'Udostępnij członkom',
    'settings.user2fa_enabled_hint' => 'Domyślnie wyłączone. Własne ustawienie dwuskładnikowe panelu jest osobne i nietknięte.',
    'settings.user2fa_heading' => 'Dwuskładnikowe dla kont',
    'settings.user2fa_intro' => 'Sześciocyfrowy kod z aplikacji uwierzytelniającej obok hasła, dla <strong>kont członków</strong> — panel ma własne od 1.14.0 i to go nie dotyka. Członkowie włączają je sobie sami na stronie konta; nikt nie włączy tego za kogoś. <strong>Wymaganie</strong> nigdy nie odmawia logowania: konto bez drugiego składnika nadal działa, a wstrzymany jest panel administracyjny. Zasada, która potrafi zamknąć komuś dostęp do własnego konta, to zasada, którą się potem wyłącza.',
    'settings.user2fa_off' => 'Nieudostępnione',
    'settings.user2fa_on' => 'Udostępnione',
    'settings.user2fa_panel' => 'Konta, które mogą otworzyć panel',
    'settings.user2fa_required' => 'Wymagaj od',
    'settings.user2fa_required_hint' => 'Domyślnie od nikogo.',
    'settings.user2fa_required_none' => 'Nikogo',
    'settings.fav_enabled' => 'Ulubione',
    'settings.fav_enabled_hint' => 'Główny włącznik. Wyłączone — gwiazdka się nie pojawia, a każdy endpoint odpowiada tak, jakby funkcji nie było.',
    'settings.fav_heading' => 'Ulubione i profile',
    'settings.fav_intro' => 'Członek może prowadzić listę ulubionych torrentów i — jeśli na to pozwolisz — pokazywać ją na publicznym profilu pod <code>?action=u&amp;name=…</code>. Wszystko tutaj jest domyślnie wyłączone; lista tego, co ktoś lubi, jest listą o nim.',
    'settings.fav_max' => 'Limit na konto',
    'settings.fav_max_hint' => 'To, co czyni strategię zapytań bezpieczną: lista jednej osoby zawsze mieści się w całości. 10–5000.',
    'settings.fav_public' => 'Publiczne listy',
    'settings.fav_public_hint' => 'Czy członek w ogóle może pokazać ulubione na swoim profilu. Każdy i tak decyduje sam, a grupa potrzebuje <code>favourites.public</code>.',
    'settings.fav_who' => '„Kto ma to w ulubionych”',
    'settings.fav_who_hint' => 'Lista w panelu Info z osobami, które dodały torrent do ulubionych. Pojawiają się tylko ci, którzy na to pozwolili — i są też pomijani w liczniku, żeby nie dało się ich wyliczyć z różnicy.',
    'settings.federation_add_peer' => 'Dodaj peera',
    'settings.federation_enabled' => 'Federacja',
    'settings.federation_enabled_off' => 'Wyłączona',
    'settings.federation_enabled_on' => 'Włączona',
    'settings.federation_exchange_hint' => 'Przebieg wymiany: każdy admin dodaje drugiego jako peera, zaznacza <em>nadaj dostęp przychodzący</em> i wysyła wygenerowany bearer drugiej stronie, która wkleja go w <em>Ich bearer</em> i włącza <em>Pull</em>. Test sprawdza kierunek wychodzący. <em>Cofnij import</em> przywraca wszystko, co wniósł peer, do stanu nierozwiązanego — hashe i ich lokalna historia zostają, znikają tylko pożyczone opisy.',
    'settings.federation_export_enabled' => 'Eksport do peerów',
    'settings.federation_export_files' => 'Eksport list plików',
    'settings.federation_export_files_no' => 'Nie (tylko nazwa/rozmiar)',
    'settings.federation_export_max_batch' => 'Wierszy na stronę eksportu',
    'settings.federation_export_max_batch_hint' => 'Liczy torrenty, nie ich zawartość — zob. dwa budżety obok.',
    'settings.federation_export_max_bytes' => 'Bajtów na stronę eksportu',
    'settings.federation_export_max_bytes_hint' => '0 = bez limitu, mierzone na łączu.',
    'settings.federation_export_max_files' => 'Rekordów plików na stronę eksportu',
    'settings.federation_export_max_files_hint' => '0 = bez limitu. Strona kończy się, gdy wyczerpie się którykolwiek z trzech budżetów, i oddaje kursor — ciężki katalog sam z siebie daje mniejsze strony.',
    'settings.federation_export_no' => 'Nie (tylko pull)',
    'settings.federation_grant_label' => 'nadaj dostęp przychodzący',
    'settings.federation_grant_title' => 'Utwórz też klucz API (zakres: federation), którym peer pobiera OD nas — pokazywany tylko raz',
    'settings.federation_import_batch_bytes' => 'Partia importu (bajty)',
    'settings.federation_import_batch_bytes_hint' => 'Partię kończy to, co zapełni się pierwsze. 33554432 = 32 MB.',
    'settings.federation_import_batch_rows' => 'Partia importu (wiersze)',
    'settings.federation_import_batch_rows_hint' => 'Wiersze, które importer trzyma przed zatwierdzeniem. Kursor przesuwa się razem z partią, więc przerwany przebieg kosztuje najwyżej tyle wierszy — nigdy naprawy.',
    'settings.federation_import_max_seconds' => 'Budżet czasu importu (s)',
    'settings.federation_import_max_seconds_hint' => 'Jeden przebieg. Reszta zostanie podjęta następnym razem — dzięki kursorowi nic to nie kosztuje.',
    'settings.federation_import_mode' => 'Ufaj przychodzącym metadanym',
    'settings.federation_import_mode_fill' => 'Od razu (fill)',
    'settings.federation_import_mode_hint' => 'W trybie przeglądu nic, co wyśle peer, nie trafia do katalogu, dopóki tego nie zaakceptujesz — czeka w kolejce poniżej. Nazwy są renderowane jako tekst, nigdy jako znaczniki, więc chodzi o <em>to, co publikujesz</em>, a nie o wstrzyknięcie skryptu. Pierwsza synchronizacja dużego peera może zaparkować dziesiątki tysięcy wierszy, więc akceptuj per peer, a nie pojedynczo.',
    'settings.federation_import_mode_review' => 'Wstrzymaj do przeglądu (kwarantanna)',
    'settings.federation_import_new' => 'Akceptuj nowe hashe',
    'settings.federation_import_new_hint' => 'Zaimportowane wiersze liczą się do limitu wierszy Indeksu.',
    'settings.federation_import_new_no' => 'Nie (tylko uzupełniaj moje zaobserwowane hashe)',
    'settings.federation_import_new_yes' => 'Tak (rozbudowuj indeks z peerów)',
    'settings.federation_intro' => 'Wymieniaj rozwiązane <strong>metadane</strong> Indeksu z innymi węzłami trackera, aby każdy budował większy katalog wyszukiwania bez ponownego pobierania z DHT. Model pull: każdy węzeł pobiera skompresowane strony JSON z <code>v1/federation/export</code> swoich peerów (klucz bearer z zakresem <em>federation</em>) i scala je przez <code>worker/federation.py</code> (timer systemd — <strong>nie</strong> czas WWW PHP; zob. <code>worker/README.md</code>). Domyślnie import tylko <em>uzupełnia metadane</em> hashy, które ten tracker sam zaobserwował; „akceptuj nowe hashe” dodaje także hashe nigdy tu nie widziane. Wymaga włączonego powyżej API S2S. Peerami zarządza się poniżej.',
    'settings.federation_loading' => 'Wczytywanie…',
    'settings.federation_no' => 'Nie',
    'settings.federation_node_name' => 'Nazwa węzła',
    'settings.federation_node_name_hint' => 'Pokazywana peerom w odpowiedziach eksportu.',
    'settings.federation_node_name_ph' => 'moj-tracker',
    'settings.federation_peer_bearer' => 'Ich bearer',
    'settings.federation_peer_bearer_note' => '(do pobierania OD nich; opcjonalnie)',
    'settings.federation_peer_name_ph' => 'inny-tracker',
    'settings.federation_peers' => 'Peery',
    'settings.federation_pull_minutes' => 'Interwał pull (min)',
    'settings.federation_pull_minutes_hint' => 'Respektowany przez <code>federation.py</code> w trybie pętli; timer systemd ma własny harmonogram.',
    'settings.federation_review_accept_peer' => 'Akceptuj całego peera',
    'settings.federation_review_accept_peer_title' => 'Akceptuj wszystko, co wciąż czeka od peera wybranego po lewej',
    'settings.federation_review_accept_sel' => 'Akceptuj zaznaczone',
    'settings.federation_review_all_peers' => 'Wszystkie peery',
    'settings.federation_review_hint' => 'Wszystko poniżej przyszło od peera, gdy <em>Ufaj przychodzącym metadanym</em> było ustawione na przegląd. Nic z tego nie jest w katalogu ani w wyszukiwarce. Akceptacja scala pakiet dokładnie tak jak zwykły import; odrzucenie zostawia notatkę, by peer nie oferował go ponownie przy każdym pull.',
    'settings.federation_review_refresh' => 'Odśwież',
    'settings.federation_review_reject_sel' => 'Odrzuć zaznaczone',
    'settings.federation_review_state_pending' => 'Oczekujące',
    'settings.federation_review_state_rejected' => 'Odrzucone',
    'settings.federation_review_th_files' => 'Pliki',
    'settings.federation_review_th_peer' => 'Peer',
    'settings.federation_review_th_resolved' => 'Rozwiązano',
    'settings.federation_review_th_size' => 'Rozmiar',
    'settings.federation_review_title' => 'Oczekuje na przegląd',
    'settings.federation_size_aria' => 'Rozmiar',
    'settings.federation_th_base_url' => 'Adres bazowy',
    'settings.federation_th_imported' => 'Zaimportowano',
    'settings.federation_th_inbound_key' => 'Klucz przychodzący',
    'settings.federation_th_last_pull' => 'Ostatni pull',
    'settings.federation_th_name' => 'Nazwa',
    'settings.federation_th_pull' => 'Pull',
    'settings.federation_th_status' => 'Status',
    'settings.federation_title' => 'Federacja / klaster',
    'settings.federation_unit_aria' => 'Jednostka',
    'settings.federation_unit_bytes' => 'bajty',
    'settings.federation_worker_mem_mb' => 'Limit pamięci importera (MB)',
    'settings.federation_worker_mem_mb_hint' => 'Twardy <code>RLIMIT_AS</code> na procesie importera. Każdy inny bezpiecznik to obietnica o arytmetyce; ten jest podłogą pod nimi — ginie proces, nie maszyna, a timer uruchamia go ponownie od ostatniej zatwierdzonej partii.',
    'settings.federation_yes' => 'Tak',
    'settings.fetch_order_building' => 'budowanie',
    'settings.fetch_order_building_title' => 'indeks potrzebny tej kolejności wciąż się buduje',
    'settings.fetch_order_intro' => 'Który oczekujący hash worker weźmie jako następny z kolejki <strong>indeksu</strong>. Przy kolejce liczonej w milionach to decyduje, o czym tracker w ogóle będzie coś wiedział przez miesiące: <em>kolejność w kolejce</em> jest sprawiedliwa, ale to też powód, dla którego wydanie dodane wczoraj stoi za milionem hashy, których nikt nie seedował od 2019. Stosowane w ciągu ~60&nbsp;s, bez restartu.',
    'settings.fetch_order_label' => 'Kolejność pobierania',
    'settings.fetch_order_live_hint' => 'Tryb to plan zapytania, nie preferencja. Ten działa na indeksie',
    'settings.fetch_order_live_label' => 'Co worker faktycznie robi',
    'settings.fetch_order_mix_hint' => 'Udziały zawsze sumują się do 100: podniesienie jednego zabiera różnicę pozostałym proporcjonalnie. Miks powtarza się co <strong>100 zajęć</strong>, przeplatanych, a nie blokami &mdash; więc 70/15/15 to nie siedemdziesiąt jednego rodzaju, a potem piętnaście następnego, i każda pojedyncza fala równoległych pobrań jest już proporcjonalną próbką. Jeden punkt to zatem jedno pobranie na sto: mało, ale nigdy zero. Notka pod każdym polem mówi, ile to daje przy powyższym ustawieniu równoległych pobrań, a to właśnie ta liczba decyduje, czy udział jest wart posiadania.',
    'settings.fetch_order_mix_reset' => 'Przywróć domyślne',
    'settings.fetch_order_mix_title' => 'Udziały w miksie',
    'settings.fetch_order_mix_wl_more' => 'Co robi udział whitelisty',
    'settings.fetch_order_mix_wl_more_body' => '<strong>0 oznacza, że whitelista zachowuje bezwzględny priorytet</strong> &mdash; opróżnia się w całości przed jakimkolwiek wierszem indeksu, dokładnie jak w każdym innym trybie i każdym wcześniejszym wydaniu, więc pozostawienie tego bez zmian niczego nie zmienia. Nadaj jej liczbę, a stanie się gwarantowanym wycinkiem rotacji: użyj tego, gdy masowy import postawił pięćdziesiąt tysięcy wierszy przed indeksem, a chcesz, żeby ruszyły oba. Slot, którego kolejka okaże się pusta, nie marnuje się &mdash; przechodzi do drugiej kolejki &mdash; więc udział to dolna granica dla whitelisty, nigdy górna granica przepustowości.',
    'settings.fetch_order_still_building' => 'indeks wciąż się buduje',
    'settings.fetch_order_title' => 'Kolejność pobierania metadanych',
    'settings.fetch_order_why' => 'Dlaczego te kolejności, a nie inne',
    'settings.fetch_order_why_1' => 'Zajęcie wiersza odbywa się przy każdym slocie pobrania &mdash; kilka razy na sekundę &mdash; więc każdy tryb tutaj musi być sortowaniem, które obsłuży <strong>istniejący indeks</strong>; wszystko inne to filesort po trzech milionach wierszy w takim tempie. Pominięte celowo:',
    'settings.fetch_order_why_2' => 'A <em>Losowo</em> to nie <code>ORDER BY RAND()</code>, który czytałby i sortował całą tabelę: info hashe to skróty SHA-1, a więc rozkładają się równomiernie w przestrzeni kluczy, zatem losowy punkt plus &bdquo;pierwszy oczekujący wiersz od tego punktu w górę&rdquo; to jedno wyszukanie w indeksie.',
    'settings.fetch_order_wl_hint' => 'Kolejka <strong>whitelisty</strong> pozostaje bez zmian: poza trybem mieszanym zawsze opróżnia się pierwsza, bo te wiersze są tam dlatego, że ktoś poprosił o nie z nazwy.',
    'settings.filelist_admin_batch' => 'Plików na żądanie (panel)',
    'settings.filelist_admin_batch_hint' => 'Ile plików pokazuje okno szczegółów, zanim zaproponuje <em>Wczytaj całą listę plików</em>. Do <strong>:max</strong> &mdash; celowo więcej niż publicznie: to operator czeka i nikt nie stoi za nim w kolejce.',
    'settings.filelist_admin_max' => 'Maksimum wczytanych plików (panel)',
    'settings.filelist_admin_max_hint' => 'Co może oznaczać <em>Wczytaj całą listę plików</em>. <strong>:max</strong> to dotychczasowe zachowanie panelu, zostawione po to, by aktualizacja niczego nie zmieniła &mdash; ale milion ścieżek to jedno <code>fetchAll</code> i jedno <code>json_encode</code> o rozmiarze setek megabajtów w php-fpm, na tej samej maszynie co baza. Zalecane jest obniżenie tej wartości.',
    'settings.filelist_admin_mode' => 'Wczytywanie (panel)',
    'settings.filelist_admin_mode_hint' => 'Ten sam wybór dla okien szczegółów w Indeksie i na Liście dozwolonych. <em>Dopiero po kliknięciu</em> to obecne zachowanie panelu: jedna partia, potem przycisk. <em>Podczas przewijania</em> dobiera resztę, gdy dojdziesz do końca drzewa. <em>Wszystko od razu</em> prosi o całą listę już przy otwarciu okna &mdash; nadal jednym żądaniem, więc tracker i tak jest odpytywany raz.',
    'settings.filelist_admin_note' => '(okna szczegółów w Indeksie i na Liście dozwolonych)',
    'settings.filelist_intro' => 'Trzy pytania, zadane dwukrotnie: jak przeglądarka prosi o więcej, ile niesie jedna odpowiedź i ile może się łącznie uzbierać na jednej stronie. Dwukrotnie, bo ktoś obcy z internetu i operator w panelu to nie ten sam odwiedzający &mdash; ten pierwszy dzieli limit liczony <strong>na adres IP</strong> ze wszystkimi za tym samym łączem, drugi nie. Tryb decyduje wyłącznie o tym, <em>kiedy</em> przeglądarka pyta; obie liczby egzekwuje serwer, więc ręcznie wpisany adres nie poprosi o więcej, niż tu ustawiono.',
    'settings.filelist_mode_all' => 'Wszystko od razu (aż do maksimum)',
    'settings.filelist_mode_button' => 'Dopiero po kliknięciu',
    'settings.filelist_mode_scroll' => 'Podczas przewijania (oraz przycisk)',
    'settings.filelist_pub_batch' => 'Plików na żądanie (wyszukiwarka)',
    'settings.filelist_pub_batch_hint' => 'Ile plików przynosi jedno żądanie. Najwyżej <strong>:max</strong> niezależnie od tego, co tu wpiszesz: 5&nbsp;000 ścieżek i rozmiarów to już blisko megabajta JSON-a z bazy współdzielonej z serwerem pocztowym, forum i hostingiem plików. Każde żądanie zużywa też jeden token limitu <em>wyszukiwania</em> &mdash; liczonego na adres IP, więc dzielą go wszyscy za jednym łączem.',
    'settings.filelist_pub_max' => 'Maksimum wczytanych plików (wyszukiwarka)',
    'settings.filelist_pub_max_hint' => 'Tu lista się kończy &mdash; również w trybie <em>Wszystko od razu</em> &mdash; a czytelnik dostaje wyjaśnienie zamiast domysłów. Sufit <strong>:max</strong>; puste pole wraca do wartości domyślnej, a to pole można tylko obniżyć.',
    'settings.filelist_pub_max_more' => 'Skąd taki sufit',
    'settings.filelist_pub_max_more_body' => 'Strony to <code>LIMIT</code>/<code>OFFSET</code> i tak zostanie, bo uprawnienie decydujące o tym, kto w ogóle wychodzi poza pierwszą stronę (<em>Wczytywanie całej listy plików</em>), jest warunkiem na tym właśnie offsecie &mdash; kursor, który uczyniłby offset nieistotnym, ominąłby przy okazji to uprawnienie. Cena jest taka, że najgłębsza dozwolona strona pobiera około :max wierszy, żeby odpowiedzieć na jedno żądanie; sufit stoi więc tam, gdzie to jeszcze da się przeżyć na współdzielonej bazie, a jego podniesienie jest zmianą w kodzie &mdash; po pomiarze, a nie przez wpisanie liczby w pole. Przed 1.38.0 nie było tu żadnego sufitu: użytkownik z tym uprawnieniem mógł przewertować torrent o 500&nbsp;000 plików do końca.',
    'settings.filelist_pub_mode' => 'Wczytywanie (publiczna wyszukiwarka)',
    'settings.filelist_pub_mode_hint' => 'Jak wypełnia się lista plików w publicznej wyszukiwarce. <em>Podczas przewijania</em> to obecne zachowanie strony. <em>Dopiero po kliknięciu</em> nigdy nie pobiera bez pytania. <em>Wszystko od razu</em> łańcuchuje żądanie za żądaniem aż do maksimum obok &mdash; przy dużym torrencie to kilkanaście żądań z tej samej puli wyszukiwań na adres IP, i dlatego nie jest to ustawienie domyślne.',
    'settings.filelist_pub_note' => '(co dostają odwiedzający)',
    'settings.filelist_title' => 'Wczytywanie listy plików',
