    'settings.group_tracker' => 'Tracker i whitelista',
    'settings.group_users' => 'Konta użytkowników',
    'settings.groups_all' => 'Wszystkie ustawienia',
    'settings.groups_aria' => 'Grupy ustawień',
    'settings.home_arrange' => 'Ułóż sekcje',
    'settings.home_badge_builtin' => 'układ wbudowany',
    'settings.home_badge_rearranged' => 'zmieniony',
    'settings.home_front_page' => 'Strona główna',
    'settings.home_intro' => 'Strona główna składa się z siedmiu sekcji. Przeciągnij je w wybranej kolejności, ukryj niepotrzebne, zmień nagłówki nad nimi — i <strong>napisz własny tekst dla dowolnej z nich</strong> albo dodaj własne sekcje. Własny tekst może wstawiać żywe elementy tam, gdzie wpiszesz <code>{{block:announce}}</code>, <code>{{torrent_count}}</code>, <code>{{register_button}}</code>… dzięki czemu Twoje słowa otaczają części, które muszą pozostać dynamiczne. Każda sekcja zachowuje własną logikę — tryb trackera nadal przepisuje „O trackerze” i „Funkcje”, widżet statystyk nadal wymaga własnego ustawienia — więc <strong>ukrycie sekcji tutaj to nie to samo, co wyłączenie jej funkcji</strong>, a przeciągnięcie jej z powrotem jej nie włącza. Edytor mówi w każdym wierszu, o który przypadek chodzi.',
    'settings.home_meta_default' => 'Sekcje w domyślnej kolejności, nic nie ukryto, nagłówki bez zmian.',
    'settings.home_meta_hidden_many' => 'ukrytych sekcji: :n',
    'settings.home_meta_hidden_one' => '1 sekcja ukryta',
    'settings.home_meta_renamed_many' => 'zmienionych nagłówków: :n',
    'settings.home_meta_renamed_one' => '1 nagłówek zmieniony',
    'settings.home_meta_reordered' => 'zmieniona kolejność',
    'settings.home_meta_tagline' => 'własny slogan',
    'settings.home_title' => 'Układ strony głównej',
    'settings.home_view' => 'Podgląd',
    'settings.homelayout_add' => 'Dodaj sekcję',
    'settings.homelayout_close' => 'Zamknij',
    'settings.homelayout_reset' => 'Przywróć wbudowany układ',
