    'settings.homelayout_tagline' => 'Wiersz pod nazwą serwisu',
    'settings.homelayout_title' => 'Układ strony głównej',
    'settings.index_enable' => 'Włącz Indeks',
    'settings.index_files_days' => '(dni)',
    'settings.index_files_keep' => 'Zachowuj listy plików',
    'settings.index_files_keep_hint' => 'Worker respektuje też <code>index_keep_files</code> we własnej konfiguracji.',
    'settings.index_files_keep_no' => 'Nie (tylko nazwa/rozmiar)',
    'settings.index_files_poll_keep' => 'Przechowuj historię odpytań',
    'settings.index_files_poll_keep_hint_1' => 'Jeden wiersz na odpytanie; stoi za wykresem <strong>pokrycia scrape\'u</strong> na',
    'settings.index_files_poll_keep_hint_2' => ': ile trackera każde odpytanie faktycznie dostarczyło. Przy odpytaniu co 30 minut to 48 wierszy dziennie &mdash; 90 dni to około 4&nbsp;300 wierszy, więc koszt jest pomijalny.',
    'settings.index_files_poll_keep_link' => 'stronie Indeksu',
    'settings.index_files_title' => 'Listy plików indeksu',
    'settings.index_grace' => 'Karencja (dni)',
    'settings.index_grace_hint' => 'Nowy hash jest po tym czasie usuwany, chyba że uda się pobrać jego metadane.',
    'settings.index_intro_1' => 'Katalog info hashy <strong>widzianych na trackerze</strong> (głównie w godzinach OPEN, gdy obsługiwany jest cały rój), do przeglądania w',
    'settings.index_intro_2' => '<strong>To nie jest whitelista</strong> &mdash; nic stąd nie jest serwowane ani zapisywane do accesslisty; to katalog tylko do odczytu z metadanymi, S/L, wyszukiwarką i akcją <em>Awansuj &rarr; whitelista</em>. Janitor odpytuje pełny scrape (<code>GET&nbsp;/scrape</code>) co <em>Interwał odpytywania</em>, zachowuje hashe mające co najmniej <em>Min. seedów</em>, a worker metadanych rozwiązuje nazwy w tle (druga kolejka, za whitelistą &mdash; wymaga uprawnień w DB, zob. <code>worker/README.md</code>). <strong>Zmierz koszt pełnego scrape\'u w godzinach OPEN, zanim włączysz to na ruchliwym trackerze.</strong>',
    'settings.index_intro_link' => 'Indeksie',
    'settings.index_max_files' => 'Zapisywanych plików na torrent',
    'settings.index_max_files_hint' => 'Ile ścieżek plików worker zapisuje dla jednego torrenta, w <strong>obu</strong> kolejkach. Puste = <code>max_files</code> z konfiguracji workera; <strong>1&ndash;:max</strong>, stosowane w ciągu ~60&nbsp;s &mdash; bez restartu.',
    'settings.index_max_files_more' => 'Czego dotyczy, a czego nie',
    'settings.index_max_files_more_body' => 'Reszta dłuższego torrenta <em>nie jest zapisywana</em>, ale jego prawdziwa liczba plików już tak &mdash; dlatego duży wpis pokazuje krótką listę pod pełną liczbą i dlatego wyszukiwanie po nazwie pliku znajdzie tylko ścieżkę, która została zapisana. Dotyczy torrentów pobieranych <strong>od teraz</strong>: już zapisane listy zachowują swoją długość, dopóki dany wiersz nie zostanie rozwiązany ponownie. Nie robi nic dla wierszy indeksu, gdy <em>Zachowuj listy plików</em> jest ustawione na Nie, i <strong>nie</strong> rządzi listami zaimportowanymi od peera federacji &mdash; te mają własne limity federacji (5&nbsp;000 na wiersz, 2&nbsp;000 w kolejce recenzji), bo skracanie listy, którą peer przysłał w całości, nikomu nie pomaga. Podniesienie tej wartości zwielokrotnia liczbę wierszy zapisywanych właśnie dla największych torrentów, a każdy z nich trafia do indeksu FULLTEXT w bazie współdzielonej z serwerem pocztowym, forum i hostingiem plików: zmierz, zanim podniesiesz ją znacząco.',
    'settings.index_max_files_note' => '(puste = konfiguracja workera)',
    'settings.index_max_files_ph' => 'np. 5000',
    'settings.index_max_rows' => 'Maks. wierszy (limit)',
    'settings.index_max_rows_hint' => 'Powyżej tego limitu najstarsze niechronione wiersze są usuwane.',
    'settings.index_meta_auto' => 'Automatyczne kolejkowanie metadanych',
    'settings.index_meta_auto_hint' => 'Gdy włączone, każdy zaobserwowany hash bez metadanych trafia do kolejki automatycznie (rozłożone na ~1&nbsp;h, najlepiej seedowane najpierw), a budżet dzienny jest <strong>ignorowany</strong>. Uważaj na obciążenie DHT przy dużym indeksie.',
    'settings.index_meta_auto_no' => 'Nie (tylko budżet dzienny)',
    'settings.index_meta_auto_yes' => 'Tak (kolejkuj każdy nowy hash)',
    'settings.index_meta_budget' => 'Budżet metadanych (na dzień)',
    'settings.index_meta_budget_hint' => 'Liczba wierszy kolejkowanych do pobrania metadanych dziennie, rozłożona na 24&nbsp;h. 0 = nigdy nie pobieraj automatycznie.',
    'settings.index_min_seeders' => 'Min. seedów do indeksowania',
    'settings.index_min_seeders_hint' => 'Odcina ogon martwych rojów. 1 = co najmniej jeden seed.',
    'settings.index_no' => 'Nie',
    'settings.index_poll_budget' => 'Budżet czasu odpytania (s)',
    'settings.index_poll_budget_hint' => 'Limit czasu zegarowego na jedno odpytanie; ogromny scrape jest przetwarzany częściowo.',
    'settings.index_poll_interval' => 'Interwał odpytywania (min)',
    'settings.index_poll_interval_hint' => '5&ndash;1440. Limit modest-fullscrape w OpenTrackerze to 5&nbsp;min/IP.',
    'settings.index_protect' => 'Ochrona (dni)',
    'settings.index_protect_hint' => 'Hash z metadanymi żyje tyle dni; okres jest przedłużany, dopóki wciąż ma seedów.',
    'settings.index_source_url' => 'Adres źródła pełnego scrape\'u',
    'settings.index_source_url_hint' => 'OpenTracker <code>/scrape</code> bez info_hash = pełny scrape. Zalecany localhost.',
    'settings.index_title' => 'Indeks (zaobserwowane hashe)',
    'settings.index_worker_conc' => 'Równoległe pobrania workera',
    'settings.index_worker_conc_hint' => 'Ile hashy worker rozwiązuje jednocześnie, łącznie w obu kolejkach. <strong>1&ndash;64</strong>, stosowane w ciągu ~60&nbsp;s &mdash; bez restartu.',
    'settings.index_worker_conc_more' => 'Ile to kosztuje',
    'settings.index_worker_conc_more_body' => 'Każde pobranie to jeden uchwyt libtorrent utrzymujący niewielki zestaw połączeń DHT i peerów, więc sufitem są tu deskryptory plików i pamięć, nie libtorrent: przy górnej granicy spodziewaj się kilkuset gniazd, kilkuset MB i odpowiadającego im ruchu wychodzącego. Podnoś tę wartość dlatego, że maszyna ma zapas mocy, a nie dlatego, że taka liczba jest dostępna.',
    'settings.index_worker_conc_note' => '(puste = konfiguracja workera)',
    'settings.index_worker_conc_ph' => 'np. 8',
    'settings.index_yes' => 'Tak',
    'settings.iplists_capacity_hint' => '<strong>Sieć, nie adres.</strong> Plik strefy Chin z ipdeny ma <strong>8&nbsp;810</strong> wierszy i obejmuje <strong>343&nbsp;miliony</strong> adresów — ten sufit mieści więc około <strong>28 krajów tej wielkości</strong>, a zablokowanie jednego kosztuje 3&nbsp;% z niego. Limit dotyczy zestawu reguł, który nftables ładuje jako jedną transakcję; nie ogranicza tego, jak dużą część internetu możesz odrzucić. Każda lista pokazuje obie liczby na',
    'settings.iplists_capacity_hint_link' => 'stronie Ruch',
    'settings.iplists_capacity_label' => 'Ile to pomieści',
    'settings.iplists_capacity_value' => ':n sieci',
    'settings.iplists_enabled_hint' => 'Wył. usuwa zestawy z firewalla bez kasowania czegokolwiek, co zaimportowano. Listy żyją w tabeli limitu ruchu przychodzącego, więc limit (albo liczniki) musi działać, żeby w ogóle zostały załadowane.',
    'settings.iplists_heading' => 'Listy adresów (zezwól / blokuj)',
    'settings.iplists_intro' => '<strong>Zaufane adresy</strong> powyżej to pole, w które wpisujesz garść adresów. Tu ten sam pomysł w skali potrzebnej operatorowi: całe sieci, całe kraje, trzymane w pliku lub pobierane z URL-a takiego jak <code>ipdeny.com/ipblocks/data/countries/cn.zone</code> i odświeżane cyklicznie. Same listy zarządzane są na',
    'settings.iplists_intro_after' => '— tu jest tylko główny przełącznik i domyślny interwał odświeżania.',
    'settings.iplists_intro_link' => 'stronie Ruch',
    'settings.iplists_kinds' => 'Trzy rodzaje, stosowane w tej kolejności: <strong>zezwól</strong> nigdy nie jest odrzucane, cokolwiek mówi reszta; <strong>blokuj</strong> jest odrzucane zawsze; <strong>blokuj pod obciążeniem</strong> jest odrzucane tylko wtedy, gdy maszyna jest zajęta — te adresy dostają budżet pięć razy mniejszy niż pozostali, więc w spoczynku nikt ich nie rusza, a pod obciążeniem odpadają pierwsze. Cokolwiek wpiszesz w Zaufane adresy, wygrywa z każdą listą.',
    'settings.iplists_label' => 'Listy adresów',
    'settings.iplists_off' => 'Wył. — firewall nie niesie żadnych list',
    'settings.iplists_on' => 'Wł. — egzekwuj włączone listy',
    'settings.iplists_ttl_hint' => 'Wartość domyślna proponowana przy dodawaniu listy z URL-a; każda lista trzyma własną. 720 to dwanaście godzin. Strefa kraju zmienia się kilka razy w roku, więc pobieranie jej częściej jest nieuprzejme wobec tego, kto ją hostuje.',
    'settings.iplists_ttl_label' => 'Odświeżaj pobrane listy co',
    'settings.iplists_ttl_label_sub' => '(minuty)',
