    'settings.langdup_cancel' => 'Anuluj',
    'settings.langdup_code' => 'Nowy kod',
    'settings.langdup_code_hint' => 'Dwie lub trzy litery, np. <code>de</code>, <code>fr</code>, <code>ast</code>.',
    'settings.langdup_intro_after' => 'zostaną skopiowane pod nowy kod. Kopia startuje jako <strong>wyłączona</strong>, więc można ją dokończyć, zanim ktokolwiek ją zobaczy.',
    'settings.langdup_intro_before' => 'Wszystkie teksty z',
