    'settings.languages_auto_check' => 'Użyj <code>Accept-Language</code>, gdy nikt nic nie wybrał',
    'settings.languages_auto_hint' => 'Tylko w obrębie „dla kont” i tylko wtedy, gdy nie ma zapisanego wyboru. Ustawienie języka strony na <em>Automatyczny</em> robi to samo w bardziej czytelny sposób.',
    'settings.languages_col_accounts' => 'Dla kont',
    'settings.languages_col_accounts_title' => 'Użytkownik może przypiąć go do konta; z tego wybiera też automatyczne dopasowanie',
    'settings.languages_col_completeness' => 'Kompletność',
    'settings.languages_col_language' => 'Język',
    'settings.languages_col_offered' => 'Oferowany',
