    'settings.languages_col_switcher' => 'W przełączniku',
    'settings.languages_col_switcher_title' => 'Pokazywany w przełączniku w nagłówku',
    'settings.languages_col_vs' => 'względem',
    'settings.languages_default' => 'Język strony',
    'settings.languages_default_hint' => 'To, co dostaje odwiedzający, zanim cokolwiek wybierze. Własny wybór zalogowanego konta oraz jawne <code>?lang=</code> mają pierwszeństwo.',
    'settings.languages_download_template' => 'Pobierz plik angielski do tłumaczenia',
    'settings.languages_install' => 'Zainstaluj język',
    'settings.languages_intro1' => 'Panel dostarczany jest z językiem <strong>angielskim</strong> i <strong>polskim</strong>. Każdy plik wrzucony do <code>lang/</code> jest językiem — zainstaluj go poniżej z eksportu JSON albo skopiuj istniejący i edytuj kopię. Klucz, którego brakuje w tłumaczeniu, wraca do angielskiego, więc częściowe tłumaczenie degraduje się do czytelnego angielskiego, a nie do pustych miejsc.',
    'settings.languages_intro2' => '<strong>Trzy listy i to nie jest to samo pytanie.</strong> <em>Oferowany</em> decyduje, które języki w ogóle istnieją dla odwiedzających; <em>w przełączniku</em> decyduje, które pokazuje kontrolka w nagłówku; <em>dla kont</em> decyduje, które użytkownik może przypiąć do konta — i z tego zbioru wybiera też automatyczne dopasowanie do przeglądarki. Język pominięty w dwóch ostatnich listach nadal jest dostępny przez jawny link <code>?lang=</code>: ukrycie kontrolki to nie to samo, co wycofanie tłumaczenia.',
    'settings.languages_not_writable' => 'Katalog <code>lang/</code> nie jest zapisywalny dla użytkownika serwera WWW, więc instalowanie lub kopiowanie języka się nie uda. Na Debianie: <code>sudo chown www-data lang</code>.',
    'settings.languages_swap' => 'Przełączaj bez przeładowania',
    'settings.languages_swap_hint' => 'Przełącznik pobiera tę stronę w drugim języku i podmienia tekst w miejscu, więc nic się nie przesuwa i nic nie ginie. Gdy cokolwiek zawiedzie — brak JavaScriptu, brak sieci, wygasła sesja — przeglądarka po prostu wczytuje stronę, czyli robi to, co dziś. Kilka komunikatów wbudowanych w stronę przy renderze zostaje w starym języku do następnego pełnego wczytania.',
    'settings.languages_title' => 'Języki',
    'settings.langup_cancel' => 'Anuluj',
    'settings.langup_drop_aria' => 'Wybierz lub upuść plik JSON',
    'settings.langup_drop_choose' => 'Wybierz plik',
    'settings.langup_drop_or' => 'lub upuść go tutaj',
    'settings.langup_drop_sub' => 'Plik JSON z parami "klucz": "tekst" — wyeksportuj jeden powyżej, aby od niego zacząć.',
    'settings.langup_or_code' => 'lub kod:',
    'settings.langup_pick' => 'Wybierz język…',
    'settings.langup_step1' => 'Zacznij od istniejącego pliku',
    'settings.langup_step1_text' => 'Pobierz z tabeli angielski (lub dowolny zainstalowany język), przetłumacz wartości i zostaw klucze dokładnie takie, jakie są — zmieniony klucz to tekst, który wróci do angielskiego.',
