    'settings.limits_zero_off' => '(0 = wył.)',
    'settings.limits_zero_unlimited' => '(0 = bez limitu)',
    'settings.livesync_bind_ip' => 'Ta maszyna, wewnątrz tunelu',
    'settings.livesync_bind_ip_hint' => 'Prywatny adres na interfejsie tunelu. Publiczny jest odrzucany.',
    'settings.livesync_bind_ip_ph' => 'np. 10.9.0.1',
    'settings.livesync_cmd' => 'Polecenie pomocnika',
    'settings.livesync_cmd_hint' => 'Puste = funkcja nie istnieje: żadnej karty, odpytywania ani <code>sudo</code>.',
    'settings.livesync_cmd_ph' => 'np. sudo -n /usr/local/sbin/tracker-livesync.sh',
    'settings.livesync_enabled' => 'Włączone',
    'settings.livesync_enabled_hint' => 'Włączenie pokazuje tylko kartę; uzbrojenie to osobna, potwierdzana hasłem czynność na',
    'settings.livesync_enabled_hint_link' => 'stronie Ruch',
    'settings.livesync_intro_p1' => 'Dwa opentrackery na <strong>dwóch maszynach</strong> mówiące sobie nawzajem na żywo, kto jest w którym roju. To <em>nie</em> federacja: federacja przenosi metadane między panelami po HTTPS z kluczem, to przenosi same peery między trackerami. Żadne nie zastępuje drugiego, a na jednej maszynie nie robi to zupełnie nic — nie ma z kim się synchronizować. <strong>Domyślnie wyłączone.</strong>',
    'settings.livesync_intro_p2' => '<strong>Protokół nie ma uwierzytelniania ani szyfrowania.</strong> Cokolwiek dosięgnie portu, może wstrzyknąć peery do każdego roju obsługiwanego przez ten tracker, dlatego pomocnik <strong>odmawia</strong> uzbrojenia, jeśli adres nie należy do interfejsu tunelu. Celowo nie ma od tego wyjątku. Panel nie konfiguruje też za Ciebie WireGuarda — wygenerowanie klucza prywatnego i zapisanie go w <code>/etc</code> to większa ingerencja w maszynę niż cokolwiek innego tutaj, a robiłby to nie widząc drugiego końca. Naciśnij <strong>Test</strong>, a wypisze polecenia.',
    'settings.livesync_no' => 'Nie',
    'settings.livesync_peer_ip' => 'Drugi tracker, wewnątrz tunelu',
    'settings.livesync_peer_ip_ph' => 'np. 10.9.0.2',
    'settings.livesync_port' => 'Port synchronizacji (UDP)',
    'settings.livesync_port_hint' => 'Osobny port, nie 6969 trackera.',
    'settings.livesync_test_btn' => 'Test',
    'settings.livesync_test_ok' => 'Synchronizację peerów można stąd uzbroić.',
    'settings.livesync_title' => 'Synchronizacja peerów na żywo',
    'settings.livesync_yes' => 'Tak',
    'settings.mail_domain_not_allowed' => '(już niedozwolona)',
    'settings.mail_from' => 'Adres nadawcy (From)',
    'settings.mail_from_hint' => 'Cała poczta wychodząca (resety, weryfikacje, powiadomienia) jest wysyłana Z tego adresu; odpowiedzi nadal trafiają na E-mail strony. Zostaw lewe pole puste, aby wysyłać z E-maila strony. Lista domen jest ograniczona do hosta z Adresu strony i jego domen nadrzędnych — cokolwiek innego psuje zgodność SPF/DKIM/DMARC. Najlepsza dostarczalność: domena, dla której Twój serwer pocztowy podpisuje DKIM i która ma rekord SPF (zwykle domena główna).',
    'settings.mail_from_hint_nodomain' => 'Najpierw ustaw poprawny <strong>Adres strony</strong> (domenę, nie IP) — domena nadawcy jest wtedy wybierana z tej domeny i jej domen nadrzędnych. Do tego czasu to zwykłe pole tekstowe, a wartość nie jest sprawdzana pod kątem domeny.',
    'settings.mail_from_sub' => '(puste = E-mail strony)',
    'settings.pm_chars' => 'Znaków na wiadomość',
    'settings.pm_chars_hint' => 'Sufit dla jednej wiadomości. Od 200 do 20000.',
    'settings.pm_day' => 'Wiadomości na konto dziennie',
    'settings.pm_day_hint' => 'To, co powstrzymuje jedno konto przed pisaniem do wszystkich. Od 1 do 1000.',
    'settings.pm_enabled' => 'Wiadomości prywatne',
    'settings.pm_enabled_hint' => 'Wyłączone — endpointy odpowiadają 404 i nigdzie nie rysuje się skrzynka.',
    'settings.pm_heading' => 'Ludzie: wiadomości, znajomi, katalog',
    'settings.pm_intro' => 'Konta docierające do siebie nawzajem. Wszystko tutaj startuje wyłączone. Poniższa wartość domyślna to to, co dziedziczy użytkownik, dopóki sam nie wybierze na swojej stronie konta — jej zmiana przesuwa wszystkich, którzy nie wybrali, i nie nadpisuje nikogo, kto wybrał.',
    'settings.pm_who' => 'Kto może pisać, domyślnie',
    'settings.pm_who_all' => 'Każdy zalogowany',
    'settings.pm_who_friends' => 'Tylko znajomi',
    'settings.pm_who_hint' => 'Skrzynka, do której może pisać każdy, to decyzja do podjęcia świadomie, a nie stan, do którego się dochodzi przez nieprzemyślenie.',
    'settings.pm_who_nobody' => 'Nikt',
    'settings.friends_enabled' => 'Znajomi i obserwowanie',
    'settings.friends_enabled_hint' => 'Nieodpowiedziane zaproszenie to obserwowanie; przyjęte — znajomość. Wyłączone, „tylko znajomi” powyżej znaczy „nikt”.',
    'settings.directory_enabled' => 'Katalog użytkowników',
    'settings.directory_enabled_hint' => 'Przeglądalna lista osób, które zaznaczyły „umieść mnie”. Nikogo innego na niej nie ma.',
    'settings.keep_saved' => 'Torrenty, które ktoś zachował',
    'settings.keep_saved_days' => 'Dodatkowe dni dla zachowanych',
    'settings.keep_saved_days_hint' => 'Jak długo zachowany hash żyje ponad zwykłą ochronę. Zegar startuje od nowa, gdy rój znów pokaże ten torrent — razem ze zwykłym. Od 1 do 3650.',
    'settings.keep_saved_extend' => 'Daj im dodatkowy czas',
    'settings.keep_saved_forever' => 'Nigdy ich nie usuwaj',
    'settings.keep_saved_hint' => 'Hash, który ktoś oznaczył gwiazdką albo wrzucił na listę, to hash, do którego ktoś chciał wrócić. Sprzątacz może go w ogóle nie ruszać albo dodać mu poniższe dni ponad ochronę powyżej — a torrent, który znów pojawi się w roju, i tak restartuje oba zegary.',
    'settings.keep_saved_off' => 'Traktuj jak każdy inny',
    'settings.lists_enabled' => 'Listy',
    'settings.lists_enabled_hint' => 'Wyłączone — endpointy odpowiadają 404 i nigdzie nie rysuje się nic o listach.',
    'settings.lists_heading' => 'Listy',
    'settings.lists_intro' => 'Lista to zbiór, który ktoś tworzy świadomie: nazwa, torrenty, które do niej wrzucił, i jego własna decyzja, kto może ją zobaczyć. Przydatne w trybie blacklisty, gdzie nie ma whitelisty, po której można by grupować — czytelnik i tak może zebrać paczkę i komuś ją podać. Wszystko tutaj startuje wyłączone.',
    'settings.lists_items' => 'Torrentów na listę',
    'settings.lists_items_hint' => 'Sufit dla jednej listy, żeby jeden zbiór nie stał się kosztem zapytań dla wszystkich. Od 10 do 5000.',
    'settings.lists_max' => 'List na konto',
    'settings.lists_max_hint' => 'Ile list może mieć jedno konto. Od 1 do 200.',
    'settings.lists_public' => 'Listy publiczne',
    'settings.lists_public_hint' => 'Ogólnosystemowa połowa pytania „czy lista może być publiczna”. Wyłączone — każda lista jest prywatna niezależnie od wyboru właściciela; jego wybór jest zapamiętany i wraca do gry po włączeniu tego z powrotem.',
    'settings.mail_heading' => 'Kontakt i e-mail',
    'settings.mail_hmac' => 'Sekret HMAC (dla tokenów wypisania)',
    'settings.mail_local_ph' => 'noreply',
    'settings.mail_obfuscate' => 'Maskuj e-mail',
    'settings.mail_show_contact' => 'Pokaż kontakt',
    'settings.mail_site_email' => 'E-mail strony',
    'settings.mail_site_email_sub' => '(kontakt publiczny; tu trafiają odpowiedzi)',
    'settings.net_auto_cpu_cores_hint' => 'Ta maszyna ma <strong>:cores</strong> rdzeni, więc :pct % oznacza średnie obciążenie powyżej <strong>:load</strong>.',
    'settings.net_auto_cpu_hint' => 'Gdy 1-minutowe średnie obciążenie na rdzeń przekracza tę wartość, tryb automatyczny zacieśnia limit, nawet jeśli tempo pakietów jest poniżej celu.',
    'settings.net_auto_cpu_label' => 'Strażnik CPU',
    'settings.net_auto_cpu_label_sub' => '(% obciążenia na rdzeń)',
    'settings.net_auto_heading' => 'Tryb automatyczny',
    'settings.net_auto_heading_sub' => '(domyślnie wyłączony)',
    'settings.net_auto_intro' => 'Raz na minutę janitor porównuje liczbę pakietów na sekundę, które faktycznie dotarły do trackera, z Twoim celem i przesuwa limit o ±10 % w obrębie pasma poniżej. Potrzebuje <strong>trzech</strong> kolejnych próbek po tej samej stronie, zanim cokolwiek się ruszy (więc pojedynczy skok niczego nie zmienia), a między ruchami obowiązuje dwuminutowa przerwa. Wymaga włączenia zarówno monitora, jak i limitu ruchu przychodzącego.',
    'settings.net_auto_label' => 'Tryb automatyczny',
    'settings.net_auto_max_hint' => '… i nigdy nie luzuje powyżej tej.',
    'settings.net_auto_max_label' => 'Pasmo: maksimum',
    'settings.net_auto_min_hint' => 'Tryb automatyczny nigdy nie dławi poniżej tej wartości.',
    'settings.net_auto_min_label' => 'Pasmo: minimum',
    'settings.net_auto_off' => 'Wyłączony',
    'settings.net_auto_on' => 'Wł. — przesuwaj limit za mnie',
    'settings.net_auto_target_hint' => 'Ile pakietów na sekundę chcesz oddawać OpenTrackerowi. Powyżej tej wartości limit się zacieśnia, wyraźnie poniżej niej (−20 %) — luzuje.',
    'settings.net_auto_target_label' => 'Cel',
    'settings.net_auto_target_label_sub' => '(pakiety/sekundę)',
    'settings.net_avail_test_btn' => 'Sprawdź dostęp do firewalla',
    'settings.net_avail_test_hint' => 'Tylko odczyt: sprawdza <code>nft</code>, regułę sudoers i czy reguła przetrwa restart. Niczego nie ładuje ani nie usuwa.',
    'settings.net_avail_test_label' => 'Test dostępności',
    'settings.net_blocked' => 'Zablokowane adresy',
    'settings.net_blocked_hint' => 'Lustrzane odbicie pola powyżej; istnieje dla jednego przypadku, którego listy nie potrafią wyrazić: <strong>&bdquo;przepuść całą Polskę oprócz tych trzech hostów&rdquo;</strong>. Lista dozwolonych jest dopasowywana przed listą blokowanych, więc hosta z dozwolonego zakresu nie zatrzyma żadna inna lista &mdash; ale zatrzyma go to pole.',
    'settings.net_blocked_more' => 'Kolejność dopasowywania',
    'settings.net_blocked_more_1' => '<strong>1. Zaufane adresy</strong> &mdash; przepuszczane, niezależnie od reszty. <strong>2. Zablokowane adresy (to pole)</strong> &mdash; odrzucane, przed wszystkimi listami. <strong>3. Listy dozwolonych</strong> &mdash; przepuszczane. <strong>4. Listy blokowane</strong> &mdash; odrzucane. <strong>5. Listy blokowane pod obciążeniem</strong> &mdash; dostają jedną piątą ogólnego budżetu. <strong>6. Limit przychodzący</strong> &mdash; wszyscy pozostali. Adres wpisany w oba pola jest więc zaufany: wygrywa pierwsze dopasowanie, a panel mówi o tym na',
    'settings.net_blocked_more_2' => 'zamiast zostawiać Ci to do wykombinowania. Ten sam limit co wyżej (:max), ta sama walidacja tutaj i ponownie w pomocniku roota. Całe kraje należą do <em>listy</em> na stronie Ruchu, nie do tego pola.',
    'settings.net_blocked_note' => '(zawsze odrzucane)',
    'settings.net_burst_hint' => 'O ile ponad budżet może wyjść krótki skok, zanim pakiety zaczną być odrzucane. 100 to rozsądna wartość domyślna; przy 5 limit zaczyna działać niemal natychmiast.',
    'settings.net_burst_label' => 'Burst',
    'settings.net_burst_label_sub' => '(pakiety)',
    'settings.net_cmd_hint' => 'Tylko litery, cyfry, spacja i <code>_ . / -</code> — bez metaznaków powłoki, dokładnie jak polecenie przełączania trybu powyżej.',
    'settings.net_cmd_label' => 'Polecenie pomocnika roota',
    'settings.net_cmd_label_sub' => '(argumenty akcji są dopisywane automatycznie; puste = funkcja wyłączona)',
    'settings.net_cmd_ph' => 'np. :cmd',
    'settings.net_in_force' => 'Obowiązuje: :n',
    'settings.net_install_once' => 'Zainstaluj raz, na serwerze',
    'settings.net_intro_1' => 'Dwa różne problemy, dwie różne dźwignie. <strong>Ruch przychodzący</strong> (ta sekcja): pakiety odrzucone przez firewall nigdy nie docierają do OpenTrackera, więc rój, który bez przerwy wali w port, nie kosztuje CPU. <strong>Ruch wychodzący</strong> (<code>tools/opentracker/egress-budget/ottrack.nft</code>): ograniczenie tego, co tracker <em>odpowiada</em>, utrzymuje resztę maszyny osiągalną. Panel steruje pierwszym, a drugi pokazuje obok na',
    'settings.net_intro_2' => 'Wszystko tutaj jest stosowane przez pomocnika roota <code>tools/opentracker/tracker-netlimit.sh</code>, który zapisuje <strong>jeden plik</strong> (<code>/etc/nftables.d/ottrack-in.nft</code>) we <strong>własnej tabeli nftables</strong> (<code>inet ottrack_in</code>). Tabela <code>inet filter</code> Twojej dystrybucji i reguły dodane tam ręcznie nigdy nie są czytane ani zapisywane &mdash; cofnięcie tego wszystkiego to jedno kliknięcie albo <code>nft delete table inet ottrack_in</code>.',
    'settings.net_intro_link' => 'stronie Ruchu',
    'settings.net_keep' => 'Przechowuj próbki przez',
    'settings.net_keep_hint' => 'Przy jednej próbce na minutę to ~1 440 wierszy dziennie &mdash; 14 dni to około 20 000 malutkich wierszy.',
    'settings.net_limit_label' => 'Limit ruchu przychodzącego',
    'settings.net_limit_off' => 'Wył. — nic nie jest odrzucane',
    'settings.net_limit_on' => 'Włączony',
    'settings.net_monitor' => 'Monitor ruchu',
    'settings.net_monitor_hint' => 'Włącz go <em>najpierw</em>: sugerowany próg jest liczony z pomiarów, a nie zgadywany. Liczniki żyją w firewallu, więc strona Ruchu oferuje <strong>Zacznij liczyć</strong> &mdash; tę samą tabelę <strong>bez żadnej reguły odrzucania</strong>, która mierzy, niczego nie dławiąc.',
    'settings.net_monitor_off' => 'Wyłączony',
    'settings.net_monitor_on' => 'Włączony &mdash; zapisuj pakiety/sekundę',
    'settings.net_not_address' => 'To nie adres, pominięto:',
    'settings.net_port' => 'Port UDP trackera',
    'settings.net_port_hint' => 'Port z Twojego adresu announce (domyślnie <code>6969</code>). Dotykany jest tylko ten port.',
    'settings.net_pps_hint' => 'Wszystko powyżej tej wartości jest odrzucane, zanim zobaczy to OpenTracker. :min–:max.',
    'settings.net_pps_label' => 'Pakiety / sekundę',
    'settings.net_sample' => 'Próbkuj co',
    'settings.net_sample_hint' => 'Timer janitora działa co minutę, więc wartości poniżej 60 s i tak próbkują najwyżej raz na minutę.',
    'settings.net_seconds' => '(sekundy)',
    'settings.net_throttle_heading' => 'Limit ruchu przychodzącego',
    'settings.net_throttle_heading_sub' => '(dławik)',
    'settings.net_throttle_intro' => 'Zapis tutaj określa tylko, co panel <em>powinien</em> załadować — nie dotyka firewalla. Ładowanie, podgląd i usuwanie reguły na żywo odbywa się na',
    'settings.net_throttle_intro_after' => ', za hasłem administratora, ze zmierzoną medianą / P95 / szczytem naniesionymi na suwak.',
    'settings.net_throttle_intro_link' => 'stronie Ruch',
    'settings.net_title' => 'Ruch UDP i limit pakietów',
    'settings.net_trusted' => 'Zaufane adresy',
    'settings.net_trusted_hint' => 'IPv4 lub IPv6, pojedyncze lub CIDR, rozdzielone przecinkami, spacjami lub nowymi liniami. Pakiety z tych źródeł są <strong>liczone, ale nigdy nie odrzucane</strong> &mdash; całkowicie omijają budżet.',
    'settings.net_trusted_more' => 'Po co to jest i ile kosztuje',
    'settings.net_trusted_more_body' => 'Limit pakietów nie wie, które pakiety są ważne. Jeśli ta maszyna hostuje też serwer gry, jest monitorowana ze stałego adresu albo łączysz się z nią przez SSH z jednego miejsca, te źródła nigdy nie powinny paść ofiarą roju. Każdy wpis staje się elementem zbioru nftables i kosztuje jedno wyszukanie w hashu, więc lista jest darmowa przy każdym sensownym rozmiarze &mdash; limit to <strong>:max</strong> i jest to limit na rozsądek, nie na wydajność: to wyjątek od własnej ochrony maszyny, a lista, której nikt nie przegląda, to dziura. Źródło wpisane tutaj może nadawać w dowolnym tempie. Adresy są sprawdzane tutaj <em>i ponownie</em> w pomocniku roota, który faktycznie zapisuje je do firewalla; wszystko nierozpoznane jest pomijane z notką, zamiast unieważniać całe zastosowanie.',
    'settings.net_trusted_note' => '(nigdy nie limitowane)',
    'settings.no' => 'Nie',
    'settings.opt_disabled' => 'Wyłączone',
    'settings.opt_enabled' => 'Włączone',
    'settings.ot_auto_reload' => 'Automatyczne przeładowanie czarnej listy',
    'settings.ot_auto_reload_hint' => 'Automatyczny <code>systemctl reload</code> po każdym zablokowaniu/odblokowaniu/przywróceniu, aby zmiany działały natychmiast.',
    'settings.ot_auto_reload_no' => 'Nie &mdash; tylko ręcznie',
    'settings.ot_auto_reload_yes' => 'Tak &mdash; SIGHUP przy zmianie',
    'settings.ot_bl_danger' => 'Zmiany czarnej listy → czerwony',
    'settings.ot_bl_danger_hint' => 'Od tej liczby wzwyż alert robi się czerwony (restart wymagany).',
    'settings.ot_bl_warn' => 'Zmiany czarnej listy → pomarańczowy',
    'settings.ot_bl_warn_hint' => 'Liczba oczekujących zmian czarnej listy od ostatniego startu, po której zalecany jest restart.',
    'settings.ot_cluster_enabled' => 'Włączone',
    'settings.ot_cluster_enabled_hint' => 'Włączenie tylko pokazuje kartę; niczego nie tworzy.',
    'settings.ot_cluster_no' => 'Nie',
    'settings.ot_cluster_port_base' => 'Pierwszy dodatkowy port',
    'settings.ot_cluster_port_base_hint' => 'Puste = panel proponuje pierwszy wolny port obok portu samego trackera. Porty poniżej 1024 są odrzucane.',
    'settings.ot_cluster_port_base_ph' => '(obok portu głównego)',
    'settings.ot_cluster_test' => 'Test',
    'settings.ot_cluster_test_hint' => 'Przycisk Test sprawdza też coś, czego panel sam nie widzi: czy <em>zainstalowany</em> <code>/usr/local/sbin/tracker-mode.sh</code> rozumie <code>--all</code>. Żaden deploy nie aktualizuje tego pliku, a jeśli nocny harmonogram wywoła flagę, której zainstalowana kopia nie zna, zaplanowane godziny whitelisty po prostu nigdy się nie zaczną — po cichu, każdej nocy.',
    'settings.ot_cluster_yes' => 'Tak',
    'settings.ot_cpu_affinity' => 'Przypisanie do rdzeni (affinity)',
    'settings.ot_cpu_affinity_hint' => 'Puste = wszystkie rdzenie. Przypinanie pomaga tylko wtedy, gdy coś innego na tej maszynie potrzebuje wolnych rdzeni. <strong>Wymaga restartu.</strong>',
    'settings.ot_cpu_affinity_ph' => 'np. 2-5',
    'settings.ot_cpu_weight' => 'Waga CPU',
    'settings.ot_cpu_weight_hint' => 'Udział CPU względem innych usług przy rywalizacji. 100 to domyślna wartość dla wszystkiego, więc 200 oznacza „dwa razy tyle co forum”.',
    'settings.ot_intro_1' => 'Podaj jednostkę systemd swojego trackera (np. <code>opentracker</code> lub <code>opentracker.service</code>). Gdy jest ustawiona, na Pulpicie pojawiają się przyciski <strong>Przeładuj</strong> i <strong>Restartuj tracker</strong> wraz z inteligentnymi zaleceniami, które robią się',
    'settings.ot_intro_2' => 'gdy restart jest wskazany (po zmianach czarnej listy albo przy długim uptime). <strong>Przeładuj</strong> uruchamia <code>systemctl reload &lt;nazwa&gt;</code> &mdash; <strong>SIGHUP</strong>, po którym OpenTracker ponownie wczytuje białą/czarną listę <em>bez przestoju</em>; <strong>Restartuj</strong> uruchamia <code>systemctl restart &lt;nazwa&gt;</code> (krótki przestój). Użytkownik web/PHP musi mieć prawo uruchamiać te polecenia &mdash; użyj przycisków <strong>Test</strong> poniżej i zajrzyj do README (sudoers). Zostaw nazwę pustą, aby całkowicie ukryć przyciski.',
    'settings.ot_intro_or' => 'lub',
    'settings.ot_intro_orange' => 'pomarańczowe',
    'settings.ot_intro_red' => 'czerwone',
    'settings.ot_nice' => 'Nice',
    'settings.ot_nice_hint' => 'Niżej = więcej CPU, gdy maszyna jest zajęta. −2 zalecają notatki instalacyjne; poniżej −5 zaczynasz konkurować z wątkami samego jądra.',
    'settings.ot_nofile' => 'Limit otwartych plików',
    'settings.ot_nofile_hint' => '<code>LimitNOFILE</code>. <strong>Wymaga restartu.</strong>',
    'settings.ot_perf_cmd' => 'Polecenie pomocnika',
    'settings.ot_perf_cmd_hint' => 'Wymaga reguły sudoers: <code>www-data ALL=(root) NOPASSWD: /usr/local/sbin/tracker-instance.sh</code>. Puste = panel może tylko czytać, nigdy zmieniać.',
    'settings.ot_perf_cmd_ph' => 'np. sudo -n /usr/local/sbin/tracker-instance.sh',
    'settings.ot_perf_intro_a' => 'Pokrętła, które i tak istnieją na każdej maszynie z systemd, a dają niemal cały dostępny zysk przy niemal zerowym ryzyku. Wszystko, co panel zapisuje, trafia do <strong>jednego pliku, który jest jego własnością</strong> — <code>90-tracker-panel.conf</code> w katalogu drop-in unitu. <code>override.conf</code> i <code>limits.conf</code> położył tam instalator albo ręka administratora i są <strong>nigdy nieruszane</strong>; cofnięcie to usunięcie tego jednego pliku panelu, i to właśnie robi <em>Reset</em>. <strong>Zapis tutaj sam z siebie niczego nie zmienia</strong> — te wartości opisują, czego chcesz, a wprowadza je w życie przycisk Zastosuj na stronie',
    'settings.ot_perf_intro_b' => '(hasło administratora).',
    'settings.ot_perf_test_btn' => 'Testuj',
    'settings.ot_perf_title' => 'OpenTracker — wydajność',
    'settings.ot_perf_traffic_page' => 'Ruch',
    'settings.ot_perm_test' => 'Test uprawnień',
    'settings.ot_perm_test_hint' => 'Sprawdza, czy użytkownik web może uruchomić polecenie (przez <code>sudo -n -l</code>) &mdash; <strong>nie</strong> restartuje ani nie przeładowuje niczego. Najpierw zapisz nazwę usługi. Jeśli test się nie powiedzie, pokażą się instrukcje naprawy.',
    'settings.ot_perm_test_reload' => 'Testuj uprawnienie do przeładowania',
    'settings.ot_perm_test_restart' => 'Testuj uprawnienie do restartu',
    'settings.ot_service_name' => 'Nazwa usługi',
    'settings.ot_service_name_hint' => 'Dozwolone są tylko litery, cyfry oraz <code>. _ @ -</code>.',
    'settings.ot_service_name_note' => '(puste = wyłączone)',
    'settings.ot_sudo' => 'Uruchamiaj przez sudo',
    'settings.ot_sudo_hint' => 'Większość instalacji wymaga sudo: php-fpm działa bez uprawnień.',
    'settings.ot_sudo_no' => 'Nie &mdash; bezpośrednio',
    'settings.ot_sudo_yes' => 'Tak &mdash; <code>sudo -n</code>',
    'settings.ot_thresholds' => 'Progi zalecenia restartu',
    'settings.ot_title' => 'Usługa OpenTracker',
    'settings.ot_udp_workers' => 'Wątki UDP (workers)',
    'settings.ot_udp_workers_hint' => '<code>listen.udp.workers</code> we własnej konfiguracji opentrackera — zapisywane do <strong>obu</strong> plików trybów, żeby nie zmieniło się przy przełączeniu white/black. Puste nic nie rusza. <strong>Czytane tylko przy starcie: wymaga restartu.</strong>',
    'settings.ot_udp_workers_ph' => 'puste = bez zmian',
    'settings.ot_uptime_danger' => 'Dni uptime → czerwony',
    'settings.ot_uptime_danger_hint' => 'Ostrzeżenie o uptime robi się czerwone przy tylu dniach.',
    'settings.ot_uptime_warn' => 'Dni uptime → pomarańczowy',
    'settings.ot_uptime_warn_hint' => 'Zalecaj restart, gdy uptime osiągnie tyle dni.',
    'settings.pages_archive_appeals' => 'Automatyczna archiwizacja odwołań',
    'settings.pages_archive_appeals_hint' => 'Automatycznie archiwizuj rozstrzygnięte odwołania starsze niż X dni.',
    'settings.pages_archive_reports' => 'Automatyczna archiwizacja zgłoszeń',
    'settings.pages_archive_reports_hint' => 'Automatycznie archiwizuj rozpatrzone zgłoszenia starsze niż X dni.',
    'settings.pages_badge_builtin' => 'wbudowana',
    'settings.pages_badge_draft' => 'szkic — widoczna jest strona wbudowana',
