    'settings.pages_email_log' => 'Usuwaj log e-maili po',
    'settings.pages_email_log_hint' => 'Usuwa wiersze sent_emails starsze niż X dni. Domyślnie wyłączone.',
    'settings.pages_email_log_sub' => '(0 = przechowuj bezterminowo)',
    'settings.pages_format' => 'Format',
    'settings.pages_format_bbcode' => 'BBCode — bez nagłówków, zamiast nich duże pogrubienie',
    'settings.pages_format_markdown' => 'Markdown — z nagłówkami',
    'settings.pages_heading' => 'Strony publiczne',
    'settings.pages_heading_2' => 'Strony serwisu (Regulamin i Informacje)',
    'settings.pages_intro1' => '<strong>Regulamin</strong> i <strong>Informacje o trackerze</strong> są dostarczane jako gotowe strony i można je zastąpić własnymi, tym samym edytorem, którego używają opisy na whiteliście i masowa poczta — Markdown lub BBCode, z podglądem na żywo. Wbudowane strony <em>przepisują się same</em>, gdy zmienia się tryb trackera lub system kont; zapisana strona już nie, a <strong>Przywróć</strong> wraca do wbudowanej wersji napisanej pod aktualną konfigurację trackera.',
    'settings.pages_intro2' => '<strong>Jedna wersja na język.</strong> Odwiedzający dostaje wersję w swoim języku; gdy nie jest opublikowana, dostaje wersję w domyślnym języku strony, potem angielską, potem dowolną inną istniejącą — i dopiero gdy <em>nic</em> nie jest napisane, dostaje stronę wbudowaną. Ta kolejność jest zamierzona: regulamin, który faktycznie napisałeś, nigdy nie może zostać po cichu zastąpiony szablonem tylko dlatego, że brakuje jednego tłumaczenia.',
    'settings.pages_intro3' => '<strong>Markdown jest proponowany jako pierwszy</strong> dla tych dwóch stron, i nie z upodobania: renderer ma prawdziwe nagłówki w Markdown (<code>#</code>…<code>######</code>), a w BBCode żadnych — tam nagłówek może być tylko większą pogrubioną linią. Strona regulaminu to głównie nagłówki i listy numerowane.',
    'settings.pages_lang_draft' => 'zapisana jako szkic',
    'settings.pages_lang_live' => 'Twoja wersja jest opublikowana',
    'settings.pages_lang_none' => 'brak napisanej wersji',
    'settings.pages_meta_never' => 'Nigdy nie edytowana — odwiedzający widzą stronę dostarczoną z panelem.',
    'settings.pages_meta_written' => 'Napisano :n z :total języków.',
    'settings.pages_preview' => 'Jak to będzie wyglądać',
    'settings.pages_preview_frame' => 'Podgląd',
    'settings.pages_restore' => 'Przywróć wbudowaną',
    'settings.pages_save' => 'Zapisz',
    'settings.pages_title' => 'Strony serwisu',
    'settings.pages_use_mine' => 'Użyj mojej wersji',
    'settings.pages_view' => 'Podgląd',
    'settings.pages_your_text' => 'Twój tekst',
    'settings.pages_zero_disabled' => '(0 = wyłączone)',
    'settings.pc_markers_note' => 'Bloki ujęte w [[if:name]] … [[/if]] (albo [[ifnot:name]]) pojawiają się tylko wtedy, gdy dane ustawienie jest włączone, więc zapisana strona nadal podąża za trybem trackera i systemem kont dokładnie tak jak wbudowana. „Przywróć" przywraca wbudowany tekst dla tego języka, razem ze znacznikami.',
    'settings.probe_disabled' => 'Wyłączone',
    'settings.probe_enabled' => 'Włączone',
    'settings.probe_intro_p1' => 'Każdy może wkleić czterdzieści znaków hex. Większość tego, co gromadzi publiczna whitelista, to nie nadużycia — to hashe, których nikt nie seeduje, i hashe, których torrent nigdy nie wskazywał tego trackera. Każdy z nich staje się wierszem, który accesslist niesie na zawsze.',
    'settings.probe_intro_p2' => 'Gdy to włączone, nowe zgłoszenie musi wykazać dwie rzeczy, zanim tracker zacznie je obsługiwać: <strong>metadane da się pobrać</strong> (ktoś naprawdę to udostępnia) i <strong>scrape znajduje co najmniej jednego peera</strong> (announce\'ującego tutaj). Korzysta z workera metadanych zamiast dokładać drugą kolejkę, ale przeskakuje kolejkę — na to zgłoszenie ktoś czeka, na resztę kolejki nikt. <strong>Domyślnie wyłączone:</strong> zmienia to, co <em>znaczy</em> rejestracja, a tego nie powinno się dziedziczyć po aktualizacji.',
    'settings.probe_max_batch' => 'Magnetów weryfikowanych naraz, na zgłoszenie',
    'settings.probe_max_batch_hint' => 'Pięćset wierszy na pasie priorytetowym nie rozwiąże się szybciej — wszyscy po prostu czekają razem. Trzymaj to na poziomie <em>Równoległych pobrań workera</em> lub niżej.',
    'settings.probe_max_batch_ph' => 'np. 8 (domyślnie równoległość workera)',
    'settings.probe_on_fail' => 'Jeśli magnet nigdy się nie zweryfikuje',
    'settings.probe_on_fail_delete' => 'Usuń wiersz',
    'settings.probe_on_fail_hint' => 'Tu domyślnie usuwamy, inaczej niż w regule martwych wierszy: ten wiersz nigdy nie był obsługiwany i nikt na nim nie polega.',
    'settings.probe_on_fail_keep' => 'Zostaw, nieobsługiwany, z powodem',
    'settings.probe_required' => 'Weryfikuj magnet przed obsługą',
    'settings.probe_required_hint' => 'Istniejące wiersze nie są objęte: wszystko zarejestrowane wcześniej liczy się jako już przyjęte, więc włączenie niczego nie cofa z publikacji.',
    'settings.probe_subtitle' => 'Sprawdzenie magnetu, weryfikacja peerów i kolejka weryfikacji',
    'settings.probe_timeout' => 'Limit czasu weryfikacji (minuty)',
    'settings.probe_timeout_hint' => 'Pobranie metadanych z DHT nie jest natychmiastowe. Za krótki limit i uczciwe zgłoszenia przepadają.',
    'settings.probe_title' => 'Zgłoszenia muszą się wykazać',
    'settings.profiles' => 'Publiczne profile',
    'settings.profiles_hint' => 'Czy <code>?action=u&amp;name=…</code> jest osiągalne. Osobny włącznik, bo korzystają z niego też zarejestrowane torrenty. Profil widzi wyłącznie zalogowany czytelnik.',
    'settings.rep_anon_weight' => 'Waga głosu anonimowego (%)',
    'settings.rep_anon_weight_hint' => 'Wobec 100% dla zalogowanego konta. 0 = głosy anonimowe są liczone, ale niczego nie zmieniają.',
    'settings.rep_captcha_pts_vote' => 'Punkty CAPTCHA za głos',
    'settings.rep_captcha_pts_vote_hint' => 'Głos dodaje tyle do tego samego wyniku, który zasilają wszystkie inne akcje. Spokojne korzystanie nigdy nie jest przerywane; pięćdziesiąt głosów w minutę trafia na wyzwanie, bez pisania przez kogokolwiek wykrywacza botów.',
    'settings.rep_enabled_hint' => 'Oceny dotyczą <strong>każdego hasha znanego katalogowi</strong>, nie tylko zarejestrowanych — torrent nie musi być wpisany na whitelistę, żeby dało się go ocenić.',
    'settings.rep_heading' => 'Oceny',
    'settings.rep_intro_1' => 'Kciuk w górę lub w dół dla torrenta, widoczny w panelu Info i opcjonalnie obok każdego wyniku wyszukiwania. <strong>Domyślnie wyłączone.</strong>',
    'settings.rep_intro_2' => '<strong>Czym naprawdę jest publiczny przycisk głosowania:</strong> najłatwiejszą do zautomatyzowania rzeczą na stronie. Jedna pętla, tysiąc negatywów i wynik na zawsze przestaje cokolwiek znaczyć. Stoją tu temu na drodze cztery rzeczy, bo żadna pojedyncza nie wystarcza: jeden głos na tożsamość wymuszony przez <strong>unikalny klucz w bazie danych</strong> (a nie sprawdzenie w PHP, które jest wyścigiem — dwa żądania przejdą przez nie bez trudu), wspólny limiter żądań, schemat punktów CAPTCHA, którego ta strona już używa, oraz waga sprawiająca, że głos anonimowy liczy się mniej niż głos konta.',
    'settings.rep_intro_3' => '<strong>O przypisywaniu głosów do adresu IP:</strong> <code>REMOTE_ADDR</code> pochodzi z połączenia TCP i nie da się go sfałszować przez internet — wymagałoby to dokończenia handshake\'u z podrobionego adresu. Nagłówki da się sfałszować, a ten panel czyta je tylko wtedy, gdy żądanie faktycznie przyszło z adresu wpisanego w <em>Zaufane IP proxy</em>. Czego to wszystko nie rozwiązuje, to jedna osoba z VPN-em i telefonem: IPv6 jest grupowane do /64, więc jedna alokacja liczy się raz, ale wynik zbudowany z anonimowych głosów to słaby sygnał i panel nie będzie udawał, że jest inaczej.',
    'settings.rep_min_votes' => 'Głosów, zanim wynik będzie widoczny',
    'settings.rep_min_votes_hint' => 'Poniżej tej liczby panel pokazuje „za mało ocen” zamiast liczby. „100% z jednego głosu” i „100% z czterystu” to nie ten sam fakt.',
    'settings.rep_mode' => 'Sposób oceniania',
    'settings.rep_mode_hint' => 'Gwiazdki są zapisywane w dziesięciu krokach, a pokazywane jako pięć, więc pół gwiazdki to prawdziwa wartość, a nie coś wywnioskowanego. Zmiana trybu niczego nie usuwa, ale obie skale nie są porównywalne — oceny oddane w jednym trybie będą dziwnie wyglądać w drugim.',
    'settings.rep_mode_stars' => 'Pięć gwiazdek, co pół gwiazdki',
    'settings.rep_mode_thumbs' => 'W górę lub w dół',
    'settings.rep_off' => 'Oceny wyłączone',
