    'settings.rep_show_column' => 'Także jako kolumna na liście',
    'settings.rep_show_info' => 'Tylko w panelu Info',
    'settings.rep_who' => 'Kto może oceniać',
    'settings.rep_who_all' => 'Każdy, także anonimowo',
    'settings.rep_who_hint' => 'Anonimowe głosowanie jest przypisywane do koszyka adresów, a jedna osoba może mieć ich kilka. Włączaj to ze świadomością tego faktu.',
    'settings.rep_who_off' => 'Nikt — tylko pokazuj wyniki',
    'settings.rep_who_users' => 'Zalogowane konta',
