    'settings.sched_all_day' => 'whitelist 00:00–24:00',
    'settings.sched_ends_next_day_at' => 'kończy się następnego dnia o ',
    'settings.sched_open_mode' => 'tryb otwarty (blacklist)',
    'settings.sched_same_day' => 'ten sam dzień',
    'settings.sched_set_both_times' => 'ustaw obie godziny',
    'settings.schedule_desired_now' => 'Oczekiwany tryb teraz:',
    'settings.schedule_disabled' => 'Wyłączony',
    'settings.schedule_enabled' => 'Tryb harmonogramu',
    'settings.schedule_enabled_opt' => 'Włączony',
    'settings.schedule_intro_1' => 'Uruchamia tracker w trybie <strong>whitelisty</strong> w godzinach poniżej, a w każdej innej chwili w trybie <strong>otwartym (blacklista)</strong>.',
    'settings.schedule_intro_2' => 'Samo przełączenie wykonuje pomocnik roota poniżej (podmienia binarkę + konfigurację OpenTrackera i restartuje usługę; argument <code>white</code> / <code>black</code>),',
    'settings.schedule_intro_3' => 'wywoływany przez timer janitora (<code>tools/janitor.php</code>, co minutę) — nigdy przez żądanie WWW. Gdy harmonogram jest WŁĄCZONY, pole „Tryb trackera” powyżej jest',
    'settings.schedule_intro_4' => 'nadpisywane przez harmonogram w ciągu minuty; bany są utrzymywane spójnie między whitelistą (zbanowane hashe) a plikiem blacklisty przy każdym przełączeniu.',
    'settings.schedule_intro_5' => 'Rejestracja publiczna pozostaje otwarta w obu trybach; hashe zarejestrowane w godzinach otwartych stają się aktywne w następnym oknie whitelisty.',
    'settings.schedule_invalid' => 'nieprawidłowy',
    'settings.schedule_kind_all' => 'Whitelista cały dzień',
    'settings.schedule_kind_none' => 'Blacklista (otwarty) cały dzień',
    'settings.schedule_kind_window' => 'Okno whitelisty',
    'settings.schedule_last_switch' => 'Ostatnie przełączenie:',
    'settings.schedule_next_change' => 'następna zmiana:',
    'settings.schedule_none' => 'brak',
    'settings.schedule_off_note' => 'Harmonogram jest wyłączony — tracker pozostaje w trybie wybranym powyżej.',
    'settings.schedule_saved' => 'Zapisany harmonogram:',
    'settings.schedule_subtitle' => 'Whitelista w wyznaczonych godzinach, poza nimi otwarty',
    'settings.schedule_switch_at' => 'o',
    'settings.schedule_switch_cmd' => 'Polecenie przełączania trybu',
    'settings.schedule_switch_cmd_hint' => '(pomocnik roota; dopisywane jest <code>white</code>/<code>black</code>; puste = tylko przełącz ustawienie w panelu)',
    'settings.schedule_switch_cmd_ph' => 'np. sudo -n /usr/local/sbin/tracker-mode.sh',
    'settings.schedule_th_day' => 'Dzień',
    'settings.schedule_th_from' => 'Od',
    'settings.schedule_th_rule' => 'Reguła',
    'settings.schedule_th_to' => 'Do',
    'settings.schedule_title' => 'Harmonogram trybu trackera',
    'settings.schedule_tracker_is_in' => 'tracker jest w trybie',
    'settings.schedule_tz' => 'Strefa czasowa',
    'settings.schedule_window_hint' => 'Okno zaczyna się w danym dniu tygodnia o godzinie <em>Od</em>; gdy <em>Do</em> ≤ <em>Od</em>, kończy się <strong>następnego dnia</strong> o godzinie <em>Do</em> (np. Pon 10:00 → 02:30 = poniedziałek 10:00 do wtorku 02:30). Poza oknami tracker pracuje w trybie <strong>OTWARTYM (blacklista)</strong>.',
    'settings.search_aria' => 'Szukaj ustawień',
    'settings.search_clear' => 'Wyczyść wyszukiwanie',
    'settings.search_no_match' => 'Żadne ustawienie nie pasuje do',
    'settings.search_no_match_hint' => 'Spróbuj krótszego słowa — wyszukiwarka zna też synonimy (np. <em>bot</em>, <em>smtp</em>, <em>cron</em>, <em>hidden url</em>).',
    'settings.search_ph' => 'Szukaj ustawień — spróbuj: captcha, nadawca, timeout, whitelista…',
    'settings.site_announce_https' => 'Adres announce (HTTP/S)',
    'settings.site_announce_udp' => 'Adres announce (UDP)',
    'settings.site_github_hint' => 'Wyświetlany jako link <strong>GitHub</strong> w stopce. Wskaż <em>repozytorium</em> tego trackera (żeby odwiedzający trafił na źródła, a nie na stronę konta); zostaw puste, aby ukryć link.',
    'settings.site_github_url' => 'Adres GitHub',
    'settings.site_github_url_sub' => '(repozytorium projektu)',
    'settings.site_heading' => 'Konfiguracja strony',
    'settings.site_name' => 'Nazwa strony',
    'settings.site_url' => 'Adres strony (URL)',
    'settings.stats_cache_ttl' => 'Czas życia cache / TTL (s)',
    'settings.stats_cache_ttl_hint' => 'Wspólny, serwerowy czas życia pobranych statystyk. Dopóki cache jest młodszy niż ta wartość, wszyscy dostają te same dane, a tracker <strong>nie</strong> jest odpytywany ponownie. Ustaw wartość ≥ typowego czasu pobrania z trackera (zwykle 30–60 s), aby przeładowania strony nie wywoływały ciągłych synchronizacji.',
    'settings.stats_enable' => 'Włącz statystyki trackera',
    'settings.stats_home_interval' => 'Odświeżanie na stronie głównej (s)',
    'settings.stats_home_interval_hint' => 'Jak często widżet na stronie głównej pobiera świeże dane.',
    'settings.stats_livesync' => 'Licznik Live Syncs',
    'settings.stats_livesync_hint' => 'Livesync w OpenTracker wynosi 0 przy jednym węźle. „Licz nasze odświeżenia cache” zamienia statystykę <em>Live Syncs</em> na liczbę odświeżeń cache od ostatniego startu trackera (zeruje się automatycznie przy restarcie trackera).',
    'settings.stats_livesync_local' => 'Licz nasze odświeżenia cache',
    'settings.stats_livesync_upstream' => 'Wartość z trackera (surowa, często 0)',
    'settings.stats_loading_hint' => 'Podaj zakres opóźnienia w milisekundach (np. od 100 do 2000). Serwer wylosuje czas z tego zakresu, aby zasymulować animację ładowania. Ustaw obie wartości tak samo, aby uzyskać stałe opóźnienie.',
    'settings.stats_max_loading' => 'Maks. opóźnienie ładowania (ms)',
    'settings.stats_min_loading' => 'Min. opóźnienie ładowania (ms)',
    'settings.stats_opt_no' => 'Nie',
    'settings.stats_opt_yes' => 'Tak',
    'settings.stats_page_interval' => 'Odświeżanie strony statystyk (s)',
    'settings.stats_page_interval_hint' => 'Jak często strona /?action=stats sprawdza cache. Tanie trafienia w cache — nie pobiera ponownie z trackera.',
    'settings.stats_peer_label_style' => 'Styl etykiet seedów/leecherów',
    'settings.stats_peer_label_style_hint' => 'Jak podpisane są karty Seedy/Leecherzy na stronie statystyk.',
    'settings.stats_pls_absolute' => 'Bezwzględnie (z N peerów)',
    'settings.stats_pls_peers_card' => 'Karta peerów (leecherzy · seedy)',
    'settings.stats_pls_percent' => 'Procent wszystkich peerów (44% / 56%)',
    'settings.stats_show_home' => 'Pokaż na stronie głównej',
    'settings.stats_source_url' => 'Adres URL źródła statystyk',
    'settings.stats_timeout' => 'Limit czasu żądania (s)',
    'settings.stats_title' => 'Statystyki trackera',
    'settings.sysctl_cmd' => 'Polecenie pomocnika',
    'settings.sysctl_cmd_hint' => 'Puste = funkcja nie istnieje: brak karty, odpytywania i <code>sudo</code>. Najpierw zainstaluj <code>tools/opentracker/tracker-sysctl.sh</code> i jego regułę <code>sudoers.d</code>, potem naciśnij Test.',
    'settings.sysctl_cmd_ph' => 'np. sudo -n /usr/local/sbin/tracker-sysctl.sh',
    'settings.sysctl_confirm_seconds' => 'Okno potwierdzenia (s)',
    'settings.sysctl_confirm_seconds_hint' => 'Jak długo uzbrojona zmiana czeka na Twoje potwierdzenie, zanim sama się cofnie. Zaokrąglane do pełnych minut, bo awaryjnym strażnikiem jest janitor, a ten działa raz na minutę — 30-sekundowa obietnica, której nie da się dotrzymać, wciąż brzmiałaby jak gwarancja.',
    'settings.sysctl_enabled' => 'Włączone',
    'settings.sysctl_enabled_hint' => 'Domyślnie wyłączone. Włączenie tylko pokazuje kartę; niczego nie zmienia.',
    'settings.sysctl_intro' => 'Osiem ustawień jądra, które decydują, ile announce\'ów przetrwa nagły skok ruchu — bufory gniazd, kolejka pakietów na CPU i pula pamięci UDP całej maszyny. To pierwsza rzecz, której panel dotyka, a która <strong>nie</strong> należy do samego trackera: te ustawienia należą do całej maszyny, na której działa tu także poczta, forum, serwis plików i wspólna baza danych. Dlatego zapis niczego nie stosuje. Zmiana zostaje <em>uzbrojona</em>, działa, gdy na nią patrzysz, i <strong>sama się cofa, jeśli jej nie potwierdzisz</strong> — cofnięcie jest planowane przez systemd jeszcze przed wprowadzeniem zmiany, więc nie potrzebuje tego panelu, bazy danych ani administratora, który wciąż może się zalogować. Do <code>/etc</code> nic nie trafia, dopóki nie potwierdzisz również tego, więc do tego czasu restart także cofa zmianę. Wartości znajdziesz na stronie',
    'settings.sysctl_intro_link' => 'Ruch',
    'settings.sysctl_intro_tail' => ', obok liczników, które mówią, które z nich w ogóle warto ruszać.',
    'settings.sysctl_no' => 'Nie',
    'settings.sysctl_test' => 'Test',
    'settings.sysctl_title' => 'Bufory sieciowe jądra',
    'settings.sysctl_yes' => 'Tak',
    'settings.timeline_buttons' => 'Oferowane przyciski',
    'settings.timeline_buttons_hint' => 'Odznaczone zakresy znikają z wykresu wszędzie (strona statystyk, Indeks, Whitelista). Odznaczenie wszystkich przywraca pełny zestaw; domyślny zakres musi pozostać zaznaczony, inaczej wygrywa pierwszy pozostały przycisk.',
    'settings.timeline_custom' => 'Suwak własnego zakresu',
    'settings.timeline_custom_hint' => 'Dodaje suwak obejmujący dowolny zakres od 1 h do 5 lat. Te odpowiedzi są liczone przy każdym żądaniu (stałe zakresy są serwowane z 30-sekundowego cache plikowego), więc na ruchliwej publicznej stronie zostaw to wyłączone.',
    'settings.timeline_custom_yes' => 'Tak — dodaj przycisk „Własny”',
    'settings.timeline_default_range' => 'Domyślny zakres',
    'settings.timeline_default_range_hint' => 'Zakres otwierany przy pierwszej wizycie (ostatni wybór odwiedzającego jest potem zapamiętywany w przeglądarce). Krótki domyślny zakres jest najtańszy w obsłudze.',
    'settings.timeline_enable' => 'Włącz oś czasu',
    'settings.timeline_interval' => 'Interwał próbkowania (s)',
    'settings.timeline_interval_hint' => 'Jedna próbka co tyle sekund (30–600). 60 odpowiada timerowi janitora.',
    'settings.timeline_intro' => 'Zapisuje statystyki trackera w czasie (seedy, leecherzy, peery, torrenty, tempo announce, tryb trackera) i rysuje wykres w stylu giełdowym na publicznej stronie <strong>/?action=stats</strong> oraz w panelu na stronie Ruch. Próbki pobiera <strong>timer janitora</strong> (<code>tools/janitor.php</code>, co minutę — zob. README) oraz, bez dodatkowego kosztu, każde odświeżenie z trackera wykonane przez stronę statystyk; agregaty (5 min / 1 h) i retencja działają z tego samego timera. Wymaga włączonych <em>Statystyk trackera</em> powyżej z poprawnym adresem źródła statystyk.',
    'settings.timeline_keep_days' => 'Przechowuj agregaty 5-min (dni)',
    'settings.timeline_keep_days_hint' => '7–3650 dni; agregaty godzinowe są przechowywane bezterminowo (~9 tys. wierszy rocznie).',
    'settings.timeline_public' => 'Wykres publiczny',
    'settings.timeline_public_hint' => 'Gdy wyłączone, wykres i API <code>stats_timeline</code> odpowiadają tylko zalogowanym adminom.',
    'settings.timeline_public_no' => 'Nie — tylko dla adminów',
    'settings.timeline_public_yes' => 'Tak — na stronie statystyk',
    'settings.timeline_ranges_head' => 'Przyciski zakresów',
    'settings.timeline_raw_days' => 'Przechowuj surowe próbki (dni)',
    'settings.timeline_raw_days_hint' => 'Surowa rozdzielczość (1–30 dni); używana przez widok 24 h.',
    'settings.timeline_title' => 'Oś czasu statystyk',
    'settings.title' => 'Ustawienia',
    'settings.transparency_enable' => 'Włącz stronę przejrzystości',
    'settings.transparency_per_page' => 'Wyników na stronę',
    'settings.transparency_title' => 'Strona przejrzystości',
    'settings.transport_cookie_secure' => 'Bezpieczne ciasteczka',
    'settings.transport_cookie_secure_always' => 'Zawsze',
    'settings.transport_cookie_secure_auto' => 'Automatycznie — pytaj to żądanie (domyślnie)',
    'settings.transport_cookie_secure_hint' => 'Dodaje flagę <code>Secure</code> do ciasteczka sesji, języka i „zapamiętaj mnie”, więc przeglądarka wyśle je wyłącznie po HTTPS. <strong>Automatycznie</strong> pyta to żądanie: szyfrowanie do tego serwera albo zaufane proxy mówiące o tym w nagłówku obok. <strong>Zawsze</strong> jest dla konfiguracji proxy, której nie da się wykryć — a na stronie serwowanej naprawdę po zwykłym HTTP blokuje <em>wszystkich</em>, również Ciebie: przeglądarka odmawia zapisania ciasteczka sesji, więc każde logowanie się udaje, a następne kliknięcie wraca do formularza, bo token CSRF wydany przy logowaniu nigdy nie jest tym sprawdzanym przy zapisie. Powrót to jedno zapytanie na bazie trackera: <code>UPDATE settings SET value = \'auto\' WHERE `key` = \'cookie_secure_mode\';</code> — dlatego można to zapisać tylko z żądania, które już jest po HTTPS, i dlatego prosi o hasło właściciela. <strong>Nigdy</strong> to wyjście awaryjne dla instalacji po zwykłym HTTP w sieci lokalnej. Włączenie tego nikogo nie wylogowuje: Secure to reguła o wysyłaniu ciasteczka, nie o jego przechowywaniu, więc istniejące sesje działają dalej i dostają flagę przy kolejnym logowaniu.',
    'settings.transport_cookie_secure_never' => 'Nigdy',
    'settings.transport_diag_by_https' => 'serwer WWW ustawił HTTPS',
    'settings.transport_diag_by_none' => 'nic nie powiedziało HTTPS',
    'settings.transport_diag_by_proxy_header' => 'zaufane proxy powiedziało to w nagłówku',
    'settings.transport_diag_by_request_scheme' => 'serwer WWW ustawił REQUEST_SCHEME',
    'settings.transport_diag_http' => 'zwykłe HTTP',
    'settings.transport_diag_https' => 'HTTPS',
    'settings.transport_diag_label' => 'To żądanie widziane przez PHP:',
    'settings.transport_diag_remote' => 'Połączenie przyszło z',
    'settings.transport_hsts' => 'HSTS (wymuś HTTPS w przeglądarkach)',
    'settings.transport_hsts_hint' => 'Wysyła <code>Strict-Transport-Security</code>, który mówi każdej przeglądarce, która raz zobaczyła tę stronę, żeby odmawiała zwykłego HTTP do tej nazwy hosta, aż upłynie czas poniżej. <strong>Domyślnie wyłączone i nigdy nie wychodzi przy żądaniu po zwykłym HTTP.</strong> Przeczytaj to przed włączeniem: przypięcie obejmuje całą <em>nazwę hosta</em> i ignoruje port, więc adres announce po <code>http://</code> na tym samym hoście przestanie działać w przeglądarkach (klientów BitTorrent to nie dotyczy — nie mają HSTS). A wyłączenie tego z powrotem <em>nie</em> zwalnia przeglądarek, które już mają przypięcie; dobiegną do czasu, który dostały.',
    'settings.transport_hsts_max_age' => 'HSTS max-age (sekundy)',
    'settings.transport_hsts_max_age_hint' => 'Jak długo przeglądarka pamięta przypięcie. Zaczyna od <strong>86400</strong> (jeden dzień) celowo: pomyłka kosztuje wtedy dzień, nie rok. Podnieś do <code>31536000</code> (rok), gdy minie tydzień i nic się nie zepsuje — to również minimum wymagane przez listę preload. <strong>0 to nie „wyłączone”</strong>: to wycofanie i dociera do przeglądarek tylko wtedy, gdy przełącznik powyżej jest nadal włączony.',
    'settings.transport_hsts_preload' => 'HSTS: token preload',
    'settings.transport_hsts_preload_hint' => 'Dodaje <code>preload</code>, znacznik pozwalający zgłosić tę nazwę hosta na listę preload przeglądarek. <strong>Praktycznie nieodwracalne</strong>: po przyjęciu host trafia do wydań przeglądarek, a usunięcie trwa miesiące cykli wydawniczych — nic w tym panelu tego nie przyspieszy, bo ten krok dzieje się na cudzej stronie. Przyjmowane tylko razem z <em>obejmij subdomeny</em> i czasem co najmniej roku, bo tego wymaga sama lista, i prosi o hasło właściciela. Samo ustawienie niczego nie zmienia — host trzeba jeszcze zgłosić samodzielnie.',
    'settings.transport_hsts_subdomains' => 'HSTS: obejmij subdomeny',
    'settings.transport_hsts_subdomains_hint' => 'Rozszerza przypięcie na <em>każdą</em> nazwę pod tą nazwą hosta, także te, które jeszcze nie istnieją, i te prowadzone przez kogoś innego. Bezpieczne, gdy panel stoi na własnej subdomenie; na domenie głównej przypina też pocztę, forum i hosting plików — które na tej klasie maszyny są prawdziwymi sąsiadami, nie hipotezą.',
    'settings.transport_hsts_warn_announce' => 'Adres announce na stronie głównej to adres <code>http://</code> na <code>:host</code> — tej samej nazwie hosta co ten panel. HSTS ignoruje port, więc po włączeniu przeglądarki będą odmawiać tego linku przez cały czas podany poniżej (klientów BitTorrent to nie dotyczy). Najpierw przenieś adres announce na <code>https://</code> albo na inną nazwę hosta.',
    'settings.transport_intro' => 'Co ta strona mówi przeglądarkom o połączeniu: flaga <code>Secure</code> na każdym ustawianym ciasteczku oraz — wyłączony, dopóki go nie włączysz — nagłówek, który każe przeglądarce odmawiać zwykłego HTTP do tej nazwy hosta.',
    'settings.transport_proto_header' => 'Nagłówek protokołu klienta',
    'settings.transport_proto_header_hint' => 'Nagłówek, którym zdalne proxy mówi, czy połączenie samego gościa było po HTTPS. Zaufany <strong>tylko</strong> wtedy, gdy żądanie faktycznie przychodzi z adresu z pola <em>Zaufane IP proxy</em> powyżej, dokładnie jak nagłówek IP klienta — i może wyłącznie dodać „to było HTTPS”, nigdy odebrać tego połączeniu, które naprawdę jest szyfrowane. <code>X-Forwarded-SSL</code> oraz nagłówek <code>Forwarded</code> z RFC 7239 są czytane od tych samych zaufanych adresów.',
    'settings.transport_proto_header_note' => '(puste = całkowicie ignorowany)',
    'settings.transport_title' => 'Bezpieczeństwo transportu (ciasteczka i HSTS)',
    'settings.transport_warn_no_tls' => 'Adres strony zaczyna się od <code>https://</code>, ale serwer WWW nie mówi PHP o szyfrowaniu — więc każde ciasteczko tej strony wychodzi bez <code>Secure</code>. W Apache z <code>mod_ssl</code> dzieje się to samo z siebie, więc ten komunikat oznacza, że szyfrowanie kończy się gdzie indziej. W nginx z php-fpm dodaj te dwie linie do bloku <code>location</code> dla PHP i przeładuj: <code>fastcgi_param HTTPS $https if_not_empty;</code> oraz <code>fastcgi_param REQUEST_SCHEME $scheme;</code>. Jeśli szyfrowanie faktycznie kończy się przed serwerem — na CDN, load balancerze albo w tunelu — wpisz to coś w <em>Zaufane IP proxy</em>; serwer WWW na tej samej maszynie podaje adres gościa jako adres połączenia i nigdy nie jest własnym proxy.',
    'settings.transport_warn_proxy_dropped' => 'Te wpisy w polu <em>Zaufane IP proxy</em> są ignorowane: <code>:entries</code>. Są błędne albo szersze, niż panel dopuszcza — nic z nich nie jest zaufane i nigdy nie było, bo zakres w tym polu do tej wersji nie robił zupełnie nic. Zawęż je albo usuń.',
    'settings.tuner_enabled_hint' => 'Włączenie tylko pokazuje przycisk; przebieg nadal wymaga hasła administratora.',
    'settings.tuner_enabled_opt' => 'Włączona — przycisk pojawia się na stronie Ruch',
    'settings.tuner_hard' => 'Twardy stop',
    'settings.tuner_hard_hint' => 'Bezwzględny bezpiecznik pod całością, na wypadek maszyny naprawdę zajeżdżanej na śmierć. Dużo powyżej wszystkiego, co tu normalne.',
    'settings.tuner_headroom' => 'Obciążenie, jakie przebieg może dodać',
    'settings.tuner_headroom_hint' => 'Przebieg zatrzymuje się, gdy obciążenie wzrośnie o więcej niż tyle <strong>ponad wartość początkową</strong>. Celowo liczone względem bazy: bezwzględny sufit nic nie znaczy na maszynie, której zwykłe obciążenie robocze już jest blisko niego — tak właśnie każdy przebieg tutaj kończył się na pierwszym kroku.',
    'settings.tuner_intro' => 'Znajduje faktyczne granice tej maszyny, przesuwając limit ruchu przychodzącego w kilku krokach i obserwując, co się dzieje — także z <strong>całą resztą na tym serwerze</strong>. Wzór może podpowiedzieć liczbę na podstawie dawnego ruchu; tylko przebieg odpowie na pytanie „czy po podniesieniu tego inne usługi gubią pakiety”, a zwykle o to właśnie chodzi.<br><strong>Domyślnie wyłączone.</strong> Droga powrotna jest zapisywana przed pierwszą zmianą, więc ustawienia wracają nawet gdy przebieg zostanie zabity albo maszyna się zrestartuje — przywraca je janitor. Nic nie jest stosowane automatycznie: przebieg kończy się dokładnie tam, gdzie zaczął, i zostawia raport.',
    'settings.tuner_label' => 'Sonda stabilności',
    'settings.tuner_load_per_core' => '(obciążenie na rdzeń)',
    'settings.tuner_per_core' => '(na rdzeń)',
    'settings.tuner_python' => 'Polecenie Pythona',
    'settings.tuner_python_hint' => 'Czym janitor uruchamia <code>tools/tuner.py</code>. Tylko litery, cyfry i <code>_ . / -</code>.',
    'settings.tuner_title' => 'Sonda stabilności',
    'settings.twofa_hint' => 'Sześciocyfrowy kod z aplikacji uwierzytelniającej (TOTP, RFC&nbsp;6238 — Google Authenticator, Aegis, 1Password, dowolna) oprócz hasła. <strong>Domyślnie wyłączone.</strong> Sekret jest przechowywany w <code>config/admin_2fa.json</code>, obok hasha hasła i z dala od tabeli ustawień, którą zrzuca każda kopia zapasowa. <em>Wyłączenie</em> wymaga hasła <strong>i</strong> aktualnego kodu: to zabezpieczenie na wypadek, gdyby ktoś inny znał hasło — samo hasło nie może go wyłączyć.',
    'settings.twofa_reading' => 'Wczytywanie…',
    'settings.twofa_title' => 'Uwierzytelnianie dwuskładnikowe',
    'settings.users_default_group' => 'Domyślna grupa (slug)',
    'settings.users_default_group_hint' => 'Nadawana każdemu nowemu kontu (plus każda grupa oznaczona jako „domyślna”).',
    'settings.users_email_cooldown' => 'Odstęp między zmianami e-maila (dni)',
    'settings.users_email_cooldown_hint' => 'Po zakończonej zmianie następna jest zablokowana przez tyle dni (ochrona przed przejęciem). 0 = wyłączone. Zmiany zawsze potwierdza się najpierw ze STAREGO adresu, potem z NOWEGO.',
    'settings.users_email_verify' => 'Wymagaj weryfikacji e-mail',
    'settings.users_email_verify_hint' => 'Przy Tak rejestracja wymaga e-maila, a uprawnienia grup obowiązują dopiero po kliknięciu linku potwierdzającego (sama strona konta pozostaje dostępna; administratorzy są zwolnieni).',
    'settings.users_email_verify_no' => 'Nie — grupy obowiązują od razu',
    'settings.users_email_verify_yes' => 'Tak — niezweryfikowane konta działają jak goście',
    'settings.users_expiry_days' => 'Ostrzeżenie o wygaśnięciu (dni)',
    'settings.users_expiry_days_hint' => 'Powiadom (+e-mail, gdy możliwe) tyle dni przed końcem grupy czasowej. 0 = wyłączone.',
    'settings.users_intro_a' => 'Opcjonalny system członkowski: rejestracja + logowanie (chronione CAPTCHA), grupy z uprawnieniami per funkcja, dostęp czasowy (do sprzedaży przez API <code>v1/users/*</code> z kluczem o zakresie <em>users</em>), powiadomienia w panelu i wyszukiwarka w Indeksie dla członków. Użytkownikami i grupami zarządza się na stronie',
    'settings.users_intro_b' => 'Grupa <strong>guest</strong> określa, co widzą anonimowi goście — przy <em>wyłączonych</em> kontach wszystko działa dokładnie jak wcześniej (strony publiczne publiczne, Indeks tylko dla administratora).',
    'settings.users_label' => 'Konta użytkowników',
    'settings.users_links' => 'Linki logowania / rejestracji',
    'settings.users_links_hidden' => 'Ukryte (tylko bezpośredni URL)',
    'settings.users_links_hint' => 'Ukryte: <code>?action=login</code> / <code>?action=register</code> nadal działają.',
    'settings.users_links_visible' => 'Widoczne w menu',
    'settings.users_page_link' => 'Użytkownicy',
    'settings.users_registration' => 'Rejestracja publiczna',
    'settings.users_registration_closed' => 'Zamknięta (tylko admin / API)',
    'settings.users_registration_hint' => 'Rejestracja zawsze wymaga skonfigurowanej CAPTCHA.',
    'settings.users_registration_open' => 'Otwarta',
    'settings.users_rl_login' => 'Logowań / 15 min (per IP)',
    'settings.users_rl_preview' => 'Podglądów opisu / min (per IP)',
    'settings.users_rl_preview_hint' => 'Przycisk Podgląd renderuje na serwerze, bo tylko tam da się zagwarantować wynik — a to czyni z niego parser, który każdy może wywołać.',
    'settings.users_rl_register' => 'Rejestracji / godzinę (per IP)',
    'settings.users_rl_search' => 'Wyszukiwań / godzinę (per IP)',
    'settings.users_search' => 'Wyszukiwarka dla członków',
    'settings.users_search_budget' => 'Limit czasu wyszukiwania',
    'settings.users_search_budget_hint' => 'Sekundy, przez które wyszukiwanie w katalogu może działać, zanim PHP je przerwie. Na dużym katalogu podnieś: zapytanie ucięte własnym limitem serwera wraca jako goły błąd 500, bez śladu w logu. 10–300.',
    'settings.users_search_disabled' => 'Wyłączona (nawet z uprawnieniami)',
    'settings.users_search_hint' => 'Główny przełącznik dla <code>?action=search</code> — nadrzędny wobec uprawnień <code>index.view</code>.',
    'settings.users_search_note' => 'Wyszukiwarka Indeksu dla członków (<code>?action=search</code>).',
    'settings.users_search_whitelist' => 'Whitelista w wynikach wyszukiwania',
    'settings.users_search_whitelist_hint' => 'Czy zarejestrowane (whitelistowane) torrenty mogą pojawiać się w wyszukiwarce dla członków.',
    'settings.users_search_whitelist_no' => 'Nigdy nie pokazywana',
    'settings.users_search_whitelist_yes' => 'Uwzględniona (wymaga whitelist.view)',
    'settings.users_share' => 'Przyciski „Udostępnij”',
    'settings.users_share_hint' => 'Daje przycisk kopiujący link do bieżącego wyszukiwania i drugi kopiujący link do pojedynczego torrenta. Widok i tak jest w adresie — to decyduje tylko o tym, czy strona poda ten link za ciebie.',
    'settings.users_terms' => 'Regulamin rejestracji',
    'settings.users_terms_hint' => '(puste = pole wyboru linkuje do <code>?action=tos</code>)',
    'settings.users_terms_note' => 'Rejestracja zawsze wymaga zaznaczenia pola „Akceptuję regulamin”; to ustawienie decyduje tylko o tym, co pokazuje link.',
    'settings.users_terms_ph' => 'Zwykły tekst pokazywany w oknie, gdy użytkownik kliknie link regulaminu w formularzu rejestracji.',
    'settings.users_title' => 'Konta użytkowników',
    'settings.version_both' => 'Wszędzie',
    'settings.version_none' => 'Nigdzie',
    'settings.version_panel' => 'Tylko w panelu',
    'settings.version_public' => 'Tylko na stronach publicznych',
    'settings.version_where' => 'Pokazuj wersję',
    'settings.version_where_hint' => 'Ta wersja to <code>:v</code>. Domyślnie tylko panel: opiekun serwisu wie, który build odpowiada, a numer wersji na stronie publicznej mówi głównie tyle, których opisanych błędów spróbować.',
    'settings.whitelist_daily_cap' => 'Nowych hashy / dzień (limit globalny)',
    'settings.whitelist_disabled' => 'Wyłączona',
    'settings.whitelist_enabled' => 'Włączona',
    'settings.whitelist_intro_black' => '<strong>Blacklista</strong> = OpenTracker zbudowany z <code>-DWANT_ACCESSLIST_BLACK</code>: obsługiwane jest wszystko poza zablokowanymi hashami.',
    'settings.whitelist_intro_match' => 'Tryb musi zgadzać się ze skompilowanym plikiem binarnym i jego linią konfiguracji <code>access.whitelist</code> / <code>access.blacklist</code>.',
    'settings.whitelist_intro_white' => '<strong>Whitelista</strong> = zbudowany z <code>-DWANT_ACCESSLIST_WHITE</code>: obsługiwane są <em>tylko</em> zarejestrowane hashe (publiczna strona rejestracji, synchronizacja z forum, API).',
    'settings.whitelist_ip_daily_max' => 'Nowych hashy / dzień (na IP)',
    'settings.whitelist_manage_hint' => 'Samą listą (przeglądanie, dodawanie, banowanie, regeneracja pliku) zarządzasz na',
    'settings.whitelist_manage_link' => 'stronie Whitelista',
    'settings.whitelist_max_per_submission' => 'Maks. hashy na zgłoszenie',
    'settings.whitelist_mode_blacklist' => 'Blacklista (klasyczny)',
    'settings.whitelist_mode_hint' => 'Zapis zmienia tylko tryb aplikacji webowej. Binarkę/konfigurację OpenTrackera podmienia <code>tracker-mode.sh white|black</code> (uruchamiany z harmonogramu lub ręcznie przez SSH).',
    'settings.whitelist_mode_sched_warn' => '<strong>Tryb harmonogramu jest WŁĄCZONY</strong> — janitor w ciągu minuty ponownie nakłada tryb z harmonogramu, więc ręcznie zapisany tryb zostanie cofnięty. Aby przełączyć ręcznie, najpierw wyłącz poniżej Harmonogram trybu trackera (i pamiętaj, że samo ustawienie nie podmienia binarki OpenTrackera — robi to harmonogram / <code>tracker-mode.sh</code>).',
    'settings.whitelist_mode_whitelist' => 'Whitelista (wymagana rejestracja)',
    'settings.whitelist_path' => 'Ścieżka pliku whitelisty',
    'settings.whitelist_path_small' => '(poza katalogiem WWW; katalog zapisywalny przez PHP, np. <code>/home/tracker/accesslist/whitelist</code>)',
    'settings.whitelist_public_enabled' => 'Publiczna strona rejestracji',
    'settings.whitelist_rate_limit' => 'Zgłoszeń / godz. (na IP)',
    'settings.whitelist_reload_min_interval' => 'Min. sekund między przeładowaniami',
    'settings.whitelist_reload_min_interval_small' => '(dodania; usunięcia przeładowują szybciej)',
