    'settings.wl_submitter_hint' => 'Pozwala członkowi pokazywać zarejestrowane torrenty na profilu i wybierać osobno dla każdego. Decyduje o tym, na czyim profilu wiersz się pojawia — nigdy o tym, co serwuje tracker ani co znajduje wyszukiwarka.',
    'settings.wlupkeep_dead_action' => 'Co z nimi zrobić',
    'settings.wlupkeep_dead_action_hint' => '<strong>Oznaczanie jest domyślne celowo.</strong> Automat usuwający cudze rejestracje to coś, co operator powinien wybrać wprost, a nie odziedziczyć.',
    'settings.wlupkeep_dead_after' => 'Uznaj torrent za martwy po (dniach)',
    'settings.wlupkeep_dead_after_hint' => '0 = wył. Liczone od ostatniego scrape\'u, który pokazał <strong>zero seedów i zero leecherów</strong>. Wiersz, który nigdy nie był scrape\'owany, <em>nigdy</em> nie jest liczony — brak danych to nie brak peerów, a różnica ma największe znaczenie, gdy ścieżka scrape jest zepsuta, czyli dokładnie wtedy, gdy reguła „usuń przy zerze” opróżniłaby listę.',
    'settings.wlupkeep_dead_delete' => 'Usuń je',
    'settings.wlupkeep_dead_every' => 'Przebieg martwych co (dni)',
    'settings.wlupkeep_dead_mark' => 'Oznacz — nic nie jest usuwane',
    'settings.wlupkeep_dead_none' => 'Nic',
    'settings.wlupkeep_intro' => 'Whitelista rośnie. Ktoś rejestruje torrent, seeduje go tydzień i idzie dalej, a po latach tracker wciąż obsługuje rój, w którym nikogo nie ma. Oba zadania poniżej uruchamia <strong>janitor</strong>, nigdy odsłona strony, i oba są <strong>domyślnie wyłączone</strong>.',
    'settings.wlupkeep_match_many' => 'Przy obecnych ustawieniach ta reguła pasuje teraz do <strong>:n</strong> wierszy.',
    'settings.wlupkeep_match_one' => 'Przy obecnych ustawieniach ta reguła pasuje teraz do <strong>:n</strong> wiersza.',
    'settings.wlupkeep_match_unset' => 'Podaj liczbę dni powyżej, aby zobaczyć, do ilu wierszy pasowałaby reguła.',
    'settings.wlupkeep_scrape_batch' => 'Wierszy na przebieg',
    'settings.wlupkeep_scrape_batch_hint' => 'Każdy wiersz to żądanie scrape do własnego trackera. Janitor działa co minutę.',
    'settings.wlupkeep_scrape_every' => 'Odświeżaj S/L co (godzin)',
    'settings.wlupkeep_scrape_every_hint' => '0 = nigdy. Wiersze brane są od najstarszych, więc lista większa niż jedna partia jest pokrywana równomiernie, zamiast odświeżać w nieskończoność te same pierwsze dwieście wierszy.',
