    'title.unsubscribe' => 'Wypisanie się',
    'title.verify' => 'Weryfikacja adresu e-mail',
    'title.whitelist' => 'Whitelista',
    'tos.acc1' => 'Założenie konta jest darmowe i nieobowiązkowe — sam tracker działa bez niego. Konto odblokowuje jedynie funkcje dla zalogowanych (na przykład wyszukiwarkę katalogu), zgodnie z przyznanymi mu grupami.',
    'tos.acc2' => 'Dla konta przechowujemy: nazwę użytkownika, hasło (jako solony skrót — nigdy otwartym tekstem), adres e-mail:email, adresy IP użyte przy rejestracji i logowaniu (zapobieganie nadużyciom), przynależność do grup wraz z datami wygaśnięcia oraz powiadomienia w serwisie.',
    'tos.acc2_opt' => ' (opcjonalny)',
    'tos.acc2_req' => ' (wymagany i potwierdzany linkiem weryfikacyjnym)',
    'tos.acc3' => 'Adresy e-mail służą wyłącznie obsłudze konta: linkom weryfikacyjnym, resetom hasła, potwierdzeniom zmiany adresu oraz powiadomieniom o wygaśnięciu i bezpieczeństwie. Powiadomienia o koncie można wyłączyć na stronie konta; nigdy nie udostępniamy adresów stronom trzecim.',
    'tos.acc4' => 'Zmiana adresu e-mail konta wymaga potwierdzenia z obecnego adresu, a następnie z nowego; między zmianami obowiązuje okres karencji. Chroni to konta przed przejęciem.',
    'tos.acc5' => 'Ciasteczka sesji (oraz opcjonalny token „pozostań zalogowany”) są ściśle funkcjonalne. Czas trwania sesji wybierasz przy logowaniu; tokeny przechowujemy wyłącznie jako skróty i unieważnia je zmiana hasła lub wylogowanie.',
    'tos.acc6' => 'Konta wykorzystywane do nadużyć (spam, ataki na usługę, celowe rejestrowanie naruszających treści mimo ostrzeżeń) mogą zostać zawieszone lub usunięte wraz z ich wpisami na whiteliście.',
    'tos.acc7' => 'Aby usunąć konto i jego dane, napisz na adres serwisu z adresu przypisanego do konta (albo skorzystaj z formularza zgłoszeń). Przeczytane powiadomienia są automatycznie usuwane po 90 dniach.',
    'tos.acc8' => 'Wyszukiwarka indeksu jest funkcją dla zalogowanych. Frazy nie są przechowywane dłużej niż żądanie; wyniki odzwierciedlają to, co tracker zaobserwował, nie to, co hostujemy — nie hostujemy niczego.',
    'tos.acc_head' => 'Konta użytkowników',
    'tos.h1' => 'Regulamin',
    'tos.intro' => 'Korzystając z tego trackera, akceptujesz poniższy regulamin:',
    'tos.lang1' => 'Wybór języka przełącznikiem ustawia ciasteczko <code>lang</code> tylko na czas sesji przeglądarki; zawiera dwuliterowy kod i nic więcej. Zalogowane konto może zapisać preferowany język, przechowywany razem z kontem.',
    'tos.lang_head' => 'Języki i ciasteczka',
    'tos.r1' => 'Usługa jest darmowa do użytku osobistego. Organizacje komercyjne potrzebują pisemnej zgody.',
    'tos.r2' => 'Śledzenie użytkowników, ataki DoS/DDoS i wszelkie próby zakłócenia usługi są zabronione.',
    'tos.r3' => 'Nie gwarantujemy ciągłości działania usługi. Dostępność może zostać ograniczona bez uprzedzenia.',
    'tos.r4' => 'Użytkownik ponosi pełną odpowiedzialność za legalność udostępnianych treści w swojej jurysdykcji.',
    'tos.r5' => 'Naruszenie zasad użytku komercyjnego podlega opłacie w wysokości 5000 EUR.',
    'tos.r6' => 'Zastrzegamy sobie prawo do publikowania informacji o naruszeniach regulaminu.',
    'tos.r7' => 'Szanujemy prywatność użytkowników. Nie przechowujemy danych osobowych ponad to, co jest niezbędne do działania trackera.',
    'tos.r8' => 'Regulamin może się zmienić. Dalsze korzystanie z usługi oznacza akceptację zmian.',
    'tos.r9' => '<strong>Połączenie z trackerem oznacza akceptację niniejszego regulaminu.</strong>',
    'tos.r_index' => 'Tracker prowadzi <strong>indeks</strong> zaobserwowanych info hashy wraz z nazwą torrenta i listą plików pobraną z roju, aby zgłoszenia dało się dopasować do treści. Żadne pliki nie są pobierane ani przechowywane; wpisy wygasają, gdy rój cichnie.',
    'tos.r_wl' => 'Rejestracje na whiteliście są darmowe i anonimowe; adres IP zgłaszającego jest zapisywany w celu wykrywania nadużyć. Zarejestrowane info hashe mogą zostać w każdej chwili usunięte lub zbanowane, a zgłaszający nadużycia — zablokowani.',
    'transparency.blocked' => 'Zablokowanych',
