    'whitelist.announce_head' => 'Adresy announce',
    'whitelist.announce_note' => 'Dodaj je do swojego torrenta / magneta (<code>&amp;tr=</code>), aby peery znajdowały się nawzajem przez ten tracker:',
    'whitelist.anon' => 'Ten tracker obsługuje <strong>wyłącznie zarejestrowane torrenty</strong>:hours. Rejestracja jest <strong>darmowa i anonimowa</strong> — wklej jeden lub więcej linków magnet (albo same 40-znakowe info hashe), :captcha, a hashe zostaną dodane do whitelisty. Torrenty publikowane na forum społecznościowym rejestrują się automatycznie.',
    'whitelist.captcha_std' => 'rozwiąż CAPTCHĘ',
